class ConditionalIndependenceModelManager:
    """
    Comprehensive statistical independence testing framework with 15+ methods
    Combines classical statistics, information theory, and modern ML approaches
    """
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.logger = logging.getLogger(__name__)
        
        # Test configuration
        self.alpha = self.config.get('significance_level', 0.05)
        self.bootstrap_samples = self.config.get('bootstrap_samples', 1000)
        self.permutation_samples = self.config.get('permutation_samples', 500)
        self.use_gpu = self.config.get('use_gpu', HAS_CUPY and torch.cuda.is_available())
        
        # Initialize test engines
        self.gpu_engine = None
        if self.use_gpu:
            self.gpu_engine = GPUAcceleratedIndependenceTestingEngine()
            
        self.gnn_engine = None
        if HAS_TORCH_GEOMETRIC:
            self.gnn_engine = GNNIndependenceTestingEngine()
            
        # Cache for test results
        self.test_cache = {}
        self.performance_stats = defaultdict(list)
        
        # Initialize individual test components
        self._initialize_test_components()
    
    def _initialize_test_components(self):
        """Initialize all statistical test components"""
        try:
            # Kernel methods
            self.kernel_methods = KernelIndependenceTests()
            
            # Information theoretic methods  
            self.info_theory_methods = InformationTheoreticTests()
            
            # Distance-based methods
            self.distance_methods = DistanceBasedTests()
            
            # Copula methods
            self.copula_methods = CopulaIndependenceTests()
            
            # Time series methods
            self.timeseries_methods = TimeSeriesIndependenceTests()
            
            # Bayesian methods
            self.bayesian_methods = BayesianIndependenceTests()
            
            self.logger.info("All statistical test components initialized")
            
        except Exception as e:
            self.logger.error(f"Failed to initialize test components: {e}")
    
    async def test_conditional_independence(self, X: np.ndarray, Y: np.ndarray, Z: np.ndarray = None,
                                         method: str = 'comprehensive', 
                                         return_detailed: bool = True) -> Dict[str, Any]:
        """
        Test conditional independence X ⊥ Y | Z using multiple methods
        
        Args:
            X: First variable (n_samples x n_features_X)
            Y: Second variable (n_samples x n_features_Y)  
            Z: Conditioning set (n_samples x n_features_Z), optional
            method: Test method ('comprehensive', 'fast', 'specific_test_name')
            return_detailed: Return detailed results from all tests
            
        Returns:
            Dictionary with test results, p-values, and confidence measures
        """
        
        start_time = time.time()
        
        with performance_monitor.timer(f"independence_test_{method}"):
            # Validate inputs
            X, Y, Z = self._validate_and_preprocess_inputs(X, Y, Z)
            
            # Generate cache key
            cache_key = self._generate_cache_key(X, Y, Z, method)
            if cache_key in self.test_cache:
                return self.test_cache[cache_key]
            
            # Select test strategy
            if method == 'comprehensive':
                results = await self._comprehensive_independence_analysis(X, Y, Z)
            elif method == 'fast':
                results = await self._fast_independence_analysis(X, Y, Z) 
            elif method == 'temporal':
                results = await self._advanced_temporal_independence_analysis(X, Y, Z)
            elif method == 'gpu_accelerated':
                results = await self._gpu_accelerated_testing(X, Y, Z)
            else:
                # Single specific test
                results = await self._single_test_analysis(X, Y, Z, method)
            
            # Add metadata
            results['test_metadata'] = {
                'method': method,
                'data_shapes': {'X': X.shape, 'Y': Y.shape, 'Z': Z.shape if Z is not None else None},
                'computation_time_seconds': time.time() - start_time,
                'cache_key': cache_key,
                'gpu_used': self.use_gpu and results.get('gpu_tests_performed', False)
            }
            
            # Cache results
            self.test_cache[cache_key] = results
            
            # Update performance statistics
            self.performance_stats[method].append(time.time() - start_time)
            
            return results
    
    def _validate_and_preprocess_inputs(self, X: np.ndarray, Y: np.ndarray, 
                                      Z: Optional[np.ndarray]) -> Tuple[np.ndarray, np.ndarray, Optional[np.ndarray]]:
        """Validate and preprocess input data"""
        
        # Convert to numpy arrays
        X = np.asarray(X)
        Y = np.asarray(Y)
        if Z is not None:
            Z = np.asarray(Z)
        
        # Ensure 2D arrays
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        if Y.ndim == 1:
            Y = Y.reshape(-1, 1)
        if Z is not None and Z.ndim == 1:
            Z = Z.reshape(-1, 1)
        
        # Validate sample sizes
        n_samples = X.shape[0]
        if Y.shape[0] != n_samples:
            raise ValueError("X and Y must have same number of samples")
        if Z is not None and Z.shape[0] != n_samples:
            raise ValueError("Z must have same number of samples as X and Y")
        
        # Handle missing values
        if np.any(np.isnan(X)) or np.any(np.isnan(Y)) or (Z is not None and np.any(np.isnan(Z))):
            self.logger.warning("Missing values detected, using complete cases")
            if Z is not None:
                combined = np.hstack([X, Y, Z])
                valid_idx = ~np.any(np.isnan(combined), axis=1)
                X, Y, Z = X[valid_idx], Y[valid_idx], Z[valid_idx]
            else:
                combined = np.hstack([X, Y])
                valid_idx = ~np.any(np.isnan(combined), axis=1)
                X, Y = X[valid_idx], Y[valid_idx]
        
        return X, Y, Z
    
    def _generate_cache_key(self, X: np.ndarray, Y: np.ndarray, Z: Optional[np.ndarray], method: str) -> str:
        """Generate cache key for test results"""
        
        # Create hash of data and parameters
        hasher = hashlib.sha256()
        hasher.update(X.tobytes())
        hasher.update(Y.tobytes())
        if Z is not None:
            hasher.update(Z.tobytes())
        hasher.update(method.encode())
        hasher.update(str(self.alpha).encode())
        
        return hasher.hexdigest()[:16]
    
    async def _comprehensive_independence_analysis(self, X: np.ndarray, Y: np.ndarray, 
                                                 Z: Optional[np.ndarray]) -> Dict[str, Any]:
        """Comprehensive independence analysis using all available methods"""
        
        results = {
            'independence_decision': None,
            'confidence': 0.0,
            'p_value': 1.0,
            'test_statistics': {},
            'individual_tests': {},
            'method_weights': {},
            'bayesian_evidence': {},
            'ensemble_results': {}
        }
        
        # 1. Classical Statistical Tests
        classical_tests = await self._run_classical_tests(X, Y, Z)
        results['individual_tests'].update(classical_tests)
        
        # 2. Kernel-based Tests
        if hasattr(self, 'kernel_methods'):
            kernel_tests = await self._run_kernel_tests(X, Y, Z)
            results['individual_tests'].update(kernel_tests)
        
        # 3. Information-theoretic Tests
        if hasattr(self, 'info_theory_methods'):
            info_tests = await self._run_information_tests(X, Y, Z)
            results['individual_tests'].update(info_tests)
        
        # 4. Distance-based Tests
        if hasattr(self, 'distance_methods'):
            distance_tests = await self._run_distance_tests(X, Y, Z)
            results['individual_tests'].update(distance_tests)
        
        # 5. Copula-based Tests
        if hasattr(self, 'copula_methods'):
            copula_tests = await self._run_copula_tests(X, Y, Z)
            results['individual_tests'].update(copula_tests)
        
        # 6. Time Series Tests (if data has temporal structure)
        if self._is_temporal_data(X, Y):
            temporal_tests = await self._run_temporal_tests(X, Y, Z)
            results['individual_tests'].update(temporal_tests)
        
        # 7. GPU-accelerated Tests
        if self.gpu_engine:
            gpu_tests = await self._run_gpu_tests(X, Y, Z)
            results['individual_tests'].update(gpu_tests)
            results['gpu_tests_performed'] = True
        
        # 8. Graph Neural Network Tests
        if self.gnn_engine:
            gnn_tests = await self._run_gnn_tests(X, Y, Z)
            results['individual_tests'].update(gnn_tests)
        
        # 9. Bayesian Model Averaging
        bayesian_results = await self._bayesian_model_averaging(results['individual_tests'])
        results['bayesian_evidence'] = bayesian_results
        
        # 10. Ensemble Decision Making
        ensemble_decision = await self._ensemble_decision_making(results['individual_tests'])
        results['ensemble_results'] = ensemble_decision
        
        # Final decision and confidence
        results['independence_decision'] = ensemble_decision['final_decision']
        results['confidence'] = ensemble_decision['confidence']
        results['p_value'] = ensemble_decision['combined_p_value']
        
        return results
    
    async def _run_classical_tests(self, X: np.ndarray, Y: np.ndarray, Z: Optional[np.ndarray]) -> Dict[str, Any]:
        """Run classical statistical independence tests"""
        
        tests = {}
        
        try:
            # 1. Partial Correlation Test (for continuous variables)
            if Z is not None:
                partial_corr_result = self._partial_correlation_test(X, Y, Z)
                tests['partial_correlation'] = partial_corr_result
            
            # 2. Pearson Correlation Test
            pearson_result = self._pearson_correlation_test(X, Y)
            tests['pearson_correlation'] = pearson_result
            
            # 3. Spearman Rank Correlation
            spearman_result = self._spearman_correlation_test(X, Y)
            tests['spearman_correlation'] = spearman_result
            
            # 4. Kendall's Tau
            kendall_result = self._kendall_tau_test(X, Y)
            tests['kendall_tau'] = kendall_result
            
            # 5. Chi-square Test (for categorical variables)
            if self._is_categorical_data(X, Y):
                chi_square_result = self._chi_square_test(X, Y)
                tests['chi_square'] = chi_square_result
            
            # 6. Fisher's Exact Test (for 2x2 contingency tables)
            if self._is_binary_data(X, Y):
                fisher_result = self._fisher_exact_test(X, Y)
                tests['fisher_exact'] = fisher_result
                
        except Exception as e:
            self.logger.error(f"Error in classical tests: {e}")
            
        return tests
    
    def _partial_correlation_test(self, X: np.ndarray, Y: np.ndarray, Z: np.ndarray) -> Dict[str, Any]:
        """Partial correlation test for conditional independence"""
        try:
            # Flatten variables for correlation computation
            x_flat = X.flatten() if X.shape[1] == 1 else X[:, 0]
            y_flat = Y.flatten() if Y.shape[1] == 1 else Y[:, 0]
            z_flat = Z.flatten() if Z.shape[1] == 1 else Z[:, 0]
            
            # Compute correlation matrix
            data_matrix = np.column_stack([x_flat, y_flat, z_flat])
            corr_matrix = np.corrcoef(data_matrix.T)
            
            # Compute partial correlation
            if np.linalg.det(corr_matrix) != 0:
                inv_corr = np.linalg.inv(corr_matrix)
                partial_corr = -inv_corr[0, 1] / np.sqrt(inv_corr[0, 0] * inv_corr[1, 1])
            else:
                partial_corr = 0.0
            
            # Test statistic and p-value
            n = len(x_flat)
            df = n - 3 - Z.shape[1] + 1
            
            if df > 0 and abs(partial_corr) < 1:
                t_stat = partial_corr * np.sqrt(df / (1 - partial_corr**2))
                p_value = 2 * (1 - stats.t.cdf(abs(t_stat), df))
            else:
                t_stat = 0.0
                p_value = 1.0
            
            return {
                'test_statistic': float(partial_corr),
                't_statistic': float(t_stat),
                'p_value': float(p_value),
                'degrees_of_freedom': int(df),
                'significant': p_value < self.alpha,
                'method': 'partial_correlation'
            }
            
        except Exception as e:
            self.logger.error(f"Partial correlation test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False, 'error': str(e)}
    
    def _pearson_correlation_test(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """Pearson correlation test"""
        try:
            x_flat = X.flatten() if X.shape[1] == 1 else X[:, 0]
            y_flat = Y.flatten() if Y.shape[1] == 1 else Y[:, 0]
            
            corr, p_value = stats.pearsonr(x_flat, y_flat)
            
            return {
                'test_statistic': float(corr),
                'p_value': float(p_value),
                'significant': p_value < self.alpha,
                'method': 'pearson_correlation'
            }
            
        except Exception as e:
            self.logger.error(f"Pearson correlation test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False, 'error': str(e)}
    
    def _spearman_correlation_test(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """Spearman rank correlation test"""
        try:
            x_flat = X.flatten() if X.shape[1] == 1 else X[:, 0]
            y_flat = Y.flatten() if Y.shape[1] == 1 else Y[:, 0]
            
            corr, p_value = stats.spearmanr(x_flat, y_flat)
            
            return {
                'test_statistic': float(corr),
                'p_value': float(p_value),
                'significant': p_value < self.alpha,
                'method': 'spearman_correlation'
            }
            
        except Exception as e:
            self.logger.error(f"Spearman correlation test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False, 'error': str(e)}
    
    def _kendall_tau_test(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """Kendall's tau correlation test"""
        try:
            x_flat = X.flatten() if X.shape[1] == 1 else X[:, 0]
            y_flat = Y.flatten() if Y.shape[1] == 1 else Y[:, 0]
            
            tau, p_value = stats.kendalltau(x_flat, y_flat)
            
            return {
                'test_statistic': float(tau),
                'p_value': float(p_value), 
                'significant': p_value < self.alpha,
                'method': 'kendall_tau'
            }
            
        except Exception as e:
            self.logger.error(f"Kendall tau test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False, 'error': str(e)}
    
    def _is_categorical_data(self, X: np.ndarray, Y: np.ndarray) -> bool:
        """Check if data appears to be categorical"""
        x_unique = len(np.unique(X.flatten()))
        y_unique = len(np.unique(Y.flatten()))
        n_samples = X.shape[0]
        
        # Consider categorical if number of unique values is small relative to sample size
        return (x_unique < min(20, n_samples/5) and y_unique < min(20, n_samples/5))
    
    def _is_binary_data(self, X: np.ndarray, Y: np.ndarray) -> bool:
        """Check if data is binary"""
        x_unique = len(np.unique(X.flatten()))
        y_unique = len(np.unique(Y.flatten()))
        
        return x_unique == 2 and y_unique == 2
    
    def _chi_square_test(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """Chi-square test for categorical independence"""
        try:
            x_flat = X.flatten().astype(int)
            y_flat = Y.flatten().astype(int)
            
            # Create contingency table
            contingency_table = pd.crosstab(x_flat, y_flat).values
            
            # Chi-square test
            chi2, p_value, dof, expected = stats.chi2_contingency(contingency_table)
            
            return {
                'test_statistic': float(chi2),
                'p_value': float(p_value),
                'degrees_of_freedom': int(dof),
                'significant': p_value < self.alpha,
                'method': 'chi_square'
            }
            
        except Exception as e:
            self.logger.error(f"Chi-square test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False, 'error': str(e)}
    
    def _fisher_exact_test(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """Fisher's exact test for 2x2 contingency tables"""
        try:
            x_flat = X.flatten().astype(int)
            y_flat = Y.flatten().astype(int)
            
            # Create 2x2 contingency table
            contingency_table = pd.crosstab(x_flat, y_flat).values
            
            if contingency_table.shape == (2, 2):
                odds_ratio, p_value = stats.fisher_exact(contingency_table)
                
                return {
                    'test_statistic': float(odds_ratio),
                    'p_value': float(p_value),
                    'significant': p_value < self.alpha,
                    'method': 'fisher_exact'
                }
            else:
                return {'test_statistic': 1.0, 'p_value': 1.0, 'significant': False, 
                       'error': 'Not a 2x2 table'}
                
        except Exception as e:
            self.logger.error(f"Fisher exact test failed: {e}")
            return {'test_statistic': 1.0, 'p_value': 1.0, 'significant': False, 'error': str(e)}
    
    def _is_temporal_data(self, X: np.ndarray, Y: np.ndarray) -> bool:
        """Check if data has temporal structure"""
        # Simple heuristic: if data looks like it could be time series
        n_samples = X.shape[0]
        
        # Check for temporal ordering (basic autocorrelation test)
        if n_samples > 10:
            try:
                x_flat = X.flatten() if X.shape[1] == 1 else X[:, 0]
                autocorr = np.corrcoef(x_flat[:-1], x_flat[1:])[0, 1]
                return abs(autocorr) > 0.1  # Some temporal structure
            except:
                return False
        return False
    
    async def _fast_independence_analysis(self, X: np.ndarray, Y: np.ndarray, 
                                        Z: Optional[np.ndarray]) -> Dict[str, Any]:
        """Fast independence analysis using subset of efficient tests"""
        
        results = {
            'independence_decision': None,
            'confidence': 0.0,
            'p_value': 1.0,
            'individual_tests': {}
        }
        
        # Run only fast tests
        tests_to_run = ['pearson_correlation', 'spearman_correlation']
        
        if Z is not None:
            tests_to_run.append('partial_correlation')
            
        if self._is_categorical_data(X, Y):
            tests_to_run.append('chi_square')
        
        # Run tests in parallel
        test_futures = []
        for test_name in tests_to_run:
            if test_name == 'pearson_correlation':
                test_futures.append(self._pearson_correlation_test(X, Y))
            elif test_name == 'spearman_correlation':
                test_futures.append(self._spearman_correlation_test(X, Y))
            elif test_name == 'partial_correlation':
                test_futures.append(self._partial_correlation_test(X, Y, Z))
            elif test_name == 'chi_square':
                test_futures.append(self._chi_square_test(X, Y))
        
        # Combine results
        for i, test_name in enumerate(tests_to_run):
            results['individual_tests'][test_name] = test_futures[i]
        
        # Simple majority voting for fast decision
        significant_count = sum(1 for test in results['individual_tests'].values() 
                              if test.get('significant', False))
        total_tests = len(results['individual_tests'])
        
        results['independence_decision'] = significant_count < total_tests / 2
        results['confidence'] = 1.0 - (significant_count / total_tests)
        results['p_value'] = np.mean([test.get('p_value', 1.0) 
                                    for test in results['individual_tests'].values()])
        
        return results
    
    async def _bayesian_model_averaging(self, individual_tests: Dict[str, Any]) -> Dict[str, Any]:
        """Bayesian model averaging for combining test results"""
        
        try:
            p_values = []
            weights = []
            
            # Define weights for different test methods
            method_weights = {
                'partial_correlation': 1.0,
                'pearson_correlation': 0.8,
                'spearman_correlation': 0.9,
                'kendall_tau': 0.8,
                'mutual_information': 1.2,
                'hsic_test': 1.1,
                'distance_correlation': 1.0,
                'chi_square': 0.7,
                'fisher_exact': 0.7
            }
            
            for test_name, test_result in individual_tests.items():
                if 'p_value' in test_result and not np.isnan(test_result['p_value']):
                    p_values.append(test_result['p_value'])
                    weights.append(method_weights.get(test_name, 0.5))
            
            if not p_values:
                return {'combined_p_value': 1.0, 'bayes_factor': 1.0, 'evidence': 'no_tests'}
            
            p_values = np.array(p_values)
            weights = np.array(weights)
            weights = weights / np.sum(weights)  # Normalize weights
            
            # Compute Bayes factors (approximate)
            # BF = P(data|H1) / P(data|H0) where H0: independence, H1: dependence
            log_bf = 0.0
            for p_val, weight in zip(p_values, weights):
                # Convert p-value to approximate Bayes factor
                if p_val > 0 and p_val < 1:
                    bf_i = -np.log(p_val) if p_val < 0.5 else np.log(p_val)
                    log_bf += weight * bf_i
            
            bayes_factor = np.exp(log_bf)
            
            # Combined p-value using weighted Fisher's method
            chi2_stat = -2 * np.sum(weights * np.log(np.maximum(p_values, 1e-10)))
            combined_p_value = 1 - stats.chi2.cdf(chi2_stat, 2 * len(p_values))
            
            # Evidence interpretation
            if bayes_factor > 10:
                evidence = 'strong_dependence'
            elif bayes_factor > 3:
                evidence = 'moderate_dependence'
            elif bayes_factor < 0.1:
                evidence = 'strong_independence'
            elif bayes_factor < 0.33:
                evidence = 'moderate_independence'
            else:
                evidence = 'inconclusive'
            
            return {
                'combined_p_value': float(combined_p_value),
                'bayes_factor': float(bayes_factor),
                'evidence': evidence,
                'individual_p_values': p_values.tolist(),
                'weights': weights.tolist(),
                'effective_tests': len(p_values)
            }
            
        except Exception as e:
            self.logger.error(f"Bayesian model averaging failed: {e}")
            return {'combined_p_value': 1.0, 'bayes_factor': 1.0, 'evidence': 'error', 'error': str(e)}
    
    async def _ensemble_decision_making(self, individual_tests: Dict[str, Any]) -> Dict[str, Any]:
        """Ensemble decision making combining all test results"""
        
        try:
            # Collect all p-values and significance decisions
            p_values = []
            significance_votes = []
            test_weights = []
            
            for test_name, test_result in individual_tests.items():
                if isinstance(test_result, dict) and 'p_value' in test_result:
                    p_values.append(test_result['p_value'])
                    significance_votes.append(test_result.get('significant', False))
                    
                    # Weight different test types
                    if 'mutual_information' in test_name or 'hsic' in test_name:
                        test_weights.append(1.2)  # Higher weight for advanced tests
                    elif 'correlation' in test_name:
                        test_weights.append(1.0)  # Standard weight for correlation tests
                    else:
                        test_weights.append(0.8)  # Lower weight for simple tests
            
            if not p_values:
                return {
                    'final_decision': True,  # Independence by default
                    'confidence': 0.0,
                    'combined_p_value': 1.0,
                    'voting_summary': {'error': 'no_valid_tests'}
                }
            
            p_values = np.array(p_values)
            test_weights = np.array(test_weights)
            test_weights = test_weights / np.sum(test_weights)  # Normalize
            
            # Multiple combination methods
            
            # 1. Weighted majority voting
            weighted_significant = np.sum([w for w, sig in zip(test_weights, significance_votes) if sig])
            voting_confidence = abs(0.5 - weighted_significant)
            
            # 2. Fisher's combined p-value
            if np.all(p_values > 0):
                fisher_chi2 = -2 * np.sum(np.log(p_values))
                fisher_p_value = 1 - stats.chi2.cdf(fisher_chi2, 2 * len(p_values))
            else:
                fisher_p_value = 0.0
            
            # 3. Stouffer's Z-score method
            z_scores = stats.norm.ppf(1 - p_values / 2) * np.sign(0.5 - p_values)  # Two-tailed
            combined_z = np.sum(test_weights * z_scores) / np.sqrt(np.sum(test_weights**2))
            stouffer_p_value = 2 * (1 - stats.norm.cdf(abs(combined_z)))
            
            # 4. Harmonic mean p-value
            hmean_p_value = len(p_values) / np.sum(1.0 / np.maximum(p_values, 1e-10))
            
            # Final decision using multiple criteria
            combined_p_values = [fisher_p_value, stouffer_p_value, hmean_p_value]
            final_p_value = np.median(combined_p_values)  # Robust central tendency
            
            # Independence decision (null hypothesis: independence)
            independence_decision = final_p_value > self.alpha
            
            # Confidence based on consistency of methods
            p_value_consistency = 1.0 - np.std(combined_p_values) / (np.mean(combined_p_values) + 1e-10)
            vote_consistency = 1.0 - abs(0.5 - weighted_significant) * 2
            
            overall_confidence = (p_value_consistency + vote_consistency + voting_confidence) / 3
            overall_confidence = np.clip(overall_confidence, 0.0, 1.0)
            
            return {
                'final_decision': bool(independence_decision),
                'confidence': float(overall_confidence),
                'combined_p_value': float(final_p_value),
                'combination_methods': {
                    'fisher_p_value': float(fisher_p_value),
                    'stouffer_p_value': float(stouffer_p_value),
                    'harmonic_mean_p_value': float(hmean_p_value)
                },
                'voting_summary': {
                    'significant_tests': int(sum(significance_votes)),
                    'total_tests': len(significance_votes),
                    'weighted_significance': float(weighted_significant),
                    'vote_consistency': float(vote_consistency)
                },
                'test_statistics_summary': {
                    'min_p_value': float(np.min(p_values)),
                    'max_p_value': float(np.max(p_values)),
                    'median_p_value': float(np.median(p_values)),
                    'p_value_std': float(np.std(p_values))
                }
            }
            
        except Exception as e:
            self.logger.error(f"Ensemble decision making failed: {e}")
            return {
                'final_decision': True,
                'confidence': 0.0,
                'combined_p_value': 1.0,
                'error': str(e)
            }

    def get_performance_statistics(self) -> Dict[str, Any]:
        """Get performance statistics for different test methods"""
        
        stats_summary = {}
        for method, times in self.performance_stats.items():
            if times:
                stats_summary[method] = {
                    'mean_time_seconds': np.mean(times),
                    'std_time_seconds': np.std(times),
                    'min_time_seconds': np.min(times),
                    'max_time_seconds': np.max(times),
                    'total_calls': len(times)
                }
        
        return {
            'method_performance': stats_summary,
            'cache_hit_rate': len(self.test_cache) / max(sum(len(times) for times in self.performance_stats.values()), 1),
            'cache_size': len(self.test_cache),
            'gpu_enabled': self.use_gpu,
            'available_engines': {
                'gpu_engine': self.gpu_engine is not None,
                'gnn_engine': self.gnn_engine is not None
            }
        }
        
    def clear_cache(self):
        """Clear test result cache"""
        self.test_cache.clear()
        self.logger.info("Test result cache cleared")


class GPUAcceleratedIndependenceTestingEngine:
    """
    GPU-accelerated statistical independence testing using CUDA
    Provides massive speedup for large-scale independence testing
    """
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.logger = logging.getLogger(__name__)
        
        # GPU configuration
        self.use_gpu = HAS_CUPY and torch.cuda.is_available()
        self.device = 'cuda' if self.use_gpu else 'cpu'
        self.batch_size = self.config.get('batch_size', 1024)
        self.max_memory_fraction = self.config.get('max_memory_fraction', 0.8)
        
        # Initialize GPU resources
        if self.use_gpu:
            self._initialize_gpu_resources()
        
        # Performance tracking
        self.gpu_stats = defaultdict(list)
        
        self.logger.info(f"GPU acceleration {'enabled' if self.use_gpu else 'disabled'}")
    
    def _initialize_gpu_resources(self):
        """Initialize GPU resources and memory management"""
        try:
            if HAS_CUPY:
                import cupy as cp
                self.cp = cp
                
                # Set memory pool
                mempool = cp.get_default_memory_pool()
                mempool.set_limit(fraction=self.max_memory_fraction)
                
                # Get GPU info
                gpu_info = cp.cuda.Device(0)
                total_memory = gpu_info.mem_info[1]
                self.max_batch_elements = min(
                    self.batch_size,
                    int(total_memory * self.max_memory_fraction / (8 * 4))  # 8 bytes per float64, safety factor
                )
                
                self.logger.info(f"GPU initialized: {gpu_info.name}")
                self.logger.info(f"Max batch elements: {self.max_batch_elements}")
                
        except Exception as e:
            self.logger.error(f"GPU initialization failed: {e}")
            self.use_gpu = False
    
    async def batch_mutual_information_test(self, X: np.ndarray, Y: np.ndarray, 
                                          k: int = 3, base: float = np.e) -> Dict[str, Any]:
        """
        GPU-accelerated mutual information estimation using KSG estimator
        Implements the Kraskov-Stögbauer-Grassberger method with CUDA acceleration
        """
        
        if not self.use_gpu:
            return await self._cpu_mutual_information_test(X, Y, k, base)
        
        start_time = time.time()
        
        try:
            # Transfer data to GPU
            X_gpu = self.cp.asarray(X, dtype=self.cp.float64)
            Y_gpu = self.cp.asarray(Y, dtype=self.cp.float64)
            
            n_samples = X_gpu.shape[0]
            
            # KSG estimator implementation on GPU
            mi_estimate = await self._gpu_ksg_estimator(X_gpu, Y_gpu, k, base)
            
            # Statistical significance testing
            p_value = await self._gpu_mi_significance_test(X_gpu, Y_gpu, mi_estimate, k, base)
            
            # Performance tracking
            computation_time = time.time() - start_time
            self.gpu_stats['mutual_information'].append(computation_time)
            
            return {
                'test_statistic': float(mi_estimate),
                'p_value': float(p_value),
                'significant': p_value < 0.05,
                'method': 'gpu_mutual_information_ksg',
                'k_neighbors': k,
                'base': base,
                'n_samples': int(n_samples),
                'computation_time_gpu': computation_time,
                'gpu_memory_used_mb': float(self.cp.get_default_memory_pool().used_bytes() / 1024**2)
            }
            
        except Exception as e:
            self.logger.error(f"GPU mutual information test failed: {e}")
            return await self._cpu_mutual_information_test(X, Y, k, base)
    
    async def _gpu_ksg_estimator(self, X_gpu, Y_gpu, k: int, base: float) -> float:
        """GPU implementation of KSG mutual information estimator"""
        
        n_samples = X_gpu.shape[0]
        dim_x = X_gpu.shape[1] if X_gpu.ndim > 1 else 1
        dim_y = Y_gpu.shape[1] if Y_gpu.ndim > 1 else 1
        
        # Reshape for proper broadcasting
        if X_gpu.ndim == 1:
            X_gpu = X_gpu.reshape(-1, 1)
        if Y_gpu.ndim == 1:
            Y_gpu = Y_gpu.reshape(-1, 1)
        
        # Joint space Z = [X, Y]
        Z_gpu = self.cp.hstack([X_gpu, Y_gpu])
        
        # Batch processing for large datasets
        batch_size = min(self.max_batch_elements // n_samples, n_samples)
        n_batches = (n_samples + batch_size - 1) // batch_size
        
        mi_estimates = []
        
        for batch_idx in range(n_batches):
            start_idx = batch_idx * batch_size
            end_idx = min((batch_idx + 1) * batch_size, n_samples)
            
            batch_mi = await self._gpu_ksg_batch(
                X_gpu[start_idx:end_idx], 
                Y_gpu[start_idx:end_idx], 
                Z_gpu[start_idx:end_idx], 
                k, dim_x, dim_y, base
            )
            mi_estimates.append(batch_mi)
        
        # Combine batch results
        return float(self.cp.mean(self.cp.array(mi_estimates)))
    
    async def _gpu_ksg_batch(self, X_batch, Y_batch, Z_batch, k, dim_x, dim_y, base):
        """Process a batch for KSG estimation on GPU"""
        
        n_batch = X_batch.shape[0]
        
        # Compute k-nearest neighbors in joint space Z
        distances_z = self._gpu_pairwise_distances(Z_batch, Z_batch)
        knn_distances_z = self.cp.partition(distances_z, k, axis=1)[:, k]
        
        # For each point, count neighbors in X and Y spaces within epsilon
        epsilon = knn_distances_z.reshape(-1, 1)
        
        # Count neighbors in X space
        distances_x = self._gpu_pairwise_distances(X_batch, X_batch)
        nx = self.cp.sum(distances_x < epsilon, axis=1) - 1  # Exclude self
        
        # Count neighbors in Y space  
        distances_y = self._gpu_pairwise_distances(Y_batch, Y_batch)
        ny = self.cp.sum(distances_y < epsilon, axis=1) - 1  # Exclude self
        
        # KSG formula: MI = psi(k) + psi(n) - <psi(nx+1) + psi(ny+1)>
        # where psi is the digamma function
        
        # Digamma function approximation on GPU
        psi_k = self._gpu_digamma(k)
        psi_n = self._gpu_digamma(n_batch)
        psi_nx = self._gpu_digamma(nx + 1)
        psi_ny = self._gpu_digamma(ny + 1)
        
        mi_estimate = psi_k + psi_n - self.cp.mean(psi_nx + psi_ny)
        
        # Convert to desired base
        if base != np.e:
            mi_estimate = mi_estimate / self.cp.log(base)
        
        return mi_estimate
    
    def _gpu_pairwise_distances(self, X, Y):
        """Compute pairwise Euclidean distances on GPU"""
        
        # Use broadcasting for efficient distance computation
        # ||x - y||^2 = ||x||^2 + ||y||^2 - 2<x,y>
        
        X_norm = self.cp.sum(X**2, axis=1, keepdims=True)
        Y_norm = self.cp.sum(Y**2, axis=1, keepdims=True)
        XY = self.cp.dot(X, Y.T)
        
        distances_squared = X_norm + Y_norm.T - 2 * XY
        distances_squared = self.cp.maximum(distances_squared, 0)  # Numerical stability
        
        return self.cp.sqrt(distances_squared)
    
    def _gpu_digamma(self, x):
        """GPU implementation of digamma function (derivative of log gamma)"""
        
        # Use series approximation for digamma function
        # psi(x) ≈ log(x) - 1/(2x) - 1/(12x^2) + 1/(120x^4) - 1/(252x^6)
        
        x = self.cp.asarray(x, dtype=self.cp.float64)
        
        # For small values, use recurrence relation
        # psi(x+1) = psi(x) + 1/x
        
        result = self.cp.zeros_like(x, dtype=self.cp.float64)
        
        # Main approximation for x >= 1
        mask = x >= 1
        x_large = x[mask]
        
        if self.cp.any(mask):
            log_x = self.cp.log(x_large)
            inv_x = 1.0 / x_large
            inv_x2 = inv_x * inv_x
            inv_x4 = inv_x2 * inv_x2
            inv_x6 = inv_x4 * inv_x2
            
            psi_approx = (log_x - 0.5 * inv_x - inv_x2 / 12.0 + 
                         inv_x4 / 120.0 - inv_x6 / 252.0)
            
            result = self.cp.where(mask, psi_approx, result)
        
        # Handle x < 1 using recurrence relation
        mask_small = x < 1
        if self.cp.any(mask_small):
            x_small = x[mask_small]
            # Shift to x >= 1 and use recurrence
            n_shifts = self.cp.ceil(1 - x_small).astype(int)
            x_shifted = x_small + n_shifts
            
            # Compute digamma for shifted values
            x_shifted_psi = self._gpu_digamma(x_shifted)
            
            # Apply recurrence relation backwards
            correction = self.cp.zeros_like(x_small)
            for i in range(1, int(self.cp.max(n_shifts)) + 1):
                mask_shift = n_shifts >= i
                correction = self.cp.where(mask_shift, correction - 1.0 / (x_small + i - 1), correction)
            
            result = self.cp.where(mask_small, x_shifted_psi + correction, result)
        
        return result
    
    async def _gpu_mi_significance_test(self, X_gpu, Y_gpu, observed_mi, k, base, n_permutations=500):
        """GPU-accelerated permutation test for mutual information significance"""
        
        n_samples = X_gpu.shape[0]
        
        # Generate permutation indices on GPU
        permutation_mis = []
        
        # Process permutations in batches for memory efficiency
        batch_size = min(50, n_permutations)
        n_batches = (n_permutations + batch_size - 1) // batch_size
        
        for batch_idx in range(n_batches):
            batch_start = batch_idx * batch_size
            batch_end = min((batch_idx + 1) * batch_size, n_permutations)
            current_batch_size = batch_end - batch_start
            
            # Generate random permutation indices for this batch
            perm_indices_batch = self.cp.random.permutation(n_samples)[:current_batch_size * (n_samples // current_batch_size)]
            perm_indices_batch = perm_indices_batch.reshape(current_batch_size, -1)
            
            batch_mis = []
            for perm_idx in range(current_batch_size):
                # Permute Y while keeping X fixed
                Y_perm = Y_gpu[perm_indices_batch[perm_idx]]
                
                # Compute MI for permuted data
                mi_perm = await self._gpu_ksg_estimator(X_gpu, Y_perm, k, base)
                batch_mis.append(mi_perm)
            
            permutation_mis.extend(batch_mis)
        
        # Convert to GPU array for final computation
        permutation_mis = self.cp.array(permutation_mis)
        
        # Compute p-value
        p_value = self.cp.mean(permutation_mis >= observed_mi)
        
        return float(p_value)
    
    async def batch_distance_correlation(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """GPU-accelerated distance correlation computation"""
        
        if not self.use_gpu:
            return await self._cpu_distance_correlation(X, Y)
        
        start_time = time.time()
        
        try:
            # Transfer to GPU
            X_gpu = self.cp.asarray(X, dtype=self.cp.float64)
            Y_gpu = self.cp.asarray(Y, dtype=self.cp.float64)
            
            # Compute distance correlation
            dcorr = await self._gpu_distance_correlation(X_gpu, Y_gpu)
            
            # Significance test using permutations
            p_value = await self._gpu_dcorr_significance_test(X_gpu, Y_gpu, dcorr)
            
            computation_time = time.time() - start_time
            self.gpu_stats['distance_correlation'].append(computation_time)
            
            return {
                'test_statistic': float(dcorr),
                'p_value': float(p_value),
                'significant': p_value < 0.05,
                'method': 'gpu_distance_correlation',
                'computation_time_gpu': computation_time,
                'gpu_memory_used_mb': float(self.cp.get_default_memory_pool().used_bytes() / 1024**2)
            }
            
        except Exception as e:
            self.logger.error(f"GPU distance correlation failed: {e}")
            return await self._cpu_distance_correlation(X, Y)
    
    async def _gpu_distance_correlation(self, X_gpu, Y_gpu):
        """Compute distance correlation on GPU"""
        
        n = X_gpu.shape[0]
        
        # Ensure 2D arrays
        if X_gpu.ndim == 1:
            X_gpu = X_gpu.reshape(-1, 1)
        if Y_gpu.ndim == 1:
            Y_gpu = Y_gpu.reshape(-1, 1)
        
        # Compute pairwise distances
        a_ij = self._gpu_pairwise_distances(X_gpu, X_gpu)
        b_ij = self._gpu_pairwise_distances(Y_gpu, Y_gpu)
        
        # Double centering
        a_i_dot = self.cp.mean(a_ij, axis=1, keepdims=True)
        a_dot_j = self.cp.mean(a_ij, axis=0, keepdims=True)
        a_dot_dot = self.cp.mean(a_ij)
        
        A_ij = a_ij - a_i_dot - a_dot_j + a_dot_dot
        
        b_i_dot = self.cp.mean(b_ij, axis=1, keepdims=True)
        b_dot_j = self.cp.mean(b_ij, axis=0, keepdims=True)
        b_dot_dot = self.cp.mean(b_ij)
        
        B_ij = b_ij - b_i_dot - b_dot_j + b_dot_dot
        
        # Distance covariance and variances
        dcov_xy = self.cp.sqrt(self.cp.mean(A_ij * B_ij))
        dvar_x = self.cp.sqrt(self.cp.mean(A_ij * A_ij))
        dvar_y = self.cp.sqrt(self.cp.mean(B_ij * B_ij))
        
        # Distance correlation
        if dvar_x > 0 and dvar_y > 0:
            dcorr = dcov_xy / self.cp.sqrt(dvar_x * dvar_y)
        else:
            dcorr = 0.0
        
        return dcorr
    
    async def _gpu_dcorr_significance_test(self, X_gpu, Y_gpu, observed_dcorr, n_permutations=300):
        """GPU-accelerated permutation test for distance correlation"""
        
        n_samples = X_gpu.shape[0]
        permutation_dcorrs = []
        
        for _ in range(n_permutations):
            # Random permutation of Y
            perm_indices = self.cp.random.permutation(n_samples)
            Y_perm = Y_gpu[perm_indices]
            
            # Compute distance correlation for permuted data
            dcorr_perm = await self._gpu_distance_correlation(X_gpu, Y_perm)
            permutation_dcorrs.append(dcorr_perm)
        
        permutation_dcorrs = self.cp.array(permutation_dcorrs)
        p_value = self.cp.mean(permutation_dcorrs >= observed_dcorr)
        
        return float(p_value)
    
    async def batch_kernel_independence_test(self, X: np.ndarray, Y: np.ndarray, 
                                           kernel_type: str = 'gaussian', 
                                           sigma: Optional[float] = None) -> Dict[str, Any]:
        """GPU-accelerated kernel independence test (HSIC)"""
        
        if not self.use_gpu:
            return await self._cpu_kernel_independence_test(X, Y, kernel_type, sigma)
        
        start_time = time.time()
        
        try:
            # Transfer to GPU
            X_gpu = self.cp.asarray(X, dtype=self.cp.float64)
            Y_gpu = self.cp.asarray(Y, dtype=self.cp.float64)
            
            # Compute HSIC
            hsic_value = await self._gpu_hsic(X_gpu, Y_gpu, kernel_type, sigma)
            
            # Significance test
            p_value = await self._gpu_hsic_significance_test(X_gpu, Y_gpu, hsic_value, kernel_type, sigma)
            
            computation_time = time.time() - start_time
            self.gpu_stats['kernel_independence'].append(computation_time)
            
            return {
                'test_statistic': float(hsic_value),
                'p_value': float(p_value),
                'significant': p_value < 0.05,
                'method': f'gpu_hsic_{kernel_type}',
                'kernel_type': kernel_type,
                'sigma': sigma,
                'computation_time_gpu': computation_time,
                'gpu_memory_used_mb': float(self.cp.get_default_memory_pool().used_bytes() / 1024**2)
            }
            
        except Exception as e:
            self.logger.error(f"GPU kernel independence test failed: {e}")
            return await self._cpu_kernel_independence_test(X, Y, kernel_type, sigma)
    
    async def _gpu_hsic(self, X_gpu, Y_gpu, kernel_type='gaussian', sigma=None):
        """Compute HSIC (Hilbert-Schmidt Independence Criterion) on GPU"""
        
        n = X_gpu.shape[0]
        
        # Ensure 2D arrays
        if X_gpu.ndim == 1:
            X_gpu = X_gpu.reshape(-1, 1)
        if Y_gpu.ndim == 1:
            Y_gpu = Y_gpu.reshape(-1, 1)
        
        # Compute kernel matrices
        K = self._gpu_kernel_matrix(X_gpu, X_gpu, kernel_type, sigma)
        L = self._gpu_kernel_matrix(Y_gpu, Y_gpu, kernel_type, sigma)
        
        # Center kernel matrices
        H = self.cp.eye(n) - self.cp.ones((n, n)) / n
        K_c = H @ K @ H
        L_c = H @ L @ H
        
        # Compute HSIC
        hsic = self.cp.trace(K_c @ L_c) / ((n - 1) ** 2)
        
        return hsic
    
    def _gpu_kernel_matrix(self, X, Y, kernel_type='gaussian', sigma=None):
        """Compute kernel matrix on GPU"""
        
        if kernel_type == 'gaussian':
            # RBF kernel: K(x,y) = exp(-||x-y||^2 / (2*sigma^2))
            
            if sigma is None:
                # Median heuristic for bandwidth selection
                distances = self._gpu_pairwise_distances(X, Y)
                sigma = self.cp.median(distances[distances > 0])
            
            # Compute squared distances
            dist_sq = self._gpu_pairwise_distances(X, Y) ** 2
            
            # RBF kernel
            K = self.cp.exp(-dist_sq / (2 * sigma**2))
            
        elif kernel_type == 'linear':
            # Linear kernel: K(x,y) = <x,y>
            K = X @ Y.T
            
        elif kernel_type == 'polynomial':
            # Polynomial kernel: K(x,y) = (<x,y> + 1)^d
            degree = 2  # Default degree
            K = (X @ Y.T + 1) ** degree
            
        else:
            raise ValueError(f"Unknown kernel type: {kernel_type}")
        
        return K
    
    async def _gpu_hsic_significance_test(self, X_gpu, Y_gpu, observed_hsic, 
                                        kernel_type, sigma, n_permutations=200):
        """GPU-accelerated permutation test for HSIC"""
        
        n_samples = X_gpu.shape[0]
        permutation_hsics = []
        
        for _ in range(n_permutations):
            # Random permutation of Y
            perm_indices = self.cp.random.permutation(n_samples)
            Y_perm = Y_gpu[perm_indices]
            
            # Compute HSIC for permuted data
            hsic_perm = await self._gpu_hsic(X_gpu, Y_perm, kernel_type, sigma)
            permutation_hsics.append(hsic_perm)
        
        permutation_hsics = self.cp.array(permutation_hsics)
        p_value = self.cp.mean(permutation_hsics >= observed_hsic)
        
        return float(p_value)
    
    # CPU fallback methods
    async def _cpu_mutual_information_test(self, X, Y, k, base):
        """CPU fallback for mutual information test"""
        from sklearn.feature_selection import mutual_info_regression
        
        try:
            if X.ndim > 1 and X.shape[1] > 1:
                X = X[:, 0]
            if Y.ndim > 1 and Y.shape[1] > 1:
                Y = Y[:, 0]
            
            mi = mutual_info_regression(X.reshape(-1, 1), Y, discrete_features=False)[0]
            
            # Simple permutation test for p-value
            n_perm = 100
            perm_mis = []
            for _ in range(n_perm):
                Y_perm = np.random.permutation(Y)
                mi_perm = mutual_info_regression(X.reshape(-1, 1), Y_perm, discrete_features=False)[0]
                perm_mis.append(mi_perm)
            
            p_value = np.mean(np.array(perm_mis) >= mi)
            
            return {
                'test_statistic': float(mi),
                'p_value': float(p_value),
                'significant': p_value < 0.05,
                'method': 'cpu_mutual_information_sklearn'
            }
            
        except Exception as e:
            self.logger.error(f"CPU mutual information test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False, 'error': str(e)}
    
    async def _cpu_distance_correlation(self, X, Y):
        """CPU fallback for distance correlation"""
        
        try:
            # Simple implementation
            from scipy.spatial.distance import pdist, squareform
            
            n = X.shape[0]
            
            # Pairwise distances
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            a = squareform(pdist(X))
            b = squareform(pdist(Y))
            
            # Double centering
            A = a - a.mean(axis=0, keepdims=True) - a.mean(axis=1, keepdims=True) + a.mean()
            B = b - b.mean(axis=0, keepdims=True) - b.mean(axis=1, keepdims=True) + b.mean()
            
            # Distance correlation
            dcov = np.sqrt(np.mean(A * B))
            dvar_x = np.sqrt(np.mean(A * A))
            dvar_y = np.sqrt(np.mean(B * B))
            
            if dvar_x > 0 and dvar_y > 0:
                dcorr = dcov / np.sqrt(dvar_x * dvar_y)
            else:
                dcorr = 0.0
            
            # Simple permutation test
            n_perm = 100
            perm_dcorrs = []
            for _ in range(n_perm):
                Y_perm = Y[np.random.permutation(n)]
                b_perm = squareform(pdist(Y_perm))
                B_perm = b_perm - b_perm.mean(axis=0, keepdims=True) - b_perm.mean(axis=1, keepdims=True) + b_perm.mean()
                
                dcov_perm = np.sqrt(np.mean(A * B_perm))
                dvar_y_perm = np.sqrt(np.mean(B_perm * B_perm))
                
                if dvar_x > 0 and dvar_y_perm > 0:
                    dcorr_perm = dcov_perm / np.sqrt(dvar_x * dvar_y_perm)
                else:
                    dcorr_perm = 0.0
                
                perm_dcorrs.append(dcorr_perm)
            
            p_value = np.mean(np.array(perm_dcorrs) >= dcorr)
            
            return {
                'test_statistic': float(dcorr),
                'p_value': float(p_value),
                'significant': p_value < 0.05,
                'method': 'cpu_distance_correlation'
            }
            
        except Exception as e:
            self.logger.error(f"CPU distance correlation failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False, 'error': str(e)}
    
    async def _cpu_kernel_independence_test(self, X, Y, kernel_type, sigma):
        """CPU fallback for kernel independence test"""
        
        try:
            # Simplified HSIC implementation
            n = X.shape[0]
            
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            # Simple RBF kernel
            from sklearn.metrics.pairwise import rbf_kernel
            
            if sigma is None:
                sigma = 1.0
            
            gamma = 1.0 / (2 * sigma**2)
            K = rbf_kernel(X, gamma=gamma)
            L = rbf_kernel(Y, gamma=gamma)
            
            # Center kernels
            H = np.eye(n) - np.ones((n, n)) / n
            K_c = H @ K @ H
            L_c = H @ L @ H
            
            # HSIC
            hsic = np.trace(K_c @ L_c) / ((n - 1) ** 2)
            
            # Simple permutation test
            n_perm = 50
            perm_hsics = []
            for _ in range(n_perm):
                Y_perm = Y[np.random.permutation(n)]
                L_perm = rbf_kernel(Y_perm, gamma=gamma)
                L_c_perm = H @ L_perm @ H
                hsic_perm = np.trace(K_c @ L_c_perm) / ((n - 1) ** 2)
                perm_hsics.append(hsic_perm)
            
            p_value = np.mean(np.array(perm_hsics) >= hsic)
            
            return {
                'test_statistic': float(hsic),
                'p_value': float(p_value),
                'significant': p_value < 0.05,
                'method': 'cpu_hsic'
            }
            
        except Exception as e:
            self.logger.error(f"CPU kernel independence test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False, 'error': str(e)}
    
    def get_gpu_statistics(self) -> Dict[str, Any]:
        """Get GPU performance statistics"""
        
        stats = {
            'gpu_enabled': self.use_gpu,
            'device': self.device,
            'method_performance': {}
        }
        
        if self.use_gpu:
            try:
                # GPU memory info
                mempool = self.cp.get_default_memory_pool()
                stats['gpu_memory'] = {
                    'used_bytes': int(mempool.used_bytes()),
                    'total_bytes': int(mempool.total_bytes()),
                    'used_mb': float(mempool.used_bytes() / 1024**2),
                    'total_mb': float(mempool.total_bytes() / 1024**2)
                }
                
                # Performance statistics
                for method, times in self.gpu_stats.items():
                    if times:
                        stats['method_performance'][method] = {
                            'mean_time_seconds': np.mean(times),
                            'std_time_seconds': np.std(times),
                            'min_time_seconds': np.min(times),
                            'max_time_seconds': np.max(times),
                            'total_calls': len(times)
                        }
                
            except Exception as e:
                stats['gpu_error'] = str(e)
        
        return stats


class TimeSeriesIndependenceTests:
    """
    Advanced time series independence analysis methods
    Includes wavelet coherence, EMD, spectral analysis, and nonlinear dynamics
    """
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.logger = logging.getLogger(__name__)
        
        # Configuration parameters
        self.sampling_rate = self.config.get('sampling_rate', 1.0)
        self.significance_level = self.config.get('significance_level', 0.05)
        self.n_bootstrap = self.config.get('n_bootstrap', 1000)
        
        # Initialize components
        self._initialize_components()
    
    def _initialize_components(self):
        """Initialize time series analysis components"""
        
        try:
            # Wavelet analysis
            if HAS_WAVELETS:
                self.wavelet_available = True
                self.mother_wavelet = 'morlet'
                self.scales = None  # Will be computed adaptively
            else:
                self.wavelet_available = False
                
            # EMD analysis
            if HAS_PYEMD:
                self.emd_available = True
                self.emd = EMD()
                self.eemd = EEMD()
                self.ceemdan = CEEMDAN()
            else:
                self.emd_available = False
                
            # Spectral analysis
            self.spectral_available = HAS_STATSMODELS
            
            # Nonlinear dynamics
            self.nonlinear_available = HAS_NOLITSA
            
            self.logger.info(f"Time series components - Wavelet: {self.wavelet_available}, "
                           f"EMD: {self.emd_available}, Spectral: {self.spectral_available}, "
                           f"Nonlinear: {self.nonlinear_available}")
            
        except Exception as e:
            self.logger.error(f"Failed to initialize time series components: {e}")
    
    async def wavelet_coherence_test(self, x: np.ndarray, y: np.ndarray) -> Dict[str, Any]:
        """
        Wavelet coherence analysis for time series independence
        Measures frequency-domain correlation as a function of time
        """
        
        if not self.wavelet_available:
            return await self._fallback_coherence_test(x, y)
        
        try:
            # Ensure equal length time series
            min_len = min(len(x), len(y))
            x = x[:min_len]
            y = y[:min_len]
            
            # Compute continuous wavelet transforms
            cwt_x, freqs_x, scales_x = self._compute_cwt(x)
            cwt_y, freqs_y, scales_y = self._compute_cwt(y)
            
            # Ensure same frequency scales
            min_scales = min(len(scales_x), len(scales_y))
            cwt_x = cwt_x[:min_scales, :]
            cwt_y = cwt_y[:min_scales, :]
            scales = scales_x[:min_scales]
            
            # Compute wavelet coherence
            coherence = self._compute_wavelet_coherence(cwt_x, cwt_y)
            
            # Statistical significance testing
            significance, p_values = await self._wavelet_significance_test(x, y, coherence)
            
            # Aggregate measures
            mean_coherence = np.mean(coherence)
            max_coherence = np.max(coherence)
            significant_fraction = np.mean(significance)
            
            # Phase analysis
            phase_diff = self._compute_phase_difference(cwt_x, cwt_y)
            mean_phase_diff = np.angle(np.mean(np.exp(1j * phase_diff)))
            
            return {
                'test_statistic': float(mean_coherence),
                'max_coherence': float(max_coherence),
                'significant_fraction': float(significant_fraction),
                'mean_phase_difference': float(mean_phase_diff),
                'p_value': float(np.mean(p_values[significance > 0])) if np.any(significance > 0) else 1.0,
                'significant': significant_fraction > 0.1,  # 10% threshold
                'method': 'wavelet_coherence',
                'coherence_matrix': coherence.tolist(),
                'scales': scales.tolist(),
                'frequencies': freqs_x.tolist()
            }
            
        except Exception as e:
            self.logger.error(f"Wavelet coherence test failed: {e}")
            return await self._fallback_coherence_test(x, y)
    
    def _compute_cwt(self, signal: np.ndarray) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """Compute continuous wavelet transform"""
        
        # Adaptive scale selection
        n = len(signal)
        dt = 1.0 / self.sampling_rate
        
        # Scales from highest frequency (finest scale) to lowest frequency (coarsest scale)
        scales = np.logspace(0, np.log10(n/4), 50)  # 50 scales
        
        # Compute CWT using Morlet wavelet
        coefficients, freqs = pywt.cwt(signal, scales, self.mother_wavelet, dt)
        
        return coefficients, freqs, scales
    
    def _compute_wavelet_coherence(self, cwt_x: np.ndarray, cwt_y: np.ndarray, 
                                  smoothing_window: int = 5) -> np.ndarray:
        """Compute wavelet coherence between two CWT arrays"""
        
        # Cross-spectrum
        cross_spectrum = cwt_x * np.conj(cwt_y)
        
        # Auto-spectra
        spectrum_x = np.abs(cwt_x)**2
        spectrum_y = np.abs(cwt_y)**2
        
        # Smooth in time (simple moving average)
        def smooth_matrix(matrix, window):
            # Apply smoothing along time axis
            smoothed = np.zeros_like(matrix, dtype=complex)
            for i in range(matrix.shape[0]):
                for j in range(window//2, matrix.shape[1] - window//2):
                    smoothed[i, j] = np.mean(matrix[i, j-window//2:j+window//2+1])
            return smoothed
        
        # Smooth spectra
        if smoothing_window > 1:
            cross_spectrum_smooth = smooth_matrix(cross_spectrum, smoothing_window)
            spectrum_x_smooth = smooth_matrix(spectrum_x, smoothing_window)
            spectrum_y_smooth = smooth_matrix(spectrum_y, smoothing_window)
        else:
            cross_spectrum_smooth = cross_spectrum
            spectrum_x_smooth = spectrum_x
            spectrum_y_smooth = spectrum_y
        
        # Wavelet coherence
        coherence = np.abs(cross_spectrum_smooth)**2 / (spectrum_x_smooth * spectrum_y_smooth + 1e-10)
        
        return np.real(coherence)
    
    def _compute_phase_difference(self, cwt_x: np.ndarray, cwt_y: np.ndarray) -> np.ndarray:
        """Compute phase difference between two wavelet transforms"""
        
        phase_x = np.angle(cwt_x)
        phase_y = np.angle(cwt_y)
        
        return phase_y - phase_x
    
    async def _wavelet_significance_test(self, x: np.ndarray, y: np.ndarray, 
                                       coherence: np.ndarray, n_surrogates: int = 100) -> Tuple[np.ndarray, np.ndarray]:
        """Test wavelet coherence significance using surrogate data"""
        
        # Generate surrogate data by phase randomization
        n_scales, n_times = coherence.shape
        surrogate_coherences = []
        
        for _ in range(n_surrogates):
            # Phase-randomized surrogates
            x_surrogate = self._phase_randomize(x)
            y_surrogate = self._phase_randomize(y)
            
            # Compute CWT for surrogates
            cwt_x_surr, _, _ = self._compute_cwt(x_surrogate)
            cwt_y_surr, _, _ = self._compute_cwt(y_surrogate)
            
            # Ensure same dimensions
            min_scales = min(cwt_x_surr.shape[0], n_scales)
            cwt_x_surr = cwt_x_surr[:min_scales, :n_times]
            cwt_y_surr = cwt_y_surr[:min_scales, :n_times]
            
            # Compute surrogate coherence
            surr_coherence = self._compute_wavelet_coherence(cwt_x_surr, cwt_y_surr)
            surrogate_coherences.append(surr_coherence[:min_scales, :])
        
        # Stack surrogates
        surrogate_stack = np.stack(surrogate_coherences, axis=-1)
        
        # Compute significance
        significance = np.zeros_like(coherence)
        p_values = np.ones_like(coherence)
        
        for i in range(min(n_scales, surrogate_stack.shape[0])):
            for j in range(min(n_times, surrogate_stack.shape[1])):
                surr_values = surrogate_stack[i, j, :]
                percentile_95 = np.percentile(surr_values, 95)
                
                significance[i, j] = coherence[i, j] > percentile_95
                p_values[i, j] = np.mean(surr_values >= coherence[i, j])
        
        return significance, p_values
    
    def _phase_randomize(self, signal: np.ndarray) -> np.ndarray:
        """Generate phase-randomized surrogate maintaining amplitude spectrum"""
        
        # FFT of original signal
        fft_signal = np.fft.fft(signal)
        
        # Random phases
        n = len(signal)
        random_phases = np.random.uniform(0, 2*np.pi, n//2 + 1)
        
        # Ensure conjugate symmetry for real result
        if n % 2 == 0:
            random_phases[-1] = 0  # Nyquist frequency must be real
        
        # Construct phase-randomized FFT
        phases = np.zeros(n)
        phases[1:n//2+1] = random_phases[1:n//2+1]
        phases[n//2+1:] = -random_phases[1:n//2][::-1]
        
        # Apply random phases while preserving amplitudes
        fft_randomized = np.abs(fft_signal) * np.exp(1j * phases)
        
        # Inverse FFT
        surrogate = np.real(np.fft.ifft(fft_randomized))
        
        return surrogate
    
    async def emd_independence_test(self, x: np.ndarray, y: np.ndarray) -> Dict[str, Any]:
        """
        Independence test using Empirical Mode Decomposition
        Decomposes signals into intrinsic mode functions and tests independence
        """
        
        if not self.emd_available:
            return await self._fallback_emd_test(x, y)
        
        try:
            # Ensure equal length
            min_len = min(len(x), len(y))
            x = x[:min_len]
            y = y[:min_len]
            
            # EMD decomposition
            imfs_x = self.emd.emd(x)
            imfs_y = self.emd.emd(y)
            
            # Test independence of corresponding IMFs
            imf_correlations = []
            imf_p_values = []
            
            min_imfs = min(imfs_x.shape[1], imfs_y.shape[1])
            
            for i in range(min_imfs):
                imf_x = imfs_x[:, i]
                imf_y = imfs_y[:, i]
                
                # Correlation test
                corr, p_val = stats.pearsonr(imf_x, imf_y)
                imf_correlations.append(abs(corr))
                imf_p_values.append(p_val)
            
            # Overall tests
            max_correlation = np.max(imf_correlations) if imf_correlations else 0
            min_p_value = np.min(imf_p_values) if imf_p_values else 1
            
            # Bonferroni correction for multiple testing
            corrected_p_value = min(min_p_value * len(imf_p_values), 1.0)
            
            # Instantaneous phase coupling test
            phase_coupling = await self._test_instantaneous_phase_coupling(imfs_x, imfs_y)
            
            # Hilbert-Huang spectrum correlation
            hh_correlation = await self._hilbert_huang_spectrum_correlation(imfs_x, imfs_y)
            
            return {
                'test_statistic': float(max_correlation),
                'p_value': float(corrected_p_value),
                'significant': corrected_p_value < self.significance_level,
                'method': 'emd_independence',
                'n_imfs_x': imfs_x.shape[1],
                'n_imfs_y': imfs_y.shape[1],
                'imf_correlations': imf_correlations,
                'imf_p_values': imf_p_values,
                'phase_coupling': phase_coupling,
                'hh_spectrum_correlation': hh_correlation
            }
            
        except Exception as e:
            self.logger.error(f"EMD independence test failed: {e}")
            return await self._fallback_emd_test(x, y)
    
    async def _test_instantaneous_phase_coupling(self, imfs_x: np.ndarray, 
                                               imfs_y: np.ndarray) -> Dict[str, Any]:
        """Test coupling between instantaneous phases of IMFs"""
        
        try:
            phase_couplings = []
            
            min_imfs = min(imfs_x.shape[1], imfs_y.shape[1])
            
            for i in range(min_imfs):
                # Hilbert transform for instantaneous phase
                analytic_x = signal.hilbert(imfs_x[:, i])
                analytic_y = signal.hilbert(imfs_y[:, i])
                
                phase_x = np.angle(analytic_x)
                phase_y = np.angle(analytic_y)
                
                # Phase locking value (PLV)
                phase_diff = phase_y - phase_x
                plv = np.abs(np.mean(np.exp(1j * phase_diff)))
                phase_couplings.append(plv)
            
            return {
                'max_phase_coupling': float(np.max(phase_couplings)) if phase_couplings else 0,
                'mean_phase_coupling': float(np.mean(phase_couplings)) if phase_couplings else 0,
                'phase_coupling_per_imf': phase_couplings
            }
            
        except Exception as e:
            self.logger.error(f"Instantaneous phase coupling test failed: {e}")
            return {'max_phase_coupling': 0, 'mean_phase_coupling': 0, 'phase_coupling_per_imf': []}
    
    async def _hilbert_huang_spectrum_correlation(self, imfs_x: np.ndarray, 
                                                imfs_y: np.ndarray) -> Dict[str, Any]:
        """Compute correlation in Hilbert-Huang spectrum domain"""
        
        try:
            # Compute instantaneous frequency and amplitude for each IMF
            spectrum_x = []
            spectrum_y = []
            
            min_imfs = min(imfs_x.shape[1], imfs_y.shape[1])
            
            for i in range(min_imfs):
                # Hilbert transform
                analytic_x = signal.hilbert(imfs_x[:, i])
                analytic_y = signal.hilbert(imfs_y[:, i])
                
                # Instantaneous amplitude and frequency
                amp_x = np.abs(analytic_x)
                amp_y = np.abs(analytic_y)
                
                freq_x = np.diff(np.unwrap(np.angle(analytic_x))) / (2 * np.pi)
                freq_y = np.diff(np.unwrap(np.angle(analytic_y))) / (2 * np.pi)
                
                # Create spectrum representation (amplitude-frequency pairs)
                spectrum_x.append(np.column_stack([amp_x[:-1], freq_x]))
                spectrum_y.append(np.column_stack([amp_y[:-1], freq_y]))
            
            # Compute correlations in spectrum domain
            spectrum_correlations = []
            for i in range(len(spectrum_x)):
                # Flatten spectrum representations
                spec_x_flat = spectrum_x[i].flatten()
                spec_y_flat = spectrum_y[i].flatten()
                
                # Correlation between flattened spectra
                if len(spec_x_flat) > 1 and len(spec_y_flat) > 1:
                    corr = np.corrcoef(spec_x_flat, spec_y_flat)[0, 1]
                    spectrum_correlations.append(abs(corr) if not np.isnan(corr) else 0)
                else:
                    spectrum_correlations.append(0)
            
            return {
                'max_spectrum_correlation': float(np.max(spectrum_correlations)) if spectrum_correlations else 0,
                'mean_spectrum_correlation': float(np.mean(spectrum_correlations)) if spectrum_correlations else 0,
                'spectrum_correlations_per_imf': spectrum_correlations
            }
            
        except Exception as e:
            self.logger.error(f"Hilbert-Huang spectrum correlation failed: {e}")
            return {
                'max_spectrum_correlation': 0, 
                'mean_spectrum_correlation': 0, 
                'spectrum_correlations_per_imf': []
            }
    
    async def spectral_coherence_test(self, x: np.ndarray, y: np.ndarray,
                                    window: str = 'hann', nperseg: Optional[int] = None) -> Dict[str, Any]:
        """
        Spectral coherence analysis for frequency-domain independence testing
        Uses Welch's method for robust spectral estimation
        """
        
        try:
            # Ensure equal length
            min_len = min(len(x), len(y))
            x = x[:min_len]
            y = y[:min_len]
            
            # Set default window size
            if nperseg is None:
                nperseg = min(256, min_len // 4)
            
            # Compute coherence using Welch's method
            freqs, coherence = signal.coherence(x, y, fs=self.sampling_rate, 
                                               window=window, nperseg=nperseg)
            
            # Cross-power spectral density
            freqs_cross, cross_psd = signal.csd(x, y, fs=self.sampling_rate,
                                              window=window, nperseg=nperseg)
            
            # Auto-power spectral densities
            freqs_x, psd_x = signal.welch(x, fs=self.sampling_rate, 
                                        window=window, nperseg=nperseg)
            freqs_y, psd_y = signal.welch(y, fs=self.sampling_rate,
                                        window=window, nperseg=nperseg)
            
            # Coherence statistics
            mean_coherence = np.mean(coherence)
            max_coherence = np.max(coherence)
            
            # Find peak coherence frequencies
            peak_indices = signal.find_peaks(coherence, height=0.5)[0]
            peak_frequencies = freqs[peak_indices] if len(peak_indices) > 0 else []
            
            # Phase spectrum
            phase_spectrum = np.angle(cross_psd)
            
            # Statistical significance using surrogate testing
            significance = await self._spectral_significance_test(x, y, coherence, 
                                                               window, nperseg)
            
            return {
                'test_statistic': float(mean_coherence),
                'max_coherence': float(max_coherence),
                'p_value': float(significance['p_value']),
                'significant': significance['p_value'] < self.significance_level,
                'method': 'spectral_coherence',
                'frequencies': freqs.tolist(),
                'coherence_spectrum': coherence.tolist(),
                'peak_frequencies': peak_frequencies.tolist(),
                'phase_spectrum': phase_spectrum.tolist(),
                'psd_x': psd_x.tolist(),
                'psd_y': psd_y.tolist(),
                'cross_psd': np.abs(cross_psd).tolist(),
                'significant_frequencies': significance['significant_frequencies']
            }
            
        except Exception as e:
            self.logger.error(f"Spectral coherence test failed: {e}")
            return await self._fallback_spectral_test(x, y)
    
    async def _spectral_significance_test(self, x: np.ndarray, y: np.ndarray,
                                        observed_coherence: np.ndarray,
                                        window: str, nperseg: int,
                                        n_surrogates: int = 100) -> Dict[str, Any]:
        """Test spectral coherence significance using surrogate data"""
        
        try:
            surrogate_coherences = []
            
            for _ in range(n_surrogates):
                # Generate surrogate by shuffling one series
                y_surrogate = np.random.permutation(y)
                
                # Compute coherence for surrogate
                freqs, surr_coherence = signal.coherence(x, y_surrogate, 
                                                       fs=self.sampling_rate,
                                                       window=window, nperseg=nperseg)
                surrogate_coherences.append(surr_coherence)
            
            # Stack surrogates
            surrogate_matrix = np.stack(surrogate_coherences, axis=1)
            
            # Compute significance for each frequency
            p_values = np.zeros(len(observed_coherence))
            for i in range(len(observed_coherence)):
                p_values[i] = np.mean(surrogate_matrix[i, :] >= observed_coherence[i])
            
            # Overall significance
            overall_p_value = np.mean(p_values)
            
            # Significant frequencies (after multiple comparison correction)
            alpha_corrected = self.significance_level / len(p_values)  # Bonferroni
            significant_mask = p_values < alpha_corrected
            significant_frequencies = freqs[significant_mask].tolist()
            
            return {
                'p_value': float(overall_p_value),
                'frequency_p_values': p_values.tolist(),
                'significant_frequencies': significant_frequencies,
                'n_significant_frequencies': int(np.sum(significant_mask))
            }
            
        except Exception as e:
            self.logger.error(f"Spectral significance test failed: {e}")
            return {
                'p_value': 1.0,
                'frequency_p_values': [1.0] * len(observed_coherence),
                'significant_frequencies': [],
                'n_significant_frequencies': 0
            }
    
    async def nonlinear_dynamics_test(self, x: np.ndarray, y: np.ndarray) -> Dict[str, Any]:
        """
        Nonlinear dynamics independence test using phase space reconstruction
        Tests for nonlinear coupling between time series
        """
        
        if not self.nonlinear_available:
            return await self._fallback_nonlinear_test(x, y)
        
        try:
            # Ensure equal length
            min_len = min(len(x), len(y))
            x = x[:min_len]
            y = y[:min_len]
            
            # Phase space reconstruction parameters
            embedding_dim = self._estimate_embedding_dimension(x)
            delay = self._estimate_delay(x)
            
            # Reconstruct phase space
            x_embedded = delay.embed(x, dim=embedding_dim, delay=delay)
            y_embedded = delay.embed(y, dim=embedding_dim, delay=delay)
            
            # Nonlinear measures
            measures = {}
            
            # 1. Correlation dimension
            measures['correlation_dim_x'] = self._correlation_dimension(x_embedded)
            measures['correlation_dim_y'] = self._correlation_dimension(y_embedded)
            
            # 2. Largest Lyapunov exponent
            measures['lyapunov_x'] = self._lyapunov_exponent(x_embedded)
            measures['lyapunov_y'] = self._lyapunov_exponent(y_embedded)
            
            # 3. Cross-correlation dimension
            measures['cross_correlation_dim'] = self._cross_correlation_dimension(x_embedded, y_embedded)
            
            # 4. Mutual false nearest neighbors
            measures['mutual_fnn'] = self._mutual_false_nearest_neighbors(x, y, embedding_dim, delay)
            
            # 5. Nonlinear cross-prediction
            measures['cross_prediction'] = await self._nonlinear_cross_prediction(x, y)
            
            # Overall nonlinear coupling measure
            coupling_strength = measures['cross_correlation_dim'] / max(
                measures['correlation_dim_x'], measures['correlation_dim_y'], 1e-6)
            
            # Significance test
            significance = await self._nonlinear_significance_test(x, y, coupling_strength)
            
            return {
                'test_statistic': float(coupling_strength),
                'p_value': float(significance),
                'significant': significance < self.significance_level,
                'method': 'nonlinear_dynamics',
                'embedding_dimension': embedding_dim,
                'delay': delay,
                'measures': measures
            }
            
        except Exception as e:
            self.logger.error(f"Nonlinear dynamics test failed: {e}")
            return await self._fallback_nonlinear_test(x, y)
    
    def _estimate_embedding_dimension(self, x: np.ndarray, max_dim: int = 10) -> int:
        """Estimate embedding dimension using false nearest neighbors"""
        
        try:
            if self.nonlinear_available:
                # Use nolitsa if available
                tau = delay.dmi(x)
                dim = dimension.fnn(x, tau=tau, maxdim=max_dim)
                return max(2, min(dim, max_dim))
            else:
                # Simple heuristic
                return min(3, len(x) // 10)
                
        except Exception:
            return 3  # Default fallback
    
    def _estimate_delay(self, x: np.ndarray) -> int:
        """Estimate delay using mutual information"""
        
        try:
            if self.nonlinear_available:
                tau = delay.dmi(x)
                return max(1, tau)
            else:
                # Simple autocorrelation-based estimate
                autocorr = np.correlate(x, x, mode='full')
                autocorr = autocorr[len(autocorr)//2:]
                autocorr = autocorr / autocorr[0]
                
                # Find first zero crossing or minimum
                zero_crossings = np.where(np.diff(np.sign(autocorr)))[0]
                if len(zero_crossings) > 0:
                    return max(1, zero_crossings[0])
                else:
                    return max(1, np.argmin(autocorr[:len(x)//4]))
                    
        except Exception:
            return 1  # Default fallback
    
    def _correlation_dimension(self, embedded: np.ndarray, r_min: float = 1e-3,
                              r_max: float = 1.0) -> float:
        """Compute correlation dimension of embedded time series"""
        
        try:
            if self.nonlinear_available:
                return dimension.correlation_dimension(embedded)
            else:
                # Simple approximation using pairwise distances
                n = len(embedded)
                if n < 10:
                    return 1.0
                
                # Sample subset for computational efficiency
                sample_size = min(n, 1000)
                indices = np.random.choice(n, sample_size, replace=False)
                sample_embedded = embedded[indices]
                
                # Compute pairwise distances
                distances = squareform(pdist(sample_embedded))
                
                # Count pairs within different radii
                radii = np.logspace(np.log10(r_min), np.log10(r_max), 20)
                counts = []
                
                for r in radii:
                    count = np.sum(distances < r) - len(distances)  # Exclude diagonal
                    counts.append(max(1, count))
                
                # Fit slope of log(count) vs log(radius)
                log_radii = np.log(radii)
                log_counts = np.log(counts)
                
                # Linear regression
                coeffs = np.polyfit(log_radii, log_counts, 1)
                correlation_dim = coeffs[0]  # Slope
                
                return max(0.1, min(correlation_dim, len(embedded[0])))
                
        except Exception:
            return 2.0  # Default fallback
    
    def _lyapunov_exponent(self, embedded: np.ndarray) -> float:
        """Compute largest Lyapunov exponent"""
        
        try:
            if self.nonlinear_available:
                return lyapunov.largest(embedded)
            else:
                # Simplified estimation
                n, dim = embedded.shape
                if n < 20:
                    return 0.1
                
                # Average divergence rate
                divergences = []
                
                for i in range(min(n-10, 50)):  # Sample for efficiency
                    # Find nearest neighbors
                    distances = np.linalg.norm(embedded - embedded[i], axis=1)
                    nearest_idx = np.argsort(distances)[1:6]  # Exclude self, take 5 nearest
                    
                    # Track divergence
                    for j in nearest_idx:
                        if i+5 < n and j+5 < n:
                            initial_dist = distances[j]
                            final_dist = np.linalg.norm(embedded[i+5] - embedded[j+5])
                            
                            if initial_dist > 1e-8 and final_dist > 1e-8:
                                divergence = np.log(final_dist / initial_dist) / 5
                                divergences.append(divergence)
                
                return np.mean(divergences) if divergences else 0.1
                
        except Exception:
            return 0.1  # Default positive value
    
    def _cross_correlation_dimension(self, x_embedded: np.ndarray, 
                                   y_embedded: np.ndarray) -> float:
        """Compute cross-correlation dimension between two embedded series"""
        
        try:
            # Create joint embedding
            min_len = min(len(x_embedded), len(y_embedded))
            joint_embedded = np.hstack([x_embedded[:min_len], y_embedded[:min_len]])
            
            # Compute correlation dimension of joint system
            return self._correlation_dimension(joint_embedded)
            
        except Exception:
            return 1.0
    
    def _mutual_false_nearest_neighbors(self, x: np.ndarray, y: np.ndarray,
                                      embedding_dim: int, delay: int) -> float:
        """Compute mutual false nearest neighbors"""
        
        try:
            # Simple approximation - fraction of shared nearest neighbors
            n = min(len(x), len(y))
            if n < 20:
                return 0.1
            
            # Embed both series
            x_embedded = delay.embed(x[:n], dim=embedding_dim, delay=delay)
            y_embedded = delay.embed(y[:n], dim=embedding_dim, delay=delay)
            
            # For each point in x_embedded, find nearest neighbors in both spaces
            shared_neighbors = 0
            total_neighbors = 0
            
            for i in range(min(len(x_embedded), 50)):  # Sample for efficiency
                # Distances in x space
                dist_x = np.linalg.norm(x_embedded - x_embedded[i], axis=1)
                nn_x = set(np.argsort(dist_x)[1:6])  # 5 nearest neighbors, excluding self
                
                # Distances in y space
                if i < len(y_embedded):
                    dist_y = np.linalg.norm(y_embedded - y_embedded[i], axis=1)
                    nn_y = set(np.argsort(dist_y)[1:6])
                    
                    # Count shared neighbors
                    shared = len(nn_x.intersection(nn_y))
                    shared_neighbors += shared
                    total_neighbors += 5
            
            return shared_neighbors / max(total_neighbors, 1)
            
        except Exception:
            return 0.1
    
    async def _nonlinear_cross_prediction(self, x: np.ndarray, y: np.ndarray) -> Dict[str, Any]:
        """Test nonlinear cross-prediction between series"""
        
        try:
            # Split data for cross-prediction
            split_point = len(x) // 2
            
            x_train, x_test = x[:split_point], x[split_point:]
            y_train, y_test = y[:split_point], y[split_point:]
            
            # Simple nonlinear prediction using local linear models
            prediction_errors = []
            
            for i in range(min(len(x_test), 20)):  # Sample for efficiency
                if i < len(y_test):
                    # Find similar patterns in training data
                    current_pattern = x_train[-5:]  # Use last 5 points as pattern
                    
                    # Find similar patterns in y training data
                    similarities = []
                    for j in range(5, len(y_train)):
                        pattern = y_train[j-5:j]
                        similarity = np.corrcoef(current_pattern, pattern)[0,1]
                        if not np.isnan(similarity):
                            similarities.append((similarity, j))
                    
                    if similarities:
                        # Use most similar pattern for prediction
                        similarities.sort(reverse=True)
                        best_idx = similarities[0][1]
                        
                        if best_idx < len(y_train):
                            prediction = y_train[best_idx]
                            error = abs(prediction - y_test[i])
                            prediction_errors.append(error)
            
            prediction_accuracy = 1.0 - (np.mean(prediction_errors) / (np.std(y_test) + 1e-6)) if prediction_errors else 0.5
            
            return {
                'cross_prediction_accuracy': float(max(0, min(prediction_accuracy, 1))),
                'mean_prediction_error': float(np.mean(prediction_errors)) if prediction_errors else 1.0,
                'n_predictions': len(prediction_errors)
            }
            
        except Exception as e:
            self.logger.error(f"Nonlinear cross-prediction failed: {e}")
            return {
                'cross_prediction_accuracy': 0.5,
                'mean_prediction_error': 1.0,
                'n_predictions': 0
            }
    
    async def _nonlinear_significance_test(self, x: np.ndarray, y: np.ndarray,
                                         observed_coupling: float,
                                         n_surrogates: int = 50) -> float:
        """Test significance of nonlinear coupling using surrogates"""
        
        try:
            surrogate_couplings = []
            
            for _ in range(n_surrogates):
                # Generate surrogate by shuffling
                y_surrogate = np.random.permutation(y)
                
                # Compute coupling for surrogate (simplified)
                try:
                    embedding_dim = 3  # Fixed for surrogates
                    delay = 1
                    
                    x_embedded = delay.embed(x, dim=embedding_dim, delay=delay)
                    y_embedded = delay.embed(y_surrogate, dim=embedding_dim, delay=delay)
                    
                    corr_dim_x = self._correlation_dimension(x_embedded)
                    corr_dim_y = self._correlation_dimension(y_embedded)
                    cross_corr_dim = self._cross_correlation_dimension(x_embedded, y_embedded)
                    
                    coupling = cross_corr_dim / max(corr_dim_x, corr_dim_y, 1e-6)
                    surrogate_couplings.append(coupling)
                    
                except Exception:
                    surrogate_couplings.append(np.random.random() * 0.5)
            
            # Compute p-value
            p_value = np.mean(np.array(surrogate_couplings) >= observed_coupling)
            return float(p_value)
            
        except Exception:
            return 0.5  # Default p-value
    
    # Fallback methods for when advanced libraries are not available
    
    async def _fallback_coherence_test(self, x: np.ndarray, y: np.ndarray) -> Dict[str, Any]:
        """Fallback coherence test using basic correlation"""
        
        try:
            corr, p_val = stats.pearsonr(x, y)
            
            return {
                'test_statistic': float(abs(corr)),
                'max_coherence': float(abs(corr)),
                'p_value': float(p_val),
                'significant': p_val < self.significance_level,
                'method': 'fallback_correlation'
            }
            
        except Exception as e:
            self.logger.error(f"Fallback coherence test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False}
    
    async def _fallback_emd_test(self, x: np.ndarray, y: np.ndarray) -> Dict[str, Any]:
        """Fallback EMD test using simple correlation"""
        
        return await self._fallback_coherence_test(x, y)
    
    async def _fallback_spectral_test(self, x: np.ndarray, y: np.ndarray) -> Dict[str, Any]:
        """Fallback spectral test using FFT correlation"""
        
        try:
            # Simple FFT-based correlation
            fft_x = np.fft.fft(x)
            fft_y = np.fft.fft(y)
            
            cross_spectrum = fft_x * np.conj(fft_y)
            coherence_fft = np.abs(cross_spectrum)**2 / (np.abs(fft_x)**2 * np.abs(fft_y)**2 + 1e-10)
            
            mean_coherence = np.mean(coherence_fft)
            
            return {
                'test_statistic': float(mean_coherence),
                'p_value': 1.0 - mean_coherence,  # Approximate
                'significant': mean_coherence > 0.5,
                'method': 'fallback_fft_coherence'
            }
            
        except Exception as e:
            self.logger.error(f"Fallback spectral test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False}
    
    async def _fallback_nonlinear_test(self, x: np.ndarray, y: np.ndarray) -> Dict[str, Any]:
        """Fallback nonlinear test using rank correlation"""
        
        try:
            # Spearman correlation as nonlinear measure
            corr, p_val = stats.spearmanr(x, y)
            
            return {
                'test_statistic': float(abs(corr)),
                'p_value': float(p_val),
                'significant': p_val < self.significance_level,
                'method': 'fallback_spearman'
            }
            
        except Exception as e:
            self.logger.error(f"Fallback nonlinear test failed: {e}")
            return {'test_statistic': 0.0, 'p_value': 1.0, 'significant': False}


# ================================================================================================
# Graph Neural Network Independence Testing Engine
# ================================================================================================

class GNNIndependenceTestingEngine:
    """
    Advanced Graph Neural Network-based independence testing engine.
    Implements multiple GNN architectures for detecting complex relationships
    between variables through graph-based learning approaches.
    """
    def __init__(self, device: str = 'cuda', batch_size: int = 64, 
                 learning_rate: float = 0.001, num_epochs: int = 100,
                 hidden_dim: int = 128, num_layers: int = 3,
                 dropout: float = 0.2, attention_heads: int = 8):
        """
        Initialize GNN Independence Testing Engine.
        
        Args:
            device: Computing device ('cuda' or 'cpu')
            batch_size: Batch size for training
            learning_rate: Learning rate for optimization
            num_epochs: Number of training epochs
            hidden_dim: Hidden dimension size
            num_layers: Number of GNN layers
            dropout: Dropout probability
            attention_heads: Number of attention heads for GAT
        """
        try:
            import torch
            import torch.nn as nn
            import torch.nn.functional as F
            import torch_geometric
            from torch_geometric.nn import GCNConv, GATConv, SAGEConv, TransformerConv
            from torch_geometric.nn import global_mean_pool, global_max_pool, global_add_pool
            from torch_geometric.data import Data, DataLoader
            from sklearn.model_selection import StratifiedKFold
            from sklearn.metrics import roc_auc_score, accuracy_score
            
            self.torch = torch
            self.nn = nn
            self.F = F
            self.geometric = torch_geometric
            self.GCNConv = GCNConv
            self.GATConv = GATConv
            self.SAGEConv = SAGEConv
            self.TransformerConv = TransformerConv
            self.global_mean_pool = global_mean_pool
            self.global_max_pool = global_max_pool
            self.global_add_pool = global_add_pool
            self.Data = Data
            self.DataLoader = DataLoader
            self.StratifiedKFold = StratifiedKFold
            self.roc_auc_score = roc_auc_score
            self.accuracy_score = accuracy_score
            self.pytorch_available = True
            
        except ImportError as e:
            logger.error(f"Failed to import PyTorch Geometric dependencies: {e}")
            self.torch = None
            self.pytorch_available = False
            
        self.device = device if device == 'cpu' or (self.pytorch_available and self.torch.cuda.is_available()) else 'cpu'
        self.batch_size = batch_size
        self.learning_rate = learning_rate
        self.num_epochs = num_epochs
        self.hidden_dim = hidden_dim
        self.num_layers = num_layers
        self.dropout = dropout
        self.attention_heads = attention_heads
        
        # Initialize models dictionary
        self.models = {}
        self.trained_models = {}
        self.optimizers = {}
        self.schedulers = {}
        
        # Performance monitoring
        self.training_stats = defaultdict(list)
        self.test_results_cache = {}
        
        # Create model instances
        self._initialize_models()
        
        logger.info(f"GNNIndependenceTestingEngine initialized with device: {self.device}")
        
    def _initialize_models(self):
        """Initialize all GNN model architectures."""
        if not self.pytorch_available:
            logger.warning("PyTorch not available, using fallback implementation")
            return
            
        try:
            # Graph Convolutional Network
            self.models['gcn'] = self._create_gcn_model()
            
            # Graph Attention Network
            self.models['gat'] = self._create_gat_model()
            
            # GraphSAGE
            self.models['sage'] = self._create_sage_model()
            
            # Graph Transformer
            self.models['transformer'] = self._create_transformer_model()
            
            # Custom Independence Detection Model
            self.models['independence'] = self._create_independence_model()
            
            # Move models to device and initialize optimizers
            for name, model in self.models.items():
                if model is not None:
                    model = model.to(self.device)
                    self.models[name] = model
                    self.optimizers[name] = self.torch.optim.AdamW(
                        model.parameters(), lr=self.learning_rate, weight_decay=1e-4
                    )
                    self.schedulers[name] = self.torch.optim.lr_scheduler.CosineAnnealingLR(
                        self.optimizers[name], T_max=self.num_epochs
                    )
            
        except Exception as e:
            logger.error(f"Error initializing GNN models: {e}")
            
    def _create_gcn_model(self):
        """Create Graph Convolutional Network model."""
        class GCNIndependenceModel(self.nn.Module):
            def __init__(self, input_dim, hidden_dim, num_layers, dropout):
                super().__init__()
                self.convs = self.nn.ModuleList()
                self.batch_norms = self.nn.ModuleList()
                
                # First layer
                self.convs.append(self.GCNConv(input_dim, hidden_dim))
                self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Hidden layers
                for _ in range(num_layers - 2):
                    self.convs.append(self.GCNConv(hidden_dim, hidden_dim))
                    self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Output layer
                self.convs.append(self.GCNConv(hidden_dim, hidden_dim))
                self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Classification head
                self.classifier = self.nn.Sequential(
                    self.nn.Linear(hidden_dim * 3, hidden_dim),
                    self.nn.ReLU(),
                    self.nn.Dropout(dropout),
                    self.nn.Linear(hidden_dim, hidden_dim // 2),
                    self.nn.ReLU(),
                    self.nn.Dropout(dropout),
                    self.nn.Linear(hidden_dim // 2, 2)  # Independent/Dependent
                )
                
                self.dropout = dropout
                
            def forward(self, x, edge_index, batch):
                # Graph convolution layers
                for conv, bn in zip(self.convs, self.batch_norms):
                    x = conv(x, edge_index)
                    x = bn(x)
                    x = self.F.relu(x)
                    x = self.F.dropout(x, p=self.dropout, training=self.training)
                
                # Global pooling
                x_mean = self.global_mean_pool(x, batch)
                x_max = self.global_max_pool(x, batch)
                x_sum = self.global_add_pool(x, batch)
                
                # Concatenate pooled representations
                x = self.torch.cat([x_mean, x_max, x_sum], dim=1)
                
                # Classification
                out = self.classifier(x)
                return out
                
        return GCNIndependenceModel(
            input_dim=2,  # X and Y variables
            hidden_dim=self.hidden_dim,
            num_layers=self.num_layers,
            dropout=self.dropout
        )
        
    def _create_gat_model(self):
        """Create Graph Attention Network model."""
        class GATIndependenceModel(self.nn.Module):
            def __init__(self, input_dim, hidden_dim, num_layers, dropout, attention_heads):
                super().__init__()
                self.convs = self.nn.ModuleList()
                self.batch_norms = self.nn.ModuleList()
                
                # First layer
                self.convs.append(self.GATConv(
                    input_dim, hidden_dim // attention_heads, 
                    heads=attention_heads, dropout=dropout
                ))
                self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Hidden layers
                for _ in range(num_layers - 2):
                    self.convs.append(self.GATConv(
                        hidden_dim, hidden_dim // attention_heads, 
                        heads=attention_heads, dropout=dropout
                    ))
                    self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Output layer (single head)
                self.convs.append(self.GATConv(
                    hidden_dim, hidden_dim, heads=1, dropout=dropout
                ))
                self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Classification head with attention mechanism
                self.attention = self.nn.MultiheadAttention(hidden_dim, num_heads=4)
                self.classifier = self.nn.Sequential(
                    self.nn.Linear(hidden_dim * 3, hidden_dim),
                    self.nn.ReLU(),
                    self.nn.Dropout(dropout),
                    self.nn.Linear(hidden_dim, hidden_dim // 2),
                    self.nn.ReLU(),
                    self.nn.Dropout(dropout),
                    self.nn.Linear(hidden_dim // 2, 2)
                )
                
                self.dropout = dropout
                self.attention_heads = attention_heads
                
            def forward(self, x, edge_index, batch):
                # Graph attention layers
                for i, (conv, bn) in enumerate(zip(self.convs, self.batch_norms)):
                    x = conv(x, edge_index)
                    if i < len(self.convs) - 1:  # Not the last layer
                        x = x.view(-1, self.attention_heads * (self.hidden_dim // self.attention_heads))
                    x = bn(x)
                    x = self.F.elu(x)
                    x = self.F.dropout(x, p=self.dropout, training=self.training)
                
                # Global pooling with attention
                x_mean = self.global_mean_pool(x, batch)
                x_max = self.global_max_pool(x, batch)
                x_sum = self.global_add_pool(x, batch)
                
                # Concatenate and apply self-attention
                x_pooled = self.torch.cat([x_mean, x_max, x_sum], dim=1)
                x_pooled = x_pooled.unsqueeze(0)  # Add sequence dimension
                attn_out, _ = self.attention(x_pooled, x_pooled, x_pooled)
                x_pooled = attn_out.squeeze(0)
                
                # Classification
                out = self.classifier(x_pooled)
                return out
                
        return GATIndependenceModel(
            input_dim=2,
            hidden_dim=self.hidden_dim,
            num_layers=self.num_layers,
            dropout=self.dropout,
            attention_heads=self.attention_heads
        )
        
    def _create_sage_model(self):
        """Create GraphSAGE model."""
        class SAGEIndependenceModel(self.nn.Module):
            def __init__(self, input_dim, hidden_dim, num_layers, dropout):
                super().__init__()
                self.convs = self.nn.ModuleList()
                self.batch_norms = self.nn.ModuleList()
                
                # First layer
                self.convs.append(self.SAGEConv(input_dim, hidden_dim))
                self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Hidden layers
                for _ in range(num_layers - 2):
                    self.convs.append(self.SAGEConv(hidden_dim, hidden_dim))
                    self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Output layer
                self.convs.append(self.SAGEConv(hidden_dim, hidden_dim))
                self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Adaptive pooling and classification
                self.adaptive_pool = self.nn.AdaptiveAvgPool1d(1)
                self.classifier = self.nn.Sequential(
                    self.nn.Linear(hidden_dim * 3, hidden_dim * 2),
                    self.nn.ReLU(),
                    self.nn.Dropout(dropout),
                    self.nn.Linear(hidden_dim * 2, hidden_dim),
                    self.nn.ReLU(),
                    self.nn.Dropout(dropout),
                    self.nn.Linear(hidden_dim, 2)
                )
                
                self.dropout = dropout
                
            def forward(self, x, edge_index, batch):
                # SAGE convolution layers
                for conv, bn in zip(self.convs, self.batch_norms):
                    x = conv(x, edge_index)
                    x = bn(x)
                    x = self.F.relu(x)
                    x = self.F.dropout(x, p=self.dropout, training=self.training)
                
                # Multiple pooling strategies
                x_mean = self.global_mean_pool(x, batch)
                x_max = self.global_max_pool(x, batch)
                x_sum = self.global_add_pool(x, batch)
                
                # Combine pooled representations
                x = self.torch.cat([x_mean, x_max, x_sum], dim=1)
                
                # Classification
                out = self.classifier(x)
                return out
                
        return SAGEIndependenceModel(
            input_dim=2,
            hidden_dim=self.hidden_dim,
            num_layers=self.num_layers,
            dropout=self.dropout
        )
        
    def _create_transformer_model(self):
        """Create Graph Transformer model."""
        class TransformerIndependenceModel(self.nn.Module):
            def __init__(self, input_dim, hidden_dim, num_layers, dropout, attention_heads):
                super().__init__()
                self.convs = self.nn.ModuleList()
                self.batch_norms = self.nn.ModuleList()
                self.hidden_dim = hidden_dim
                
                # Transformer layers
                for i in range(num_layers):
                    self.convs.append(self.TransformerConv(
                        input_dim if i == 0 else hidden_dim,
                        hidden_dim,
                        heads=attention_heads,
                        dropout=dropout
                    ))
                    self.batch_norms.append(self.nn.BatchNorm1d(hidden_dim))
                
                # Position encoding
                self.pos_encoding = self.nn.Parameter(
                    self.torch.randn(1000, hidden_dim)  # Max 1000 nodes
                )
                
                # Multi-head self-attention for final pooling
                self.final_attention = self.nn.MultiheadAttention(
                    hidden_dim, num_heads=attention_heads
                )
                
                # Classification with residual connections
                self.classifier = self.nn.Sequential(
                    self.nn.Linear(hidden_dim * 3, hidden_dim * 2),
                    self.nn.LayerNorm(hidden_dim * 2),
                    self.nn.ReLU(),
                    self.nn.Dropout(dropout),
                    self.nn.Linear(hidden_dim * 2, hidden_dim),
                    self.nn.LayerNorm(hidden_dim),
                    self.nn.ReLU(),
                    self.nn.Dropout(dropout),
                    self.nn.Linear(hidden_dim, 2)
                )
                
                self.dropout = dropout
                
            def forward(self, x, edge_index, batch):
                # Add positional encoding
                num_nodes = x.size(0)
                if num_nodes <= self.pos_encoding.size(0):
                    x = x + self.pos_encoding[:num_nodes]
                
                # Transformer convolution layers with residual connections
                for i, (conv, bn) in enumerate(zip(self.convs, self.batch_norms)):
                    residual = x if x.size(-1) == self.hidden_dim else None
                    x = conv(x, edge_index)
                    x = bn(x)
                    x = self.F.gelu(x)
                    if residual is not None:
                        x = x + residual  # Residual connection
                    x = self.F.dropout(x, p=self.dropout, training=self.training)
                
                # Global pooling with attention
                x_mean = self.global_mean_pool(x, batch)
                x_max = self.global_max_pool(x, batch)
                x_sum = self.global_add_pool(x, batch)
                
                # Self-attention on pooled features
                pooled_features = self.torch.stack([x_mean, x_max, x_sum], dim=0)
                attn_out, _ = self.final_attention(
                    pooled_features, pooled_features, pooled_features
                )
                x_final = attn_out.transpose(0, 1).flatten(1)
                
                # Classification
                out = self.classifier(x_final)
                return out
                
        return TransformerIndependenceModel(
            input_dim=2,
            hidden_dim=self.hidden_dim,
            num_layers=self.num_layers,
            dropout=self.dropout,
            attention_heads=self.attention_heads
        )
        
    def _create_independence_model(self):
        """Create custom independence detection model combining multiple architectures."""
        class EnsembleIndependenceModel(self.nn.Module):
            def __init__(self, gcn_model, gat_model, sage_model, transformer_model, hidden_dim):
                super().__init__()
                self.gcn_model = gcn_model
                self.gat_model = gat_model
                self.sage_model = sage_model
                self.transformer_model = transformer_model
                
                # Ensemble combination layer
                self.ensemble_layer = self.nn.Sequential(
                    self.nn.Linear(8, hidden_dim),  # 4 models × 2 outputs each
                    self.nn.ReLU(),
                    self.nn.Dropout(0.3),
                    self.nn.Linear(hidden_dim, hidden_dim // 2),
                    self.nn.ReLU(),
                    self.nn.Dropout(0.2),
                    self.nn.Linear(hidden_dim // 2, 2)
                )
                
                # Attention weights for ensemble
                self.attention_weights = self.nn.Parameter(
                    self.torch.ones(4) / 4  # Equal weights initially
                )
                
            def forward(self, x, edge_index, batch):
                # Get predictions from all models
                gcn_out = self.F.softmax(self.gcn_model(x, edge_index, batch), dim=1)
                gat_out = self.F.softmax(self.gat_model(x, edge_index, batch), dim=1)
                sage_out = self.F.softmax(self.sage_model(x, edge_index, batch), dim=1)
                transformer_out = self.F.softmax(self.transformer_model(x, edge_index, batch), dim=1)
                
                # Concatenate all predictions
                all_predictions = self.torch.cat([
                    gcn_out, gat_out, sage_out, transformer_out
                ], dim=1)
                
                # Ensemble prediction
                ensemble_out = self.ensemble_layer(all_predictions)
                
                # Weighted combination with attention
                weights = self.F.softmax(self.attention_weights, dim=0)
                weighted_out = (
                    weights[0] * gcn_out +
                    weights[1] * gat_out +
                    weights[2] * sage_out +
                    weights[3] * transformer_out
                )
                
                # Final output combines ensemble and weighted predictions
                final_out = 0.7 * ensemble_out + 0.3 * weighted_out
                
                return final_out
        
        # Only create ensemble if individual models exist
        if all(self.models.get(name) is not None for name in ['gcn', 'gat', 'sage', 'transformer']):
            return EnsembleIndependenceModel(
                gcn_model=self.models['gcn'],
                gat_model=self.models['gat'],
                sage_model=self.models['sage'],
                transformer_model=self.models['transformer'],
                hidden_dim=self.hidden_dim
            )
        else:
            return None
    
    async def test_independence(self, X: np.ndarray, Y: np.ndarray, 
                              model_type: str = 'ensemble', 
                              train_on_data: bool = True) -> Dict[str, Any]:
        """
        Test independence between X and Y using Graph Neural Networks.
        
        Args:
            X: First variable data
            Y: Second variable data  
            model_type: Type of GNN model to use ('gcn', 'gat', 'sage', 'transformer', 'ensemble')
            train_on_data: Whether to train model on the data or use pre-trained
            
        Returns:
            Dictionary containing test results, p-values, and confidence scores
        """
        if not self.pytorch_available:
            return await self._fallback_independence_test(X, Y)
        
        start_time = time.time()
        
        try:
            # Prepare graph data from variables
            graph_data = await self._prepare_graph_data(X, Y)
            
            # Select model
            if model_type not in self.models or self.models[model_type] is None:
                logger.warning(f"Model {model_type} not available, using GCN fallback")
                model_type = 'gcn'
                
            model = self.models[model_type]
            
            if train_on_data:
                # Train model on the data
                training_results = await self._train_model(model, model_type, graph_data)
                self.training_stats[model_type].append(training_results)
            
            # Test independence
            independence_score = await self._predict_independence(model, graph_data)
            
            # Cross-validation for robustness
            cv_scores = await self._cross_validate_independence(model_type, graph_data)
            
            # Statistical significance testing
            p_value = await self._compute_gnn_p_value(X, Y, model_type, independence_score)
            
            computation_time = time.time() - start_time
            
            results = {
                'test_statistic': float(independence_score),
                'p_value': float(p_value),
                'significant': p_value < 0.05,
                'method': f'gnn_{model_type}',
                'model_type': model_type,
                'cv_scores': cv_scores,
                'confidence': float(np.mean(cv_scores)),
                'computation_time': computation_time,
                'graph_properties': {
                    'num_nodes': len(graph_data['node_features']),
                    'num_edges': len(graph_data['edge_index'][0]) if 'edge_index' in graph_data else 0
                }
            }
            
            if train_on_data:
                results['training_results'] = training_results
                
            # Cache results
            cache_key = f"{hash(X.tobytes())}_{hash(Y.tobytes())}_{model_type}"
            self.test_results_cache[cache_key] = results
            
            return results
            
        except Exception as e:
            logger.error(f"GNN independence test failed: {e}")
            return await self._fallback_independence_test(X, Y)
    
    async def _prepare_graph_data(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """
        Convert variable data into graph format for GNN processing.
        
        Creates graphs where nodes represent data points and edges represent
        relationships based on proximity, correlation, or mutual information.
        """
        n_samples = len(X)
        
        # Ensure 2D arrays
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        if Y.ndim == 1:
            Y = Y.reshape(-1, 1)
        
        # Create node features (X and Y values for each sample)
        node_features = np.column_stack([
            X.flatten() if X.shape[1] == 1 else X[:, 0],
            Y.flatten() if Y.shape[1] == 1 else Y[:, 0]
        ])
        
        # Normalize features
        from sklearn.preprocessing import StandardScaler
        scaler = StandardScaler()
        node_features = scaler.fit_transform(node_features)
        
        # Create edges based on k-nearest neighbors in feature space
        k = min(10, max(3, int(np.sqrt(n_samples))))  # Adaptive k
        from sklearn.neighbors import NearestNeighbors
        
        nn = NearestNeighbors(n_neighbors=k+1)
        nn.fit(node_features)
        distances, indices = nn.kneighbors(node_features)
        
        # Build edge index (exclude self-connections)
        edge_list = []
        for i, neighbors in enumerate(indices):
            for j in neighbors[1:]:  # Skip first neighbor (self)
                edge_list.append([i, j])
                edge_list.append([j, i])  # Add reverse edge for undirected graph
        
        edge_index = np.array(edge_list).T if edge_list else np.array([[], []], dtype=int)
        
        # Create labels for independence (1 = independent, 0 = dependent)
        # Use mutual information as a proxy for creating training labels
        from sklearn.feature_selection import mutual_info_regression
        
        try:
            mi = mutual_info_regression(
                X.reshape(-1, 1) if X.ndim > 1 and X.shape[1] > 1 else X,
                Y.flatten() if Y.ndim > 1 else Y
            )[0]
            
            # Threshold based on empirical distribution
            independence_threshold = 0.1  # Can be tuned
            is_independent = mi < independence_threshold
            
        except Exception:
            # Fallback: use correlation
            corr = np.corrcoef(X.flatten(), Y.flatten())[0, 1]
            is_independent = abs(corr) < 0.2
        
        # Create batch labels for graph-level prediction
        batch_labels = np.array([1 if is_independent else 0] * n_samples)
        
        return {
            'node_features': node_features.astype(np.float32),
            'edge_index': edge_index.astype(np.int64),
            'labels': batch_labels,
            'is_independent': is_independent,
            'n_samples': n_samples,
            'k_neighbors': k,
            'scaler': scaler
        }
    
    async def _train_model(self, model, model_type: str, graph_data: Dict[str, Any]) -> Dict[str, Any]:
        """Train GNN model on the graph data."""
        if not self.pytorch_available:
            return {'error': 'PyTorch not available'}
        
        model.train()
        optimizer = self.optimizers[model_type]
        scheduler = self.schedulers[model_type]
        criterion = self.nn.CrossEntropyLoss()
        
        # Prepare data
        node_features = self.torch.FloatTensor(graph_data['node_features']).to(self.device)
        edge_index = self.torch.LongTensor(graph_data['edge_index']).to(self.device)
        labels = self.torch.LongTensor(graph_data['labels']).to(self.device)
        
        # Create batch indices (all nodes belong to single graph)
        batch = self.torch.zeros(len(node_features), dtype=self.torch.long).to(self.device)
        
        training_losses = []
        training_accuracies = []
        
        for epoch in range(self.num_epochs):
            optimizer.zero_grad()
            
            # Forward pass
            outputs = model(node_features, edge_index, batch)
            
            # For graph-level prediction, we need one output per graph
            # Since we have one graph, take the mean/max of node predictions
            graph_output = self.torch.mean(outputs, dim=0, keepdim=True)
            graph_label = self.torch.tensor([graph_data['is_independent']], dtype=self.torch.long).to(self.device)
            
            loss = criterion(graph_output, graph_label)
            
            # Backward pass
            loss.backward()
            
            # Gradient clipping for stability
            self.torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
            
            optimizer.step()
            scheduler.step()
            
            # Track metrics
            training_losses.append(loss.item())
            
            with self.torch.no_grad():
                pred = self.torch.argmax(graph_output, dim=1)
                acc = (pred == graph_label).float().mean()
                training_accuracies.append(acc.item())
                
            if (epoch + 1) % 20 == 0:
                logger.debug(f"Epoch {epoch+1}/{self.num_epochs}, Loss: {loss.item():.4f}, Acc: {acc.item():.4f}")
        
        return {
            'final_loss': training_losses[-1],
            'final_accuracy': training_accuracies[-1],
            'loss_history': training_losses,
            'accuracy_history': training_accuracies,
            'epochs_trained': self.num_epochs
        }
    
    async def _predict_independence(self, model, graph_data: Dict[str, Any]) -> float:
        """Predict independence score using trained model."""
        if not self.pytorch_available:
            return 0.5
        
        model.eval()
        
        with self.torch.no_grad():
            node_features = self.torch.FloatTensor(graph_data['node_features']).to(self.device)
            edge_index = self.torch.LongTensor(graph_data['edge_index']).to(self.device)
            batch = self.torch.zeros(len(node_features), dtype=self.torch.long).to(self.device)
            
            outputs = model(node_features, edge_index, batch)
            
            # Get graph-level prediction
            graph_output = self.torch.mean(outputs, dim=0)
            probabilities = self.F.softmax(graph_output, dim=0)
            
            # Return probability of independence
            independence_score = probabilities[1].item()  # Index 1 = independent
            
            return independence_score
    
    async def _cross_validate_independence(self, model_type: str, graph_data: Dict[str, Any], 
                                         n_folds: int = 5) -> List[float]:
        """Perform cross-validation for robust independence testing."""
        if not self.pytorch_available:
            return [0.5] * n_folds
        
        # Create multiple subgraphs for cross-validation
        n_samples = graph_data['n_samples']
        fold_size = max(1, n_samples // n_folds)
        
        cv_scores = []
        
        for fold in range(n_folds):
            try:
                # Create train/test split
                start_idx = fold * fold_size
                end_idx = min((fold + 1) * fold_size, n_samples)
                
                # Use a subset of nodes for this fold
                test_indices = np.arange(start_idx, end_idx)
                train_indices = np.concatenate([
                    np.arange(0, start_idx),
                    np.arange(end_idx, n_samples)
                ])
                
                if len(train_indices) == 0 or len(test_indices) == 0:
                    cv_scores.append(0.5)
                    continue
                
                # Create fold-specific graph data
                fold_data = {
                    'node_features': graph_data['node_features'][test_indices],
                    'edge_index': self._filter_edges(graph_data['edge_index'], test_indices),
                    'labels': graph_data['labels'][test_indices],
                    'is_independent': graph_data['is_independent'],
                    'n_samples': len(test_indices)
                }
                
                # Create a fresh model for this fold
                model = self.models[model_type].__class__(
                    input_dim=2,
                    hidden_dim=self.hidden_dim,
                    num_layers=self.num_layers,
                    dropout=self.dropout,
                    **({"attention_heads": self.attention_heads} if model_type in ['gat', 'transformer'] else {})
                ).to(self.device)
                
                # Quick training on remaining data
                optimizer = self.torch.optim.Adam(model.parameters(), lr=self.learning_rate)
                model.train()
                
                # Limited training for CV
                for _ in range(10):  # Reduced epochs for CV
                    optimizer.zero_grad()
                    
                    train_features = self.torch.FloatTensor(graph_data['node_features'][train_indices]).to(self.device)
                    train_edges = self._filter_edges(graph_data['edge_index'], train_indices)
                    train_edges = self.torch.LongTensor(train_edges).to(self.device)
                    train_batch = self.torch.zeros(len(train_features), dtype=self.torch.long).to(self.device)
                    
                    if len(train_edges) == 0:
                        break
                    
                    outputs = model(train_features, train_edges, train_batch)
                    graph_output = self.torch.mean(outputs, dim=0, keepdim=True)
                    
                    # Simple loss based on independence label
                    target = self.torch.tensor([1 if graph_data['is_independent'] else 0], 
                                             dtype=self.torch.long).to(self.device)
                    loss = self.nn.CrossEntropyLoss()(graph_output, target)
                    
                    loss.backward()
                    optimizer.step()
                
                # Predict on test fold
                independence_score = await self._predict_independence(model, fold_data)
                cv_scores.append(independence_score)
                
            except Exception as e:
                logger.warning(f"CV fold {fold} failed: {e}")
                cv_scores.append(0.5)
        
        return cv_scores
    
    def _filter_edges(self, edge_index: np.ndarray, node_indices: np.ndarray) -> np.ndarray:
        """Filter edges to include only those between specified nodes."""
        if len(edge_index) == 0 or edge_index.shape[1] == 0:
            return np.array([[], []], dtype=int)
        
        # Create mapping from old indices to new indices
        index_map = {old_idx: new_idx for new_idx, old_idx in enumerate(node_indices)}
        
        # Filter edges
        filtered_edges = []
        for i in range(edge_index.shape[1]):
            src, dst = edge_index[0, i], edge_index[1, i]
            if src in index_map and dst in index_map:
                filtered_edges.append([index_map[src], index_map[dst]])
        
        if filtered_edges:
            return np.array(filtered_edges).T
        else:
            return np.array([[], []], dtype=int)
    
    async def _compute_gnn_p_value(self, X: np.ndarray, Y: np.ndarray, 
                                 model_type: str, observed_score: float,
                                 n_permutations: int = 100) -> float:
        """Compute p-value using permutation testing."""
        
        permutation_scores = []
        
        for _ in range(n_permutations):
            # Permute Y to break potential dependence
            Y_perm = np.random.permutation(Y)
            
            try:
                # Create graph data for permuted variables
                perm_graph_data = await self._prepare_graph_data(X, Y_perm)
                
                # Get model (use pre-trained if available)
                model = self.models[model_type]
                
                # Predict independence for permuted data
                perm_score = await self._predict_independence(model, perm_graph_data)
                permutation_scores.append(perm_score)
                
            except Exception as e:
                logger.warning(f"Permutation test iteration failed: {e}")
                permutation_scores.append(0.5)  # Default neutral score
        
        # Compute p-value
        # Under null hypothesis (independence), we expect high independence scores
        # P-value is proportion of permutation scores >= observed score
        p_value = np.mean(np.array(permutation_scores) >= observed_score)
        
        return max(0.001, min(0.999, p_value))  # Clamp to reasonable range
    
    async def _fallback_independence_test(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """Fallback independence test when PyTorch is not available."""
        try:
            from scipy.stats import pearsonr, spearmanr
            
            # Use correlation-based test
            X_flat = X.flatten() if X.ndim > 1 else X
            Y_flat = Y.flatten() if Y.ndim > 1 else Y
            
            # Pearson correlation
            pearson_r, pearson_p = pearsonr(X_flat, Y_flat)
            
            # Spearman correlation (nonlinear relationships)
            spearman_r, spearman_p = spearmanr(X_flat, Y_flat)
            
            # Combine results
            combined_stat = (abs(pearson_r) + abs(spearman_r)) / 2
            combined_p = min(pearson_p, spearman_p) * 2  # Bonferroni correction
            
            return {
                'test_statistic': float(1 - combined_stat),  # Convert to independence score
                'p_value': float(min(0.999, combined_p)),
                'significant': combined_p < 0.05,
                'method': 'fallback_correlation',
                'pearson_r': float(pearson_r),
                'spearman_r': float(spearman_r),
                'note': 'PyTorch not available, using correlation fallback'
            }
            
        except Exception as e:
            logger.error(f"Fallback independence test failed: {e}")
            return {
                'test_statistic': 0.5,
                'p_value': 0.5,
                'significant': False,
                'method': 'fallback_failed',
                'error': str(e)
            }
    
    def get_model_summary(self, model_type: str) -> Dict[str, Any]:
        """Get summary information about a specific model."""
        if model_type not in self.models or self.models[model_type] is None:
            return {'error': f'Model {model_type} not available'}
        
        model = self.models[model_type]
        
        if not self.pytorch_available:
            return {'error': 'PyTorch not available'}
        
        # Count parameters
        total_params = sum(p.numel() for p in model.parameters())
        trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
        
        return {
            'model_type': model_type,
            'total_parameters': total_params,
            'trainable_parameters': trainable_params,
            'device': str(self.device),
            'architecture': str(model.__class__.__name__),
            'hidden_dim': self.hidden_dim,
            'num_layers': self.num_layers,
            'dropout': self.dropout,
            'training_stats': self.training_stats.get(model_type, []),
            'has_trained': len(self.training_stats.get(model_type, [])) > 0
        }
    
    def get_all_models_summary(self) -> Dict[str, Dict[str, Any]]:
        """Get summary for all available models."""
        summaries = {}
        for model_type in self.models.keys():
            summaries[model_type] = self.get_model_summary(model_type)
        return summaries


class CausalDiscoveryEngine:
    """
    Advanced causal discovery algorithms implementation with multiple state-of-the-art methods.
    
    Implements PC, GES, NOTEARS, LiNGAM, and other causal discovery algorithms with
    comprehensive validation, statistical testing, and ensemble methods.
    """
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        """Initialize causal discovery engine"""
        self.config = config or {}
        self.logger = logging.getLogger(__name__)
        
        # Performance monitoring
        global performance_monitor
        self.performance_monitor = performance_monitor
        
        # Algorithm configurations
        self.pc_config = self.config.get('pc', {})
        self.ges_config = self.config.get('ges', {})
        self.notears_config = self.config.get('notears', {})
        self.lingam_config = self.config.get('lingam', {})
        
        # Statistical test configurations
        self.alpha = self.config.get('alpha', 0.05)
        self.max_iter = self.config.get('max_iter', 1000)
        self.tolerance = self.config.get('tolerance', 1e-6)
        
        # Initialize conditional independence tester
        self.ci_tester = self._initialize_ci_tester()
        
        # Cache for computed results
        self.result_cache = {}
        
        self.logger.info("CausalDiscoveryEngine initialized successfully")
    
    def _initialize_ci_tester(self) -> Any:
        """Initialize conditional independence tester"""
        try:
            # Try to use the previously implemented independence tester
            ci_config = self.config.get('conditional_independence', {})
            
            # Create a simple CI tester if the full system isn't available
            class SimpleCITester:
                def __init__(self):
                    self.alpha = 0.05
                
                def independence_test(self, X: np.ndarray, Y: np.ndarray, Z: Optional[np.ndarray] = None) -> Dict[str, Any]:
                    """Simple partial correlation-based independence test"""
                    try:
                        if Z is None or Z.size == 0:
                            # Pearson correlation test
                            from scipy.stats import pearsonr
                            corr, p_value = pearsonr(X.flatten(), Y.flatten())
                            return {
                                'statistic': abs(corr),
                                'p_value': p_value,
                                'independent': p_value > self.alpha,
                                'method': 'pearson_correlation'
                            }
                        else:
                            # Partial correlation test
                            from sklearn.linear_model import LinearRegression
                            
                            # Regress X on Z
                            Z_reshaped = Z.reshape(-1, Z.shape[-1] if Z.ndim > 1 else 1)
                            reg_x = LinearRegression().fit(Z_reshaped, X.flatten())
                            X_residual = X.flatten() - reg_x.predict(Z_reshaped)
                            
                            # Regress Y on Z
                            reg_y = LinearRegression().fit(Z_reshaped, Y.flatten())
                            Y_residual = Y.flatten() - reg_y.predict(Z_reshaped)
                            
                            # Test independence of residuals
                            from scipy.stats import pearsonr
                            corr, p_value = pearsonr(X_residual, Y_residual)
                            return {
                                'statistic': abs(corr),
                                'p_value': p_value,
                                'independent': p_value > self.alpha,
                                'method': 'partial_correlation'
                            }
                    except Exception as e:
                        return {
                            'statistic': 0.0,
                            'p_value': 1.0,
                            'independent': True,
                            'method': 'fallback'
                        }
            
            return SimpleCITester()
            
        except Exception as e:
            self.logger.error(f"Error initializing CI tester: {e}")
            return None
    
    def discover_causal_structure(self, data: np.ndarray, algorithm: str = 'ensemble',
                                variable_names: Optional[List[str]] = None) -> Dict[str, Any]:
        """
        Discover causal structure using specified algorithm(s)
        
        Args:
            data: Input data matrix (n_samples, n_variables)
            algorithm: Algorithm to use ('pc', 'ges', 'notears', 'lingam', 'ensemble')
            variable_names: Optional variable names
            
        Returns:
            Dictionary containing causal discovery results
        """
        start_time = time.time()
        
        try:
            if variable_names is None:
                variable_names = [f"X{i}" for i in range(data.shape[1])]
            
            # Cache key for results
            cache_key = f"{algorithm}_{hash(data.tobytes())}_{len(variable_names)}"
            if cache_key in self.result_cache:
                return self.result_cache[cache_key]
            
            self.logger.info(f"Starting causal discovery with {algorithm} algorithm")
            
            if algorithm == 'ensemble':
                result = self._ensemble_causal_discovery(data, variable_names)
            elif algorithm == 'pc':
                result = self._pc_algorithm(data, variable_names)
            elif algorithm == 'ges':
                result = self._ges_algorithm(data, variable_names)
            elif algorithm == 'notears':
                result = self._notears_algorithm(data, variable_names)
            elif algorithm == 'lingam':
                result = self._lingam_algorithm(data, variable_names)
            else:
                raise ValueError(f"Unknown algorithm: {algorithm}")
            
            # Add metadata
            result['algorithm'] = algorithm
            result['variable_names'] = variable_names
            result['computation_time'] = time.time() - start_time
            result['data_shape'] = data.shape
            
            # Cache result
            self.result_cache[cache_key] = result
            
            # Update performance metrics
            self.performance_monitor.record_operation("causal_discovery", time.time() - start_time)
            
            self.logger.info(f"Causal discovery completed in {result['computation_time']:.3f} seconds")
            return result
            
        except Exception as e:
            self.logger.error(f"Error in causal discovery: {e}")
            return {
                'adjacency_matrix': np.zeros((data.shape[1], data.shape[1])),
                'causal_order': list(range(data.shape[1])),
                'confidence_scores': np.zeros((data.shape[1], data.shape[1])),
                'algorithm': algorithm,
                'error': str(e),
                'computation_time': time.time() - start_time
            }
    
    def _pc_algorithm(self, data: np.ndarray, variable_names: List[str]) -> Dict[str, Any]:
        """
        Implement PC (Peter-Clark) algorithm for causal discovery
        
        The PC algorithm is a constraint-based approach that uses conditional independence
        tests to learn the structure of a causal graph.
        """
        n_vars = data.shape[1]
        
        # Initialize complete graph
        adjacency = np.ones((n_vars, n_vars)) - np.eye(n_vars)
        separating_sets = {}
        
        # Phase 1: Edge removal based on conditional independence
        for order in range(n_vars - 1):
            edge_removed = True
            while edge_removed:
                edge_removed = False
                
                for i in range(n_vars):
                    for j in range(i + 1, n_vars):
                        if adjacency[i, j] == 0:
                            continue
                        
                        # Get neighbors of i excluding j
                        neighbors_i = [k for k in range(n_vars) if k != j and adjacency[i, k] == 1]
                        
                        # Test all subsets of size 'order'
                        if len(neighbors_i) >= order:
                            from itertools import combinations
                            for conditioning_set in combinations(neighbors_i, order):
                                # Conditional independence test
                                if len(conditioning_set) == 0:
                                    ci_result = self.ci_tester.independence_test(
                                        data[:, i], data[:, j]
                                    )
                                else:
                                    Z = data[:, list(conditioning_set)]
                                    ci_result = self.ci_tester.independence_test(
                                        data[:, i], data[:, j], Z
                                    )
                                
                                if ci_result['independent']:
                                    # Remove edge
                                    adjacency[i, j] = adjacency[j, i] = 0
                                    separating_sets[(i, j)] = conditioning_set
                                    separating_sets[(j, i)] = conditioning_set
                                    edge_removed = True
                                    break
                        
                        if edge_removed:
                            break
                    if edge_removed:
                        break
        
        # Phase 2: Orient edges (simplified v-structure detection)
        directed_adjacency = self._orient_edges_pc(adjacency, separating_sets, n_vars)
        
        # Calculate confidence scores
        confidence_scores = self._calculate_confidence_scores_pc(
            data, directed_adjacency, separating_sets
        )
        
        # Determine causal order
        causal_order = self._topological_sort(directed_adjacency)
        
        return {
            'adjacency_matrix': directed_adjacency,
            'undirected_adjacency': adjacency,
            'separating_sets': separating_sets,
            'causal_order': causal_order,
            'confidence_scores': confidence_scores,
            'method': 'PC'
        }
    
    def _ges_algorithm(self, data: np.ndarray, variable_names: List[str]) -> Dict[str, Any]:
        """
        Implement GES (Greedy Equivalence Search) algorithm
        
        GES is a score-based causal discovery algorithm that greedily searches
        over the space of equivalence classes of DAGs.
        """
        n_vars = data.shape[1]
        
        # Initialize empty graph
        adjacency = np.zeros((n_vars, n_vars))
        
        # Phase 1: Forward search (edge addition)
        best_score = self._calculate_bic_score(data, adjacency)
        improvement = True
        
        while improvement:
            improvement = False
            best_edge = None
            
            for i in range(n_vars):
                for j in range(n_vars):
                    if i == j or adjacency[i, j] == 1:
                        continue
                    
                    # Try adding edge i -> j
                    test_adjacency = adjacency.copy()
                    test_adjacency[i, j] = 1
                    
                    # Check if this creates a cycle
                    if not self._has_cycle(test_adjacency):
                        score = self._calculate_bic_score(data, test_adjacency)
                        
                        if score > best_score:
                            best_score = score
                            best_edge = (i, j)
                            improvement = True
            
            if improvement and best_edge:
                adjacency[best_edge[0], best_edge[1]] = 1
        
        # Phase 2: Backward search (edge removal)
        improvement = True
        while improvement:
            improvement = False
            best_edge = None
            
            for i in range(n_vars):
                for j in range(n_vars):
                    if adjacency[i, j] == 0:
                        continue
                    
                    # Try removing edge i -> j
                    test_adjacency = adjacency.copy()
                    test_adjacency[i, j] = 0
                    
                    score = self._calculate_bic_score(data, test_adjacency)
                    
                    if score > best_score:
                        best_score = score
                        best_edge = (i, j)
                        improvement = True
            
            if improvement and best_edge:
                adjacency[best_edge[0], best_edge[1]] = 0
        
        # Calculate confidence scores
        confidence_scores = self._calculate_confidence_scores_ges(data, adjacency)
        
        # Determine causal order
        causal_order = self._topological_sort(adjacency)
        
        return {
            'adjacency_matrix': adjacency,
            'causal_order': causal_order,
            'confidence_scores': confidence_scores,
            'bic_score': best_score,
            'method': 'GES'
        }
    
    def _notears_algorithm(self, data: np.ndarray, variable_names: List[str]) -> Dict[str, Any]:
        """
        Implement NOTEARS algorithm for causal discovery
        
        NOTEARS formulates causal discovery as a continuous optimization problem
        with a novel acyclicity constraint.
        """
        n_vars = data.shape[1]
        n_samples = data.shape[0]
        
        # Standardize data
        data_std = (data - np.mean(data, axis=0)) / (np.std(data, axis=0) + 1e-8)
        
        # Initialize weight matrix
        W = np.random.normal(0, 0.1, (n_vars, n_vars))
        np.fill_diagonal(W, 0)
        
        # NOTEARS optimization parameters
        lambda1 = self.notears_config.get('lambda1', 0.01)  # L1 regularization
        lambda2 = self.notears_config.get('lambda2', 0.01)  # L2 regularization
        rho = self.notears_config.get('rho', 1.0)  # Augmented Lagrangian parameter
        alpha = self.notears_config.get('alpha', 0.0)  # Equality constraint multiplier
        
        # Optimization loop
        for iteration in range(self.max_iter):
            W_prev = W.copy()
            
            # Calculate gradients
            grad_W = self._notears_gradient(data_std, W, lambda1, lambda2, rho, alpha)
            
            # Update weights using gradient descent
            learning_rate = self.notears_config.get('learning_rate', 0.001)
            W = W - learning_rate * grad_W
            
            # Zero diagonal
            np.fill_diagonal(W, 0)
            
            # Check convergence
            if np.linalg.norm(W - W_prev) < self.tolerance:
                break
            
            # Update augmented Lagrangian parameters
            h = self._acyclicity_constraint(W)
            if h > 0.25 * self._acyclicity_constraint(W_prev):
                rho *= 10
            else:
                alpha += rho * h
        
        # Threshold small weights
        threshold = self.notears_config.get('threshold', 0.3)
        W_thresholded = np.where(np.abs(W) > threshold, W, 0)
        
        # Create binary adjacency matrix
        adjacency = (np.abs(W_thresholded) > 0).astype(int)
        
        # Calculate confidence scores based on weight magnitudes
        confidence_scores = np.abs(W_thresholded) / (np.max(np.abs(W_thresholded)) + 1e-10)
        
        # Determine causal order
        causal_order = self._topological_sort(adjacency)
        
        return {
            'adjacency_matrix': adjacency,
            'weight_matrix': W_thresholded,
            'causal_order': causal_order,
            'confidence_scores': confidence_scores,
            'iterations': iteration + 1,
            'final_constraint_violation': self._acyclicity_constraint(W),
            'method': 'NOTEARS'
        }
    
    def _lingam_algorithm(self, data: np.ndarray, variable_names: List[str]) -> Dict[str, Any]:
        """
        Implement LiNGAM (Linear Non-Gaussian Acyclic Model) algorithm
        
        LiNGAM assumes linear relationships with non-Gaussian noise,
        allowing for unique identification of the causal structure.
        """
        n_vars = data.shape[1]
        
        # Standardize data
        data_centered = data - np.mean(data, axis=0)
        
        # Estimate mixing matrix using Independent Component Analysis (ICA)
        try:
            from sklearn.decomposition import FastICA
            
            ica = FastICA(n_components=n_vars, random_state=42, max_iter=1000)
            sources = ica.fit_transform(data_centered)
            mixing_matrix = ica.mixing_
            
        except ImportError:
            self.logger.warning("FastICA not available, using PCA approximation")
            from sklearn.decomposition import PCA
            
            pca = PCA(n_components=n_vars)
            sources = pca.fit_transform(data_centered)
            mixing_matrix = pca.components_.T
        
        # Estimate causal order using mutual information
        causal_order = self._estimate_causal_order_lingam(data_centered, sources)
        
        # Estimate causal coefficients
        B = np.zeros((n_vars, n_vars))
        
        for i, target_idx in enumerate(causal_order):
            if i == 0:
                continue  # Root nodes have no parents
            
            # Regress target on all previous variables in causal order
            parents = causal_order[:i]
            
            if len(parents) > 0:
                from sklearn.linear_model import LinearRegression
                
                X_parents = data_centered[:, parents]
                y_target = data_centered[:, target_idx]
                
                reg = LinearRegression().fit(X_parents, y_target)
                
                for j, parent_idx in enumerate(parents):
                    B[parent_idx, target_idx] = reg.coef_[j]
        
        # Create adjacency matrix
        adjacency = (np.abs(B) > self.lingam_config.get('threshold', 0.1)).astype(int)
        
        # Calculate confidence scores based on coefficient magnitudes
        confidence_scores = np.abs(B) / (np.max(np.abs(B)) + 1e-10)
        
        # Validate non-Gaussianity assumption
        non_gaussianity_scores = self._test_non_gaussianity(sources)
        
        return {
            'adjacency_matrix': adjacency,
            'causal_coefficients': B,
            'causal_order': causal_order,
            'confidence_scores': confidence_scores,
            'mixing_matrix': mixing_matrix,
            'sources': sources,
            'non_gaussianity_scores': non_gaussianity_scores,
            'method': 'LiNGAM'
        }
    
    def _ensemble_causal_discovery(self, data: np.ndarray, variable_names: List[str]) -> Dict[str, Any]:
        """
        Ensemble causal discovery using multiple algorithms
        """
        algorithms = ['pc', 'ges', 'notears', 'lingam']
        results = {}
        
        # Run individual algorithms
        for alg in algorithms:
            try:
                self.logger.info(f"Running {alg.upper()} algorithm")
                results[alg] = getattr(self, f'_{alg}_algorithm')(data, variable_names)
            except Exception as e:
                self.logger.error(f"Error running {alg}: {e}")
                continue
        
        if not results:
            raise RuntimeError("All causal discovery algorithms failed")
        
        # Ensemble aggregation
        n_vars = data.shape[1]
        ensemble_adjacency = np.zeros((n_vars, n_vars))
        ensemble_confidence = np.zeros((n_vars, n_vars))
        
        # Aggregate adjacency matrices with weighted voting
        weights = self._calculate_algorithm_weights(results, data)
        
        for alg, result in results.items():
            weight = weights.get(alg, 1.0 / len(results))
            ensemble_adjacency += weight * result['adjacency_matrix']
            ensemble_confidence += weight * result.get('confidence_scores', 
                                                      np.ones((n_vars, n_vars)))
        
        # Threshold ensemble adjacency
        threshold = self.config.get('ensemble_threshold', 0.5)
        ensemble_adjacency_binary = (ensemble_adjacency > threshold).astype(int)
        
        # Determine consensus causal order
        causal_orders = [r['causal_order'] for r in results.values()]
        consensus_order = self._consensus_causal_order(causal_orders)
        
        # Calculate ensemble statistics
        agreement_matrix = self._calculate_agreement_matrix(results)
        uncertainty_scores = self._calculate_uncertainty_scores(results)
        
        return {
            'adjacency_matrix': ensemble_adjacency_binary,
            'confidence_scores': ensemble_confidence,
            'causal_order': consensus_order,
            'algorithm_results': results,
            'algorithm_weights': weights,
            'agreement_matrix': agreement_matrix,
            'uncertainty_scores': uncertainty_scores,
            'ensemble_strength': np.mean(ensemble_confidence),
            'method': 'Ensemble'
        }
    
    # Helper methods for PC algorithm
    def _orient_edges_pc(self, adjacency: np.ndarray, separating_sets: Dict, n_vars: int) -> np.ndarray:
        """Orient edges in PC algorithm using v-structure detection"""
        directed = adjacency.copy()
        
        # Look for v-structures (X -> Z <- Y where X and Y are not adjacent)
        for z in range(n_vars):
            # Find all pairs of neighbors of z
            neighbors_z = [i for i in range(n_vars) if directed[i, z] == 1]
            
            for i in range(len(neighbors_z)):
                for j in range(i + 1, len(neighbors_z)):
                    x, y = neighbors_z[i], neighbors_z[j]
                    
                    # Check if x and y are not adjacent
                    if directed[x, y] == 0:
                        # Check if z is not in the separating set of x and y
                        sep_set = separating_sets.get((x, y), set())
                        if z not in sep_set:
                            # Orient as v-structure: x -> z <- y
                            directed[z, x] = 0  # Remove z -> x
                            directed[z, y] = 0  # Remove z -> y
        
        return directed
    
    def _calculate_confidence_scores_pc(self, data: np.ndarray, adjacency: np.ndarray, 
                                      separating_sets: Dict) -> np.ndarray:
        """Calculate confidence scores for PC algorithm results"""
        n_vars = adjacency.shape[0]
        confidence = np.zeros((n_vars, n_vars))
        
        for i in range(n_vars):
            for j in range(n_vars):
                if adjacency[i, j] == 1:
                    # Use the p-value from the independence test that failed to reject
                    # Higher confidence if the test strongly rejected independence
                    ci_result = self.ci_tester.independence_test(data[:, i], data[:, j])
                    confidence[i, j] = 1.0 - ci_result['p_value']
        
        return confidence
    
    # Helper methods for GES algorithm
    def _calculate_bic_score(self, data: np.ndarray, adjacency: np.ndarray) -> float:
        """Calculate BIC score for a given graph structure"""
        n_samples, n_vars = data.shape
        total_score = 0.0
        
        for j in range(n_vars):
            # Find parents of variable j
            parents = np.where(adjacency[:, j] == 1)[0]
            
            if len(parents) == 0:
                # No parents, just calculate variance
                residual_var = np.var(data[:, j])
            else:
                # Linear regression to find residual variance
                from sklearn.linear_model import LinearRegression
                
                X_parents = data[:, parents]
                y = data[:, j]
                
                reg = LinearRegression().fit(X_parents, y)
                y_pred = reg.predict(X_parents)
                residuals = y - y_pred
                residual_var = np.var(residuals)
            
            # BIC score component for variable j
            if residual_var > 0:
                score_j = -0.5 * n_samples * np.log(residual_var)
                score_j -= 0.5 * (len(parents) + 1) * np.log(n_samples)  # Penalty term
                total_score += score_j
        
        return total_score
    
    def _has_cycle(self, adjacency: np.ndarray) -> bool:
        """Check if the directed graph has a cycle using DFS"""
        n_vars = adjacency.shape[0]
        
        # States: 0 = unvisited, 1 = visiting, 2 = visited
        state = np.zeros(n_vars, dtype=int)
        
        def dfs(node: int) -> bool:
            if state[node] == 1:  # Back edge found - cycle detected
                return True
            if state[node] == 2:  # Already processed
                return False
            
            state[node] = 1  # Mark as visiting
            
            # Check all children
            children = np.where(adjacency[node, :] == 1)[0]
            for child in children:
                if dfs(child):
                    return True
            
            state[node] = 2  # Mark as visited
            return False
        
        # Check for cycles starting from each unvisited node
        for i in range(n_vars):
            if state[i] == 0:
                if dfs(i):
                    return True
        
        return False
    
    def _calculate_confidence_scores_ges(self, data: np.ndarray, adjacency: np.ndarray) -> np.ndarray:
        """Calculate confidence scores for GES algorithm results"""
        n_vars = adjacency.shape[0]
        confidence = np.zeros((n_vars, n_vars))
        
        # Use bootstrap sampling to assess edge stability
        n_bootstrap = 100
        bootstrap_adjacencies = []
        
        for _ in range(n_bootstrap):
            # Bootstrap sample
            indices = np.random.choice(data.shape[0], size=data.shape[0], replace=True)
            bootstrap_data = data[indices]
            
            # Run simplified GES on bootstrap sample
            try:
                bootstrap_adj = self._simplified_ges(bootstrap_data)
                bootstrap_adjacencies.append(bootstrap_adj)
            except:
                continue
        
        # Calculate confidence as frequency of edge appearance in bootstrap
        if bootstrap_adjacencies:
            bootstrap_stack = np.stack(bootstrap_adjacencies)
            confidence = np.mean(bootstrap_stack, axis=0)
        else:
            # Fallback to uniform confidence
            confidence = adjacency * 0.5
        
        return confidence
    
    def _simplified_ges(self, data: np.ndarray) -> np.ndarray:
        """Simplified GES for bootstrap confidence calculation"""
        n_vars = data.shape[1]
        adjacency = np.zeros((n_vars, n_vars))
        
        # Simplified forward search with limited iterations
        best_score = self._calculate_bic_score(data, adjacency)
        
        for _ in range(min(20, n_vars * 2)):  # Limited iterations
            best_edge = None
            
            for i in range(n_vars):
                for j in range(n_vars):
                    if i == j or adjacency[i, j] == 1:
                        continue
                    
                    test_adjacency = adjacency.copy()
                    test_adjacency[i, j] = 1
                    
                    if not self._has_cycle(test_adjacency):
                        score = self._calculate_bic_score(data, test_adjacency)
                        
                        if score > best_score:
                            best_score = score
                            best_edge = (i, j)
            
            if best_edge:
                adjacency[best_edge[0], best_edge[1]] = 1
            else:
                break
        
        return adjacency
    
    # Helper methods for NOTEARS algorithm
    def _notears_gradient(self, data: np.ndarray, W: np.ndarray, lambda1: float, 
                         lambda2: float, rho: float, alpha: float) -> np.ndarray:
        """Calculate gradients for NOTEARS optimization"""
        n_samples, n_vars = data.shape
        
        # Data fitting term gradient
        residual = data - data @ W.T
        grad_fit = -2.0 / n_samples * data.T @ residual
        
        # L1 regularization gradient
        grad_l1 = lambda1 * np.sign(W)
        
        # L2 regularization gradient
        grad_l2 = 2 * lambda2 * W
        
        # Acyclicity constraint gradient
        h = self._acyclicity_constraint(W)
        grad_h = self._acyclicity_constraint_gradient(W)
        grad_acyclicity = rho * h * grad_h + alpha * grad_h
        
        # Total gradient
        grad_total = grad_fit + grad_l1 + grad_l2 + grad_acyclicity
        
        return grad_total
    
    def _acyclicity_constraint(self, W: np.ndarray) -> float:
        """Calculate acyclicity constraint value (should be 0 for DAG)"""
        n_vars = W.shape[0]
        A = W * W  # Element-wise square
        
        # Calculate trace of matrix exponential
        try:
            E = np.eye(n_vars) + A / n_vars
            
            # Use eigenvalue decomposition for matrix exponential
            eigenvals, eigenvecs = np.linalg.eigh(E)
            exp_eigenvals = np.exp(eigenvals)
            matrix_exp = eigenvecs @ np.diag(exp_eigenvals) @ eigenvecs.T
            
            return np.trace(matrix_exp) - n_vars
        except:
            # Fallback using simpler approximation
            return np.trace(np.linalg.matrix_power(np.eye(n_vars) + A / n_vars, n_vars)) - n_vars
    
    def _acyclicity_constraint_gradient(self, W: np.ndarray) -> np.ndarray:
        """Calculate gradient of acyclicity constraint"""
        n_vars = W.shape[0]
        A = W * W
        
        try:
            E = np.eye(n_vars) + A / n_vars
            
            # Calculate gradient using eigendecomposition
            eigenvals, eigenvecs = np.linalg.eigh(E)
            exp_eigenvals = np.exp(eigenvals)
            
            # Construct the gradient matrix
            grad_E = eigenvecs @ np.diag(exp_eigenvals) @ eigenvecs.T
            
            # Chain rule: gradient w.r.t. W
            grad_W = 2 * W * grad_E / n_vars
            
            return grad_W
        except:
            # Fallback gradient calculation
            return 2 * W * np.eye(n_vars)
    
    # Helper methods for LiNGAM algorithm  
    def _estimate_causal_order_lingam(self, data: np.ndarray, sources: np.ndarray) -> List[int]:
        """Estimate causal order for LiNGAM using mutual information"""
        n_vars = data.shape[1]
        
        # Calculate mutual information matrix
        mi_matrix = np.zeros((n_vars, n_vars))
        
        for i in range(n_vars):
            for j in range(n_vars):
                if i != j:
                    mi_matrix[i, j] = self._mutual_information(data[:, i], data[:, j])
        
        # Use topological ordering based on mutual information
        # Variables with lower mutual information with others come first
        mi_sums = np.sum(mi_matrix, axis=1)
        causal_order = np.argsort(mi_sums).tolist()
        
        return causal_order
    
    def _mutual_information(self, X: np.ndarray, Y: np.ndarray) -> float:
        """Calculate mutual information between two variables"""
        try:
            from sklearn.feature_selection import mutual_info_regression
            
            # Reshape for sklearn
            X_reshaped = X.reshape(-1, 1)
            
            # Calculate mutual information
            mi = mutual_info_regression(X_reshaped, Y, random_state=42)
            return float(mi[0])
            
        except ImportError:
            # Fallback using correlation approximation
            correlation = np.corrcoef(X, Y)[0, 1]
            # Convert correlation to approximate mutual information
            return -0.5 * np.log(1 - correlation**2 + 1e-10)
    
    def _test_non_gaussianity(self, data: np.ndarray) -> np.ndarray:
        """Test non-Gaussianity assumption for LiNGAM"""
        n_vars = data.shape[1]
        scores = np.zeros(n_vars)
        
        try:
            from scipy import stats
            
            for i in range(n_vars):
                # Jarque-Bera test for normality
                statistic, p_value = stats.jarque_bera(data[:, i])
                scores[i] = 1.0 - p_value  # Higher score = more non-Gaussian
                
        except ImportError:
            # Fallback using kurtosis
            for i in range(n_vars):
                kurt = stats.kurtosis(data[:, i])
                scores[i] = abs(kurt) / 10.0  # Normalize kurtosis
        
        return np.clip(scores, 0, 1)
    
    # Helper methods for ensemble
    def _calculate_algorithm_weights(self, results: Dict[str, Any], data: np.ndarray) -> Dict[str, float]:
        """Calculate weights for different algorithms in ensemble"""
        weights = {}
        
        # Simple equal weighting
        n_algorithms = len(results)
        base_weight = 1.0 / n_algorithms
        
        for alg in results.keys():
            weights[alg] = base_weight
            
            # Bonus weight for algorithms that converged well
            result = results[alg]
            if 'iterations' in result and result['iterations'] < self.max_iter:
                weights[alg] *= 1.1
            
            # Bonus weight based on confidence scores
            if 'confidence_scores' in result:
                mean_confidence = np.mean(result['confidence_scores'])
                weights[alg] *= (1.0 + mean_confidence)
        
        # Normalize weights
        total_weight = sum(weights.values())
        for alg in weights:
            weights[alg] /= total_weight
        
        return weights
    
    def _consensus_causal_order(self, causal_orders: List[List[int]]) -> List[int]:
        """Determine consensus causal order from multiple orderings"""
        if not causal_orders:
            return []
        
        n_vars = len(causal_orders[0])
        
        # Use Kemeny ranking to find consensus
        # Simplified approach: weighted Borda count
        scores = np.zeros(n_vars)
        
        for order in causal_orders:
            for position, var in enumerate(order):
                scores[var] += (n_vars - position)  # Higher position = higher score
        
        # Return variables sorted by consensus score
        return np.argsort(-scores).tolist()
    
    def _calculate_agreement_matrix(self, results: Dict[str, Any]) -> np.ndarray:
        """Calculate agreement matrix between algorithms"""
        algorithms = list(results.keys())
        n_algs = len(algorithms)
        agreement = np.zeros((n_algs, n_algs))
        
        for i, alg1 in enumerate(algorithms):
            for j, alg2 in enumerate(algorithms):
                if i == j:
                    agreement[i, j] = 1.0
                else:
                    # Calculate Jaccard similarity between adjacency matrices
                    adj1 = results[alg1]['adjacency_matrix']
                    adj2 = results[alg2]['adjacency_matrix']
                    
                    intersection = np.sum((adj1 == 1) & (adj2 == 1))
                    union = np.sum((adj1 == 1) | (adj2 == 1))
                    
                    if union > 0:
                        agreement[i, j] = intersection / union
                    else:
                        agreement[i, j] = 1.0  # Both empty
        
        return agreement
    
    def _calculate_uncertainty_scores(self, results: Dict[str, Any]) -> np.ndarray:
        """Calculate uncertainty scores for each edge"""
        adjacency_matrices = [r['adjacency_matrix'] for r in results.values()]
        
        if not adjacency_matrices:
            return np.zeros((1, 1))
        
        # Stack adjacency matrices
        adj_stack = np.stack(adjacency_matrices)
        
        # Calculate variance across algorithms (uncertainty)
        edge_means = np.mean(adj_stack, axis=0)
        edge_vars = np.var(adj_stack, axis=0)
        
        # Normalize uncertainty scores
        uncertainty = edge_vars / (edge_means + 1e-10)
        
        return uncertainty
    
    def _topological_sort(self, adjacency: np.ndarray) -> List[int]:
        """Perform topological sort on directed graph"""
        n_vars = adjacency.shape[0]
        in_degree = np.sum(adjacency, axis=0)
        
        # Kahn's algorithm
        queue = [i for i in range(n_vars) if in_degree[i] == 0]
        topo_order = []
        
        while queue:
            node = queue.pop(0)
            topo_order.append(node)
            
            # Remove edges from this node
            children = np.where(adjacency[node, :] == 1)[0]
            for child in children:
                in_degree[child] -= 1
                if in_degree[child] == 0:
                    queue.append(child)
        
        # If not all nodes are included, graph has cycles
        if len(topo_order) != n_vars:
            # Return arbitrary order for cyclic graphs
            return list(range(n_vars))
        
        return topo_order
    
    def get_causal_relationships(self, result: Dict[str, Any]) -> List[Dict[str, Any]]:
        """Extract causal relationships from discovery results"""
        adjacency = result['adjacency_matrix']
        confidence = result.get('confidence_scores', np.ones_like(adjacency))
        variable_names = result.get('variable_names', [f"X{i}" for i in range(adjacency.shape[0])])
        
        relationships = []
        
        for i in range(adjacency.shape[0]):
            for j in range(adjacency.shape[1]):
                if adjacency[i, j] == 1:
                    relationships.append({
                        'cause': variable_names[i],
                        'effect': variable_names[j],
                        'confidence': float(confidence[i, j]),
                        'relationship_type': 'direct_causal'
                    })
        
        return relationships
    
    def validate_causal_structure(self, data: np.ndarray, result: Dict[str, Any]) -> Dict[str, Any]:
        """Validate discovered causal structure using statistical tests"""
        adjacency = result['adjacency_matrix']
        n_vars = adjacency.shape[0]
        
        validation_results = {
            'structural_hamming_distance': 0,
            'edge_precision': 0.0,
            'edge_recall': 0.0,
            'orientation_accuracy': 0.0,
            'statistical_validation': {}
        }
        
        # Statistical validation of each edge
        for i in range(n_vars):
            for j in range(n_vars):
                if adjacency[i, j] == 1:
                    # Test if removing this edge significantly reduces fit
                    test_adjacency = adjacency.copy()
                    test_adjacency[i, j] = 0
                    
                    original_score = self._calculate_bic_score(data, adjacency)
                    reduced_score = self._calculate_bic_score(data, test_adjacency)
                    
                    validation_results['statistical_validation'][f'{i}->{j}'] = {
                        'score_difference': original_score - reduced_score,
                        'edge_significant': original_score > reduced_score
                    }
        
        return validation_results


class KernelBasedIndependenceTests:
    """
    Advanced kernel-based independence testing methods including HSIC, MMD, and kernel CCA.
    
    Implements Hilbert-Schmidt Independence Criterion (HSIC), Maximum Mean Discrepancy (MMD),
    kernel Canonical Correlation Analysis (CCA), and other kernel-based statistical tests
    with multiple kernel functions and optimization techniques.
    """
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        """Initialize kernel-based independence test engine"""
        self.config = config or {}
        self.logger = logging.getLogger(__name__)
        
        # Performance monitoring
        global performance_monitor
        self.performance_monitor = performance_monitor
        
        # Kernel configurations
        self.kernel_types = self.config.get('kernel_types', ['rbf', 'polynomial', 'linear'])
        self.default_kernel = self.config.get('default_kernel', 'rbf')
        
        # HSIC parameters
        self.hsic_config = self.config.get('hsic', {})
        self.hsic_gamma = self.hsic_config.get('gamma', 1.0)
        self.hsic_alpha = self.hsic_config.get('alpha', 0.05)
        
        # MMD parameters
        self.mmd_config = self.config.get('mmd', {})
        self.mmd_sigma_list = self.mmd_config.get('sigma_list', [0.1, 1.0, 10.0])
        
        # Kernel CCA parameters
        self.kcca_config = self.config.get('kcca', {})
        self.kcca_regularization = self.kcca_config.get('regularization', 1e-3)
        
        # Statistical test parameters
        self.n_permutations = self.config.get('n_permutations', 500)
        self.significance_level = self.config.get('significance_level', 0.05)
        
        # Cache for kernel matrices
        self.kernel_cache = {}
        
        self.logger.info("KernelBasedIndependenceTests initialized successfully")
    
    def hsic_test(self, X: np.ndarray, Y: np.ndarray, kernel_X: str = 'rbf', 
                  kernel_Y: str = 'rbf', **kwargs) -> Dict[str, Any]:
        """
        Hilbert-Schmidt Independence Criterion (HSIC) test
        
        Tests independence between X and Y using kernel embeddings in RKHS.
        
        Args:
            X: First variable data (n_samples, n_features_x)
            Y: Second variable data (n_samples, n_features_y)
            kernel_X: Kernel type for X ('rbf', 'polynomial', 'linear')
            kernel_Y: Kernel type for Y
            
        Returns:
            Dictionary with test results including statistic and p-value
        """
        start_time = time.time()
        
        try:
            n_samples = X.shape[0]
            
            # Ensure data is 2D
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            # Compute kernel matrices
            K_X = self._compute_kernel_matrix(X, X, kernel_X, **kwargs)
            K_Y = self._compute_kernel_matrix(Y, Y, kernel_Y, **kwargs)
            
            # Center kernel matrices
            K_X_centered = self._center_kernel_matrix(K_X)
            K_Y_centered = self._center_kernel_matrix(K_Y)
            
            # Compute HSIC statistic
            hsic_statistic = self._compute_hsic_statistic(K_X_centered, K_Y_centered, n_samples)
            
            # Permutation test for p-value
            p_value = self._hsic_permutation_test(X, Y, hsic_statistic, kernel_X, kernel_Y, **kwargs)
            
            # Effect size estimation
            effect_size = self._compute_hsic_effect_size(K_X_centered, K_Y_centered, n_samples)
            
            result = {
                'test_statistic': float(hsic_statistic),
                'p_value': float(p_value),
                'independent': p_value > self.significance_level,
                'effect_size': float(effect_size),
                'method': 'HSIC',
                'kernel_X': kernel_X,
                'kernel_Y': kernel_Y,
                'n_samples': n_samples,
                'computation_time': time.time() - start_time
            }
            
            # Update performance metrics
            self.performance_monitor.record_operation("hsic_test", time.time() - start_time)
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in HSIC test: {e}")
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': 'HSIC_fallback'
            }
    
    def mmd_test(self, X: np.ndarray, Y: np.ndarray, kernel_type: str = 'rbf', 
                 **kwargs) -> Dict[str, Any]:
        """
        Maximum Mean Discrepancy (MMD) test for two-sample problem
        
        Tests whether two samples come from the same distribution using kernel embeddings.
        
        Args:
            X: First sample data (n_samples_x, n_features)
            Y: Second sample data (n_samples_y, n_features)
            kernel_type: Kernel function type
            
        Returns:
            Dictionary with test results
        """
        start_time = time.time()
        
        try:
            n_x, n_y = X.shape[0], Y.shape[0]
            
            # Ensure data is 2D
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            # Compute MMD statistic using multiple kernels (ensemble approach)
            mmd_statistics = []
            
            if kernel_type == 'rbf':
                # Use multiple bandwidths for robustness
                for sigma in self.mmd_sigma_list:
                    mmd_stat = self._compute_mmd_rbf(X, Y, sigma)
                    mmd_statistics.append(mmd_stat)
                
                # Combine statistics (max or mean)
                mmd_statistic = np.mean(mmd_statistics)
            else:
                mmd_statistic = self._compute_mmd_general(X, Y, kernel_type, **kwargs)
            
            # Permutation test for significance
            p_value = self._mmd_permutation_test(X, Y, mmd_statistic, kernel_type, **kwargs)
            
            # Bootstrap confidence intervals
            confidence_interval = self._mmd_bootstrap_ci(X, Y, kernel_type, **kwargs)
            
            result = {
                'test_statistic': float(mmd_statistic),
                'p_value': float(p_value),
                'significant': p_value < self.significance_level,
                'confidence_interval': confidence_interval,
                'method': 'MMD',
                'kernel_type': kernel_type,
                'n_samples_x': n_x,
                'n_samples_y': n_y,
                'computation_time': time.time() - start_time
            }
            
            # Update performance metrics
            self.performance_monitor.record_operation("mmd_test", time.time() - start_time)
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in MMD test: {e}")
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'significant': False,
                'error': str(e),
                'method': 'MMD_fallback'
            }
    
    def kernel_cca_test(self, X: np.ndarray, Y: np.ndarray, kernel_X: str = 'rbf',
                       kernel_Y: str = 'rbf', **kwargs) -> Dict[str, Any]:
        """
        Kernel Canonical Correlation Analysis (CCA) independence test
        
        Tests independence using canonical correlations in kernel-induced feature spaces.
        
        Args:
            X: First variable data
            Y: Second variable data
            kernel_X: Kernel type for X
            kernel_Y: Kernel type for Y
            
        Returns:
            Dictionary with test results
        """
        start_time = time.time()
        
        try:
            n_samples = X.shape[0]
            
            # Ensure data is 2D
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            # Compute kernel matrices
            K_X = self._compute_kernel_matrix(X, X, kernel_X, **kwargs)
            K_Y = self._compute_kernel_matrix(Y, Y, kernel_Y, **kwargs)
            
            # Center kernel matrices
            K_X_centered = self._center_kernel_matrix(K_X)
            K_Y_centered = self._center_kernel_matrix(K_Y)
            
            # Regularized kernel CCA
            canonical_correlations = self._compute_kernel_cca(
                K_X_centered, K_Y_centered, self.kcca_regularization
            )
            
            # Test statistic: largest canonical correlation
            test_statistic = np.max(canonical_correlations) if len(canonical_correlations) > 0 else 0.0
            
            # Asymptotic p-value approximation
            p_value = self._kcca_asymptotic_pvalue(canonical_correlations, n_samples)
            
            # Alternative: permutation test (more robust but slower)
            if self.config.get('use_permutation_kcca', False):
                p_value = self._kcca_permutation_test(X, Y, test_statistic, kernel_X, kernel_Y, **kwargs)
            
            result = {
                'test_statistic': float(test_statistic),
                'canonical_correlations': canonical_correlations.tolist(),
                'p_value': float(p_value),
                'independent': p_value > self.significance_level,
                'method': 'KernelCCA',
                'kernel_X': kernel_X,
                'kernel_Y': kernel_Y,
                'regularization': self.kcca_regularization,
                'n_components': len(canonical_correlations),
                'computation_time': time.time() - start_time
            }
            
            # Update performance metrics
            self.performance_monitor.record_operation("kernel_cca_test", time.time() - start_time)
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in Kernel CCA test: {e}")
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': 'KernelCCA_fallback'
            }
    
    def kernel_ridge_test(self, X: np.ndarray, Y: np.ndarray, kernel_type: str = 'rbf',
                         **kwargs) -> Dict[str, Any]:
        """
        Kernel Ridge Regression-based independence test
        
        Tests independence by measuring how well Y can be predicted from X in kernel space.
        """
        start_time = time.time()
        
        try:
            n_samples = X.shape[0]
            
            # Ensure data is 2D
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            # Cross-validation setup
            from sklearn.model_selection import KFold
            kf = KFold(n_splits=5, shuffle=True, random_state=42)
            
            # Kernel Ridge Regression
            prediction_errors = []
            baseline_errors = []
            
            for train_idx, test_idx in kf.split(X):
                X_train, X_test = X[train_idx], X[test_idx]
                Y_train, Y_test = Y[train_idx], Y[test_idx]
                
                # Compute kernel matrix for training set
                K_train = self._compute_kernel_matrix(X_train, X_train, kernel_type, **kwargs)
                K_test_train = self._compute_kernel_matrix(X_test, X_train, kernel_type, **kwargs)
                
                # Ridge regression in kernel space
                regularization = kwargs.get('regularization', 1e-3)
                alpha = np.linalg.solve(K_train + regularization * np.eye(len(X_train)), Y_train)
                
                # Predictions
                Y_pred = K_test_train @ alpha
                
                # Compute prediction error
                if Y.shape[1] == 1:  # Regression
                    pred_error = np.mean((Y_test - Y_pred)**2)
                    baseline_error = np.var(Y_test)
                else:  # Multi-dimensional
                    pred_error = np.mean(np.sum((Y_test - Y_pred)**2, axis=1))
                    baseline_error = np.mean(np.var(Y_test, axis=0))
                
                prediction_errors.append(pred_error)
                baseline_errors.append(baseline_error)
            
            # Test statistic: normalized prediction accuracy
            mean_pred_error = np.mean(prediction_errors)
            mean_baseline_error = np.mean(baseline_errors)
            
            if mean_baseline_error > 0:
                test_statistic = 1.0 - (mean_pred_error / mean_baseline_error)
                test_statistic = max(0.0, test_statistic)  # Clamp to non-negative
            else:
                test_statistic = 0.0
            
            # Approximate p-value using permutation test
            p_value = self._kernel_ridge_permutation_test(
                X, Y, test_statistic, kernel_type, **kwargs
            )
            
            result = {
                'test_statistic': float(test_statistic),
                'prediction_error': float(mean_pred_error),
                'baseline_error': float(mean_baseline_error),
                'p_value': float(p_value),
                'independent': p_value > self.significance_level,
                'method': 'KernelRidge',
                'kernel_type': kernel_type,
                'computation_time': time.time() - start_time
            }
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in Kernel Ridge test: {e}")
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': 'KernelRidge_fallback'
            }
    
    def ensemble_kernel_test(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """
        Ensemble kernel-based independence test combining multiple methods
        """
        start_time = time.time()
        
        try:
            # Run individual tests
            results = {}
            
            # HSIC with different kernels
            for kernel_x in ['rbf', 'polynomial']:
                for kernel_y in ['rbf', 'polynomial']:
                    key = f"hsic_{kernel_x}_{kernel_y}"
                    results[key] = self.hsic_test(X, Y, kernel_x, kernel_y)
            
            # MMD test
            results['mmd'] = self.mmd_test(X, Y, 'rbf')
            
            # Kernel CCA test
            results['kcca'] = self.kernel_cca_test(X, Y, 'rbf', 'rbf')
            
            # Kernel Ridge test
            results['kridge'] = self.kernel_ridge_test(X, Y, 'rbf')
            
            # Aggregate results using Fisher's method
            p_values = [r['p_value'] for r in results.values() if 'error' not in r]
            
            if p_values:
                # Fisher's combined test
                chi2_statistic = -2 * np.sum(np.log(np.array(p_values) + 1e-10))
                from scipy.stats import chi2
                combined_p_value = 1 - chi2.cdf(chi2_statistic, 2 * len(p_values))
                
                # Weighted average of test statistics
                statistics = [r['test_statistic'] for r in results.values() if 'error' not in r]
                weights = [1.0 / (r.get('computation_time', 1.0) + 1e-6) for r in results.values() if 'error' not in r]
                weighted_statistic = np.average(statistics, weights=weights)
            else:
                combined_p_value = 1.0
                weighted_statistic = 0.0
            
            ensemble_result = {
                'test_statistic': float(weighted_statistic),
                'p_value': float(combined_p_value),
                'independent': combined_p_value > self.significance_level,
                'individual_results': results,
                'method': 'EnsembleKernel',
                'n_successful_tests': len(p_values),
                'computation_time': time.time() - start_time
            }
            
            return ensemble_result
            
        except Exception as e:
            self.logger.error(f"Error in ensemble kernel test: {e}")
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': 'EnsembleKernel_fallback'
            }
    
    # Helper methods for kernel computations
    def _compute_kernel_matrix(self, X: np.ndarray, Y: np.ndarray, kernel_type: str, 
                              **kwargs) -> np.ndarray:
        """Compute kernel matrix between X and Y"""
        try:
            if kernel_type == 'rbf':
                gamma = kwargs.get('gamma', self.hsic_gamma)
                return self._rbf_kernel(X, Y, gamma)
            elif kernel_type == 'polynomial':
                degree = kwargs.get('degree', 3)
                coef0 = kwargs.get('coef0', 1.0)
                return self._polynomial_kernel(X, Y, degree, coef0)
            elif kernel_type == 'linear':
                return self._linear_kernel(X, Y)
            elif kernel_type == 'laplacian':
                gamma = kwargs.get('gamma', self.hsic_gamma)
                return self._laplacian_kernel(X, Y, gamma)
            else:
                self.logger.warning(f"Unknown kernel type {kernel_type}, using RBF")
                return self._rbf_kernel(X, Y, self.hsic_gamma)
                
        except Exception as e:
            self.logger.error(f"Error computing kernel matrix: {e}")
            # Fallback to identity matrix
            return np.eye(X.shape[0])
    
    def _rbf_kernel(self, X: np.ndarray, Y: np.ndarray, gamma: float) -> np.ndarray:
        """RBF (Gaussian) kernel"""
        from scipy.spatial.distance import cdist
        pairwise_sq_dists = cdist(X, Y, 'sqeuclidean')
        return np.exp(-gamma * pairwise_sq_dists)
    
    def _polynomial_kernel(self, X: np.ndarray, Y: np.ndarray, degree: int, coef0: float) -> np.ndarray:
        """Polynomial kernel"""
        return (X @ Y.T + coef0) ** degree
    
    def _linear_kernel(self, X: np.ndarray, Y: np.ndarray) -> np.ndarray:
        """Linear kernel"""
        return X @ Y.T
    
    def _laplacian_kernel(self, X: np.ndarray, Y: np.ndarray, gamma: float) -> np.ndarray:
        """Laplacian kernel"""
        from scipy.spatial.distance import cdist
        pairwise_dists = cdist(X, Y, 'euclidean')
        return np.exp(-gamma * pairwise_dists)
    
    def _center_kernel_matrix(self, K: np.ndarray) -> np.ndarray:
        """Center kernel matrix in feature space"""
        n = K.shape[0]
        ones_n = np.ones((n, n)) / n
        return K - ones_n @ K - K @ ones_n + ones_n @ K @ ones_n
    
    # HSIC-specific helper methods
    def _compute_hsic_statistic(self, K_X: np.ndarray, K_Y: np.ndarray, n_samples: int) -> float:
        """Compute HSIC statistic from centered kernel matrices"""
        return float(np.trace(K_X @ K_Y)) / ((n_samples - 1) ** 2)
    
    def _compute_hsic_effect_size(self, K_X: np.ndarray, K_Y: np.ndarray, n_samples: int) -> float:
        """Compute effect size for HSIC"""
        hsic = self._compute_hsic_statistic(K_X, K_Y, n_samples)
        
        # Normalize by marginal HSIC values
        hsic_x = np.trace(K_X @ K_X) / ((n_samples - 1) ** 2)
        hsic_y = np.trace(K_Y @ K_Y) / ((n_samples - 1) ** 2)
        
        if hsic_x * hsic_y > 0:
            return hsic / np.sqrt(hsic_x * hsic_y)
        else:
            return 0.0
    
    def _hsic_permutation_test(self, X: np.ndarray, Y: np.ndarray, observed_hsic: float,
                              kernel_X: str, kernel_Y: str, **kwargs) -> float:
        """Permutation test for HSIC significance"""
        n_permutations = min(self.n_permutations, 200)  # Limit for efficiency
        permutation_statistics = []
        
        for _ in range(n_permutations):
            # Permute Y to break dependence
            Y_perm = np.random.permutation(Y)
            
            # Compute kernel matrices for permuted data
            K_X = self._compute_kernel_matrix(X, X, kernel_X, **kwargs)
            K_Y_perm = self._compute_kernel_matrix(Y_perm, Y_perm, kernel_Y, **kwargs)
            
            # Center kernel matrices
            K_X_centered = self._center_kernel_matrix(K_X)
            K_Y_perm_centered = self._center_kernel_matrix(K_Y_perm)
            
            # Compute permutation HSIC
            perm_hsic = self._compute_hsic_statistic(K_X_centered, K_Y_perm_centered, X.shape[0])
            permutation_statistics.append(perm_hsic)
        
        # Calculate p-value
        p_value = np.mean(np.array(permutation_statistics) >= observed_hsic)
        return max(0.001, min(0.999, p_value))
    
    # MMD-specific helper methods
    def _compute_mmd_rbf(self, X: np.ndarray, Y: np.ndarray, sigma: float) -> float:
        """Compute MMD with RBF kernel"""
        n_x, n_y = X.shape[0], Y.shape[0]
        
        # Compute kernel matrices
        K_XX = self._rbf_kernel(X, X, 1.0 / (2 * sigma**2))
        K_YY = self._rbf_kernel(Y, Y, 1.0 / (2 * sigma**2))
        K_XY = self._rbf_kernel(X, Y, 1.0 / (2 * sigma**2))
        
        # MMD² estimator
        mmd_squared = (np.sum(K_XX) - np.trace(K_XX)) / (n_x * (n_x - 1))
        mmd_squared += (np.sum(K_YY) - np.trace(K_YY)) / (n_y * (n_y - 1))
        mmd_squared -= 2 * np.sum(K_XY) / (n_x * n_y)
        
        return np.sqrt(max(0.0, mmd_squared))
    
    def _compute_mmd_general(self, X: np.ndarray, Y: np.ndarray, kernel_type: str, **kwargs) -> float:
        """Compute MMD with general kernel"""
        n_x, n_y = X.shape[0], Y.shape[0]
        
        # Compute kernel matrices
        K_XX = self._compute_kernel_matrix(X, X, kernel_type, **kwargs)
        K_YY = self._compute_kernel_matrix(Y, Y, kernel_type, **kwargs)  
        K_XY = self._compute_kernel_matrix(X, Y, kernel_type, **kwargs)
        
        # MMD² estimator
        mmd_squared = (np.sum(K_XX) - np.trace(K_XX)) / (n_x * (n_x - 1))
        mmd_squared += (np.sum(K_YY) - np.trace(K_YY)) / (n_y * (n_y - 1))
        mmd_squared -= 2 * np.sum(K_XY) / (n_x * n_y)
        
        return np.sqrt(max(0.0, mmd_squared))
    
    def _mmd_permutation_test(self, X: np.ndarray, Y: np.ndarray, observed_mmd: float,
                             kernel_type: str, **kwargs) -> float:
        """Permutation test for MMD significance"""
        # Combine samples
        combined_data = np.vstack([X, Y])
        n_x, n_y = X.shape[0], Y.shape[0]
        n_total = n_x + n_y
        
        permutation_statistics = []
        n_permutations = min(self.n_permutations, 100)  # Limit for efficiency
        
        for _ in range(n_permutations):
            # Random permutation
            perm_indices = np.random.permutation(n_total)
            
            # Split into new X and Y
            X_perm = combined_data[perm_indices[:n_x]]
            Y_perm = combined_data[perm_indices[n_x:]]
            
            # Compute MMD for permuted data
            if kernel_type == 'rbf':
                perm_mmd = np.mean([
                    self._compute_mmd_rbf(X_perm, Y_perm, sigma) 
                    for sigma in self.mmd_sigma_list
                ])
            else:
                perm_mmd = self._compute_mmd_general(X_perm, Y_perm, kernel_type, **kwargs)
            
            permutation_statistics.append(perm_mmd)
        
        # Calculate p-value
        p_value = np.mean(np.array(permutation_statistics) >= observed_mmd)
        return max(0.001, min(0.999, p_value))
    
    def _mmd_bootstrap_ci(self, X: np.ndarray, Y: np.ndarray, kernel_type: str, 
                         confidence_level: float = 0.95, **kwargs) -> Dict[str, float]:
        """Bootstrap confidence intervals for MMD"""
        n_bootstrap = 100
        bootstrap_statistics = []
        
        for _ in range(n_bootstrap):
            # Bootstrap samples
            X_boot = X[np.random.choice(X.shape[0], X.shape[0], replace=True)]
            Y_boot = Y[np.random.choice(Y.shape[0], Y.shape[0], replace=True)]
            
            # Compute MMD
            if kernel_type == 'rbf':
                boot_mmd = np.mean([
                    self._compute_mmd_rbf(X_boot, Y_boot, sigma) 
                    for sigma in self.mmd_sigma_list
                ])
            else:
                boot_mmd = self._compute_mmd_general(X_boot, Y_boot, kernel_type, **kwargs)
            
            bootstrap_statistics.append(boot_mmd)
        
        # Calculate confidence interval
        alpha = 1 - confidence_level
        lower_percentile = (alpha / 2) * 100
        upper_percentile = (1 - alpha / 2) * 100
        
        return {
            'lower': float(np.percentile(bootstrap_statistics, lower_percentile)),
            'upper': float(np.percentile(bootstrap_statistics, upper_percentile))
        }
    
    # Kernel CCA helper methods
    def _compute_kernel_cca(self, K_X: np.ndarray, K_Y: np.ndarray, 
                           regularization: float) -> np.ndarray:
        """Compute canonical correlations in kernel space"""
        try:
            n = K_X.shape[0]
            
            # Add regularization
            K_X_reg = K_X + regularization * np.eye(n)
            K_Y_reg = K_Y + regularization * np.eye(n)
            
            # Solve generalized eigenvalue problem
            # K_X @ alpha = rho^2 @ K_Y @ alpha
            try:
                from scipy.linalg import eigvals
                
                # Compute K_Y^{-1/2} @ K_X @ K_Y^{-1/2}
                eigenvals_y, eigenvecs_y = np.linalg.eigh(K_Y_reg)
                eigenvals_y = np.maximum(eigenvals_y, 1e-12)  # Numerical stability
                
                K_Y_inv_sqrt = eigenvecs_y @ np.diag(1.0 / np.sqrt(eigenvals_y)) @ eigenvecs_y.T
                M = K_Y_inv_sqrt @ K_X @ K_Y_inv_sqrt
                
                eigenvals_m = eigvals(M)
                canonical_correlations = np.sqrt(np.maximum(np.real(eigenvals_m), 0))
                
                # Sort in descending order
                canonical_correlations = np.sort(canonical_correlations)[::-1]
                
                # Keep only meaningful correlations
                meaningful_corrs = canonical_correlations[canonical_correlations > 1e-10]
                
                return meaningful_corrs[:min(10, len(meaningful_corrs))]  # Limit to top 10
                
            except Exception as e:
                self.logger.warning(f"Error in eigenvalue computation: {e}")
                # Fallback: use correlation between kernel matrices
                corr = np.corrcoef(K_X.flatten(), K_Y.flatten())[0, 1]
                return np.array([abs(corr)] if not np.isnan(corr) else [0.0])
                
        except Exception as e:
            self.logger.error(f"Error in kernel CCA computation: {e}")
            return np.array([0.0])
    
    def _kcca_asymptotic_pvalue(self, canonical_correlations: np.ndarray, n_samples: int) -> float:
        """Asymptotic p-value approximation for kernel CCA"""
        try:
            # Wilks' Lambda test
            if len(canonical_correlations) == 0:
                return 1.0
            
            # Compute Wilks' lambda
            lambda_wilks = np.prod(1 - canonical_correlations**2)
            
            # Chi-square approximation
            df = len(canonical_correlations)
            chi2_statistic = -(n_samples - 1 - (df + 1) / 2) * np.log(lambda_wilks)
            
            # Convert to p-value
            from scipy.stats import chi2
            p_value = 1 - chi2.cdf(chi2_statistic, df)
            
            return max(0.001, min(0.999, p_value))
            
        except Exception as e:
            self.logger.error(f"Error computing asymptotic p-value: {e}")
            # Fallback: use largest correlation as test statistic
            if len(canonical_correlations) > 0:
                max_corr = np.max(canonical_correlations)
                # Simple transformation to p-value
                return max(0.001, 1.0 - max_corr)
            return 1.0
    
    def _kcca_permutation_test(self, X: np.ndarray, Y: np.ndarray, observed_statistic: float,
                              kernel_X: str, kernel_Y: str, **kwargs) -> float:
        """Permutation test for kernel CCA"""
        n_permutations = min(self.n_permutations, 100)
        permutation_statistics = []
        
        for _ in range(n_permutations):
            # Permute Y
            Y_perm = np.random.permutation(Y)
            
            # Compute kernel matrices
            K_X = self._compute_kernel_matrix(X, X, kernel_X, **kwargs)
            K_Y_perm = self._compute_kernel_matrix(Y_perm, Y_perm, kernel_Y, **kwargs)
            
            # Center kernel matrices
            K_X_centered = self._center_kernel_matrix(K_X)
            K_Y_perm_centered = self._center_kernel_matrix(K_Y_perm)
            
            # Compute canonical correlations
            canonical_corrs = self._compute_kernel_cca(
                K_X_centered, K_Y_perm_centered, self.kcca_regularization
            )
            
            # Test statistic: maximum canonical correlation
            perm_statistic = np.max(canonical_corrs) if len(canonical_corrs) > 0 else 0.0
            permutation_statistics.append(perm_statistic)
        
        # Calculate p-value
        p_value = np.mean(np.array(permutation_statistics) >= observed_statistic)
        return max(0.001, min(0.999, p_value))
    
    def _kernel_ridge_permutation_test(self, X: np.ndarray, Y: np.ndarray, 
                                     observed_statistic: float, kernel_type: str, 
                                     **kwargs) -> float:
        """Permutation test for kernel ridge independence test"""
        n_permutations = min(self.n_permutations, 50)  # Very limited for efficiency
        permutation_statistics = []
        
        for _ in range(n_permutations):
            # Permute Y
            Y_perm = np.random.permutation(Y)
            
            # Compute prediction accuracy for permuted data
            try:
                from sklearn.model_selection import cross_val_score
                from sklearn.kernel_ridge import KernelRidge
                
                # Create kernel ridge model
                kr = KernelRidge(kernel=kernel_type, alpha=kwargs.get('regularization', 1e-3))
                
                # Cross-validation scores
                cv_scores = cross_val_score(kr, X, Y_perm.ravel(), cv=3, scoring='neg_mean_squared_error')
                
                # Compute test statistic
                pred_error = -np.mean(cv_scores)
                baseline_error = np.var(Y_perm)
                
                if baseline_error > 0:
                    perm_statistic = 1.0 - (pred_error / baseline_error)
                    perm_statistic = max(0.0, perm_statistic)
                else:
                    perm_statistic = 0.0
                    
                permutation_statistics.append(perm_statistic)
                
            except Exception as e:
                # Fallback: random value
                permutation_statistics.append(np.random.uniform(0, 0.1))
        
        # Calculate p-value
        if permutation_statistics:
            p_value = np.mean(np.array(permutation_statistics) >= observed_statistic)
            return max(0.001, min(0.999, p_value))
        else:
            return 0.5  # Neutral p-value
    
    def get_available_kernels(self) -> List[str]:
        """Get list of available kernel functions"""
        return ['rbf', 'polynomial', 'linear', 'laplacian']
    
    def set_kernel_parameters(self, kernel_type: str, **kwargs) -> None:
        """Set parameters for specific kernel type"""
        if kernel_type not in self.config:
            self.config[kernel_type] = {}
        
        self.config[kernel_type].update(kwargs)
        self.logger.info(f"Updated parameters for {kernel_type} kernel: {kwargs}")
    
    def benchmark_kernels(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Dict[str, Any]]:
        """Benchmark different kernel types on given data"""
        results = {}
        kernels_to_test = ['rbf', 'polynomial', 'linear']
        
        for kernel in kernels_to_test:
            try:
                start_time = time.time()
                result = self.hsic_test(X, Y, kernel, kernel)
                result['kernel_computation_time'] = time.time() - start_time
                results[kernel] = result
            except Exception as e:
                results[kernel] = {'error': str(e)}
        
        return results


class InformationTheoreticTests:
    """
    Advanced information-theoretic independence testing methods.
    
    Implements mutual information, transfer entropy, conditional mutual information,
    and other information-theoretic measures for independence testing with
    comprehensive estimation methods and statistical validation.
    """
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        """Initialize information-theoretic test engine"""
        self.config = config or {}
        self.logger = logging.getLogger(__name__)
        
        # Performance monitoring
        global performance_monitor
        self.performance_monitor = performance_monitor
        
        # Estimation method configurations
        self.estimation_methods = self.config.get('estimation_methods', 
                                                ['ksg', 'histogram', 'knn', 'kernel'])
        self.default_method = self.config.get('default_method', 'ksg')
        
        # KSG estimator parameters
        self.ksg_config = self.config.get('ksg', {})
        self.ksg_k = self.ksg_config.get('k', 3)  # Number of nearest neighbors
        
        # Histogram estimator parameters
        self.hist_config = self.config.get('histogram', {})
        self.hist_bins = self.hist_config.get('bins', 'auto')
        
        # KNN estimator parameters
        self.knn_config = self.config.get('knn', {})
        self.knn_k = self.knn_config.get('k', 5)
        
        # Transfer entropy parameters
        self.te_config = self.config.get('transfer_entropy', {})
        self.te_history_length = self.te_config.get('history_length', 1)
        self.te_delay = self.te_config.get('delay', 1)
        
        # Statistical test parameters
        self.n_permutations = self.config.get('n_permutations', 500)
        self.significance_level = self.config.get('significance_level', 0.05)
        
        # Cache for computed entropies
        self.entropy_cache = {}
        
        self.logger.info("InformationTheoreticTests initialized successfully")
    
    def mutual_information_test(self, X: np.ndarray, Y: np.ndarray, 
                               method: str = 'auto', **kwargs) -> Dict[str, Any]:
        """
        Mutual information independence test
        
        Tests independence by measuring mutual information between X and Y.
        Higher MI indicates stronger dependence.
        
        Args:
            X: First variable data
            Y: Second variable data  
            method: Estimation method ('ksg', 'histogram', 'knn', 'kernel', 'auto')
            
        Returns:
            Dictionary with test results
        """
        start_time = time.time()
        
        try:
            # Ensure data is properly shaped
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            n_samples = X.shape[0]
            
            # Auto-select method based on data characteristics
            if method == 'auto':
                method = self._select_optimal_mi_method(X, Y)
            
            self.logger.info(f"Computing mutual information using {method} method")
            
            # Compute mutual information
            if method == 'ksg':
                mi_value = self._mi_ksg_estimator(X, Y, **kwargs)
            elif method == 'histogram':
                mi_value = self._mi_histogram_estimator(X, Y, **kwargs)
            elif method == 'knn':
                mi_value = self._mi_knn_estimator(X, Y, **kwargs)
            elif method == 'kernel':
                mi_value = self._mi_kernel_estimator(X, Y, **kwargs)
            else:
                raise ValueError(f"Unknown MI estimation method: {method}")
            
            # Normalize MI by marginal entropies (compute normalized MI)
            H_X = self._estimate_entropy(X, method, **kwargs)
            H_Y = self._estimate_entropy(Y, method, **kwargs)
            
            if H_X > 0 and H_Y > 0:
                normalized_mi = mi_value / min(H_X, H_Y)
            else:
                normalized_mi = 0.0
            
            # Statistical significance testing
            p_value = self._mi_permutation_test(X, Y, mi_value, method, **kwargs)
            
            # Bootstrap confidence intervals
            confidence_interval = self._mi_bootstrap_ci(X, Y, method, **kwargs)
            
            # Effect size measures
            effect_size_measures = self._compute_mi_effect_sizes(X, Y, mi_value, H_X, H_Y)
            
            result = {
                'mutual_information': float(mi_value),
                'normalized_mi': float(normalized_mi),
                'entropy_X': float(H_X),
                'entropy_Y': float(H_Y),
                'p_value': float(p_value),
                'independent': p_value > self.significance_level,
                'confidence_interval': confidence_interval,
                'effect_sizes': effect_size_measures,
                'method': method,
                'n_samples': n_samples,
                'computation_time': time.time() - start_time
            }
            
            # Update performance metrics
            self.performance_monitor.record_operation("mutual_information_test", time.time() - start_time)
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in mutual information test: {e}")
            return {
                'mutual_information': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': f'{method}_fallback'
            }
    
    def transfer_entropy_test(self, X: np.ndarray, Y: np.ndarray, 
                             history_length: Optional[int] = None,
                             delay: Optional[int] = None) -> Dict[str, Any]:
        """
        Transfer entropy test for directed information flow
        
        Measures the amount of information transferred from X to Y,
        accounting for the history of both variables.
        
        Args:
            X: Source time series
            Y: Target time series
            history_length: Length of history to consider
            delay: Time delay for transfer
            
        Returns:
            Dictionary with test results
        """
        start_time = time.time()
        
        try:
            if history_length is None:
                history_length = self.te_history_length
            if delay is None:
                delay = self.te_delay
            
            # Ensure 1D time series
            if X.ndim > 1:
                X = X.flatten()
            if Y.ndim > 1:
                Y = Y.flatten()
            
            # Prepare embedded data
            X_embedded, Y_embedded, Y_future = self._prepare_transfer_entropy_data(
                X, Y, history_length, delay
            )
            
            if X_embedded.shape[0] < 10:  # Insufficient data
                return {
                    'transfer_entropy_X_to_Y': 0.0,
                    'transfer_entropy_Y_to_X': 0.0,
                    'net_transfer_entropy': 0.0,
                    'p_value_X_to_Y': 1.0,
                    'p_value_Y_to_X': 1.0,
                    'error': 'Insufficient data for transfer entropy calculation'
                }
            
            # Compute transfer entropy X -> Y
            te_x_to_y = self._compute_transfer_entropy(X_embedded, Y_embedded, Y_future)
            
            # Compute transfer entropy Y -> X  
            X_embedded_rev, Y_embedded_rev, X_future = self._prepare_transfer_entropy_data(
                Y, X, history_length, delay
            )
            te_y_to_x = self._compute_transfer_entropy(Y_embedded_rev, X_embedded_rev, X_future)
            
            # Net transfer entropy
            net_te = te_x_to_y - te_y_to_x
            
            # Statistical significance testing
            p_value_x_to_y = self._te_permutation_test(X_embedded, Y_embedded, Y_future, te_x_to_y)
            p_value_y_to_x = self._te_permutation_test(Y_embedded_rev, X_embedded_rev, X_future, te_y_to_x)
            
            # Bootstrap confidence intervals
            ci_x_to_y = self._te_bootstrap_ci(X_embedded, Y_embedded, Y_future)
            ci_y_to_x = self._te_bootstrap_ci(Y_embedded_rev, X_embedded_rev, X_future)
            
            result = {
                'transfer_entropy_X_to_Y': float(te_x_to_y),
                'transfer_entropy_Y_to_X': float(te_y_to_x),
                'net_transfer_entropy': float(net_te),
                'p_value_X_to_Y': float(p_value_x_to_y),
                'p_value_Y_to_X': float(p_value_y_to_x),
                'significant_X_to_Y': p_value_x_to_y < self.significance_level,
                'significant_Y_to_X': p_value_y_to_x < self.significance_level,
                'confidence_interval_X_to_Y': ci_x_to_y,
                'confidence_interval_Y_to_X': ci_y_to_x,
                'history_length': history_length,
                'delay': delay,
                'method': 'TransferEntropy',
                'computation_time': time.time() - start_time
            }
            
            # Update performance metrics
            self.performance_monitor.record_operation("transfer_entropy_test", time.time() - start_time)
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in transfer entropy test: {e}")
            return {
                'transfer_entropy_X_to_Y': 0.0,
                'transfer_entropy_Y_to_X': 0.0,
                'net_transfer_entropy': 0.0,
                'error': str(e),
                'method': 'TransferEntropy_fallback'
            }
    
    def conditional_mutual_information_test(self, X: np.ndarray, Y: np.ndarray, 
                                          Z: np.ndarray, method: str = 'auto') -> Dict[str, Any]:
        """
        Conditional mutual information test I(X;Y|Z)
        
        Tests independence of X and Y given Z using conditional mutual information.
        
        Args:
            X: First variable
            Y: Second variable
            Z: Conditioning variable(s)
            method: Estimation method
            
        Returns:
            Dictionary with test results
        """
        start_time = time.time()
        
        try:
            # Ensure proper data shapes
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            if Z.ndim == 1:
                Z = Z.reshape(-1, 1)
            
            # Auto-select method
            if method == 'auto':
                method = self._select_optimal_mi_method(X, Y)
            
            # Compute conditional mutual information: I(X;Y|Z) = I(X;Y,Z) - I(X;Z)
            XYZ = np.hstack([X, Y, Z])
            XZ = np.hstack([X, Z])
            
            if method == 'ksg':
                mi_xyz = self._mi_ksg_estimator(X, XYZ)
                mi_xz = self._mi_ksg_estimator(X, XZ)
            elif method == 'histogram':
                mi_xyz = self._mi_histogram_estimator(X, XYZ)
                mi_xz = self._mi_histogram_estimator(X, XZ)
            elif method == 'knn':
                mi_xyz = self._mi_knn_estimator(X, XYZ)
                mi_xz = self._mi_knn_estimator(X, XZ)
            else:
                # Fallback to simple correlation-based approach
                mi_xyz = self._mi_correlation_fallback(X, XYZ)
                mi_xz = self._mi_correlation_fallback(X, XZ)
            
            cmi_value = mi_xyz - mi_xz
            
            # Statistical significance
            p_value = self._cmi_permutation_test(X, Y, Z, cmi_value, method)
            
            # Effect size normalization
            H_X_given_Z = self._estimate_conditional_entropy(X, Z, method)
            H_Y_given_Z = self._estimate_conditional_entropy(Y, Z, method)
            
            if min(H_X_given_Z, H_Y_given_Z) > 0:
                normalized_cmi = cmi_value / min(H_X_given_Z, H_Y_given_Z)
            else:
                normalized_cmi = 0.0
            
            result = {
                'conditional_mutual_information': float(cmi_value),
                'normalized_cmi': float(normalized_cmi),
                'p_value': float(p_value),
                'independent': p_value > self.significance_level,
                'H_X_given_Z': float(H_X_given_Z),
                'H_Y_given_Z': float(H_Y_given_Z),
                'method': method,
                'computation_time': time.time() - start_time
            }
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in conditional MI test: {e}")
            return {
                'conditional_mutual_information': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': f'{method}_fallback'
            }
    
    def ensemble_information_test(self, X: np.ndarray, Y: np.ndarray, 
                                 Z: Optional[np.ndarray] = None) -> Dict[str, Any]:
        """
        Ensemble information-theoretic independence test
        """
        start_time = time.time()
        
        try:
            results = {}
            
            # Mutual information with different estimators
            for method in ['ksg', 'histogram', 'knn']:
                try:
                    if Z is None:
                        results[f'mi_{method}'] = self.mutual_information_test(X, Y, method)
                    else:
                        results[f'cmi_{method}'] = self.conditional_mutual_information_test(X, Y, Z, method)
                except Exception as e:
                    self.logger.warning(f"Method {method} failed: {e}")
                    continue
            
            # Transfer entropy (if time series data)
            if X.ndim == 1 and Y.ndim == 1 and len(X) > 20:
                try:
                    results['transfer_entropy'] = self.transfer_entropy_test(X, Y)
                except Exception as e:
                    self.logger.warning(f"Transfer entropy failed: {e}")
            
            # Multi-information (if more than 2 variables)
            if Z is not None:
                try:
                    results['multi_information'] = self._multi_information_test(X, Y, Z)
                except Exception as e:
                    self.logger.warning(f"Multi-information failed: {e}")
            
            # Aggregate results
            if results:
                # Extract test statistics and p-values
                test_statistics = []
                p_values = []
                
                for key, result in results.items():
                    if 'error' not in result:
                        if 'mutual_information' in result:
                            test_statistics.append(result['mutual_information'])
                            p_values.append(result['p_value'])
                        elif 'conditional_mutual_information' in result:
                            test_statistics.append(result['conditional_mutual_information'])
                            p_values.append(result['p_value'])
                        elif 'transfer_entropy_X_to_Y' in result:
                            test_statistics.append(result['transfer_entropy_X_to_Y'])
                            p_values.append(result['p_value_X_to_Y'])
                
                if test_statistics and p_values:
                    # Fisher's combined test for p-values
                    chi2_statistic = -2 * np.sum(np.log(np.array(p_values) + 1e-10))
                    from scipy.stats import chi2
                    combined_p_value = 1 - chi2.cdf(chi2_statistic, 2 * len(p_values))
                    
                    # Average test statistic
                    mean_test_statistic = np.mean(test_statistics)
                else:
                    combined_p_value = 1.0
                    mean_test_statistic = 0.0
                
                ensemble_result = {
                    'test_statistic': float(mean_test_statistic),
                    'p_value': float(combined_p_value),
                    'independent': combined_p_value > self.significance_level,
                    'individual_results': results,
                    'method': 'EnsembleInformationTheoretic',
                    'n_successful_tests': len(test_statistics),
                    'computation_time': time.time() - start_time
                }
                
                return ensemble_result
            else:
                raise RuntimeError("All information-theoretic tests failed")
                
        except Exception as e:
            self.logger.error(f"Error in ensemble information test: {e}")
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': 'EnsembleInformationTheoretic_fallback'
            }
    
    # Helper methods for mutual information estimation
    def _select_optimal_mi_method(self, X: np.ndarray, Y: np.ndarray) -> str:
        """Select optimal MI estimation method based on data characteristics"""
        n_samples, n_features_x = X.shape[0], X.shape[1]
        n_features_y = Y.shape[1]
        
        # Decision logic based on sample size and dimensionality
        if n_samples < 100:
            return 'histogram'  # Better for small samples
        elif n_features_x + n_features_y > 10:
            return 'knn'  # Better for high dimensions
        elif n_samples > 1000:
            return 'ksg'  # KSG is generally most accurate for large samples
        else:
            return 'histogram'  # Safe default
    
    def _mi_ksg_estimator(self, X: np.ndarray, Y: np.ndarray, **kwargs) -> float:
        """
        Kraskov-Stoegbauer-Grassberger (KSG) mutual information estimator
        
        High-quality MI estimator based on k-nearest neighbors.
        """
        try:
            k = kwargs.get('k', self.ksg_k)
            
            # Combine data
            XY = np.hstack([X, Y])
            n_samples = XY.shape[0]
            
            # Find k-nearest neighbors in joint space
            from sklearn.neighbors import NearestNeighbors
            
            # Joint space NN
            nn_joint = NearestNeighbors(n_neighbors=k+1, metric='chebyshev')
            nn_joint.fit(XY)
            distances_joint, _ = nn_joint.kneighbors(XY)
            epsilon = distances_joint[:, k]  # Distance to k-th neighbor
            
            # Count neighbors in marginal spaces
            mi_sum = 0.0
            
            for i in range(n_samples):
                # Count neighbors in X marginal space within epsilon[i]
                X_distances = np.max(np.abs(X - X[i]), axis=1)
                n_x = np.sum(X_distances < epsilon[i]) - 1  # Exclude point itself
                
                # Count neighbors in Y marginal space within epsilon[i]
                Y_distances = np.max(np.abs(Y - Y[i]), axis=1)
                n_y = np.sum(Y_distances < epsilon[i]) - 1  # Exclude point itself
                
                # KSG estimator contribution
                if n_x > 0 and n_y > 0:
                    mi_sum += np.log(n_x) + np.log(n_y)
            
            # KSG MI estimate
            mi_estimate = (special.digamma(k) - mi_sum / n_samples + 
                          special.digamma(n_samples))
            
            return max(0.0, mi_estimate)  # MI should be non-negative
            
        except Exception as e:
            self.logger.warning(f"KSG estimator failed: {e}")
            # Fallback to correlation-based estimate
            return self._mi_correlation_fallback(X, Y)
    
    def _mi_histogram_estimator(self, X: np.ndarray, Y: np.ndarray, **kwargs) -> float:
        """Histogram-based mutual information estimator"""
        try:
            bins = kwargs.get('bins', self.hist_bins)
            
            # Discretize data
            if isinstance(bins, str) and bins == 'auto':
                # Automatic bin selection using Freedman-Diaconis rule
                n_samples = X.shape[0]
                
                # For X
                X_flat = X.flatten()
                iqr_x = np.percentile(X_flat, 75) - np.percentile(X_flat, 25)
                h_x = 2 * iqr_x / (n_samples ** (1/3))
                bins_x = max(5, min(50, int((np.max(X_flat) - np.min(X_flat)) / h_x)))
                
                # For Y
                Y_flat = Y.flatten()
                iqr_y = np.percentile(Y_flat, 75) - np.percentile(Y_flat, 25)
                h_y = 2 * iqr_y / (n_samples ** (1/3))
                bins_y = max(5, min(50, int((np.max(Y_flat) - np.min(Y_flat)) / h_y)))
                
                bins = (bins_x, bins_y)
            
            # Compute joint and marginal histograms
            hist_xy, x_edges, y_edges = np.histogram2d(X.flatten(), Y.flatten(), bins=bins)
            hist_x = np.histogram(X.flatten(), bins=x_edges)[0]
            hist_y = np.histogram(Y.flatten(), bins=y_edges)[0]
            
            # Convert to probabilities
            p_xy = hist_xy / np.sum(hist_xy)
            p_x = hist_x / np.sum(hist_x)
            p_y = hist_y / np.sum(hist_y)
            
            # Compute MI
            mi_value = 0.0
            for i in range(len(p_x)):
                for j in range(len(p_y)):
                    if p_xy[i, j] > 0 and p_x[i] > 0 and p_y[j] > 0:
                        mi_value += p_xy[i, j] * np.log(p_xy[i, j] / (p_x[i] * p_y[j]))
            
            return max(0.0, mi_value)
            
        except Exception as e:
            self.logger.warning(f"Histogram estimator failed: {e}")
            return self._mi_correlation_fallback(X, Y)
    
    def _mi_knn_estimator(self, X: np.ndarray, Y: np.ndarray, **kwargs) -> float:
        """k-Nearest Neighbors mutual information estimator"""
        try:
            k = kwargs.get('k', self.knn_k)
            
            # Combine data
            XY = np.hstack([X, Y])
            n_samples = XY.shape[0]
            
            from sklearn.neighbors import NearestNeighbors
            
            # Find k-nearest neighbors
            nn = NearestNeighbors(n_neighbors=k+1)
            nn.fit(XY)
            distances, indices = nn.kneighbors(XY)
            
            # Estimate MI using KNN method
            mi_estimate = 0.0
            
            for i in range(n_samples):
                # Distance to k-th neighbor
                epsilon = distances[i, k]
                
                # Count neighbors within epsilon in marginal spaces
                X_distances = np.linalg.norm(X - X[i], axis=1)
                Y_distances = np.linalg.norm(Y - Y[i], axis=1)
                
                n_x = np.sum(X_distances < epsilon)
                n_y = np.sum(Y_distances < epsilon)
                
                if n_x > 0 and n_y > 0:
                    mi_estimate += np.log(n_x * n_y / k)
            
            mi_estimate = mi_estimate / n_samples + np.log(k) - np.log(n_samples - 1)
            
            return max(0.0, mi_estimate)
            
        except Exception as e:
            self.logger.warning(f"KNN estimator failed: {e}")
            return self._mi_correlation_fallback(X, Y)
    
    def _mi_kernel_estimator(self, X: np.ndarray, Y: np.ndarray, **kwargs) -> float:
        """Kernel density estimation-based MI estimator"""
        try:
            from sklearn.neighbors import KernelDensity
            
            # Bandwidth selection
            bandwidth = kwargs.get('bandwidth', 'scott')
            
            if bandwidth == 'scott':
                # Scott's rule for bandwidth
                n_samples = X.shape[0]
                d_x = X.shape[1]
                d_y = Y.shape[1]
                
                bw_x = n_samples ** (-1 / (d_x + 4))
                bw_y = n_samples ** (-1 / (d_y + 4))
                bw_xy = n_samples ** (-1 / (d_x + d_y + 4))
            else:
                bw_x = bw_y = bw_xy = bandwidth
            
            # Fit kernel density estimators
            kde_x = KernelDensity(bandwidth=bw_x).fit(X)
            kde_y = KernelDensity(bandwidth=bw_y).fit(Y)
            kde_xy = KernelDensity(bandwidth=bw_xy).fit(np.hstack([X, Y]))
            
            # Estimate densities at data points
            log_dens_x = kde_x.score_samples(X)
            log_dens_y = kde_y.score_samples(Y)
            log_dens_xy = kde_xy.score_samples(np.hstack([X, Y]))
            
            # MI estimate
            mi_estimate = np.mean(log_dens_xy - log_dens_x - log_dens_y)
            
            return max(0.0, mi_estimate)
            
        except Exception as e:
            self.logger.warning(f"Kernel estimator failed: {e}")
            return self._mi_correlation_fallback(X, Y)
    
    def _mi_correlation_fallback(self, X: np.ndarray, Y: np.ndarray) -> float:
        """Simple correlation-based MI approximation as fallback"""
        try:
            # Use canonical correlation for multivariate case
            if X.shape[1] > 1 or Y.shape[1] > 1:
                from sklearn.cross_decomposition import CCA
                cca = CCA(n_components=1)
                cca.fit(X, Y)
                corr = np.corrcoef(cca.transform(X).flatten(), cca.transform(Y).flatten())[0, 1]
            else:
                # Simple Pearson correlation
                corr = np.corrcoef(X.flatten(), Y.flatten())[0, 1]
            
            # Convert correlation to approximate MI
            if not np.isnan(corr) and abs(corr) < 0.999:
                mi_approx = -0.5 * np.log(1 - corr**2)
                return max(0.0, mi_approx)
            else:
                return 0.0
                
        except Exception as e:
            self.logger.error(f"Correlation fallback failed: {e}")
            return 0.0
    
    def _estimate_entropy(self, data: np.ndarray, method: str, **kwargs) -> float:
        """Estimate entropy of data using specified method"""
        try:
            # Cache key
            cache_key = f"{method}_{hash(data.tobytes())}"
            if cache_key in self.entropy_cache:
                return self.entropy_cache[cache_key]
            
            if method == 'ksg':
                entropy = self._entropy_ksg(data, **kwargs)
            elif method == 'histogram':
                entropy = self._entropy_histogram(data, **kwargs)
            elif method == 'knn':
                entropy = self._entropy_knn(data, **kwargs)
            else:
                # Fallback: Gaussian entropy approximation
                entropy = self._entropy_gaussian_approx(data)
            
            # Cache result
            self.entropy_cache[cache_key] = entropy
            return entropy
            
        except Exception as e:
            self.logger.warning(f"Entropy estimation failed: {e}")
            return self._entropy_gaussian_approx(data)
    
    def _entropy_ksg(self, data: np.ndarray, **kwargs) -> float:
        """KSG entropy estimator"""
        try:
            k = kwargs.get('k', self.ksg_k)
            n_samples, n_dims = data.shape
            
            from sklearn.neighbors import NearestNeighbors
            
            # Find k-nearest neighbors
            nn = NearestNeighbors(n_neighbors=k+1, metric='chebyshev')
            nn.fit(data)
            distances, _ = nn.kneighbors(data)
            
            # KSG entropy estimate
            epsilon = distances[:, k]  # Distance to k-th neighbor
            
            # Volume of unit ball in n_dims dimensions
            log_volume_unit_ball = (n_dims / 2) * np.log(np.pi) - special.loggamma(n_dims / 2 + 1)
            
            entropy = (special.digamma(n_samples) - special.digamma(k) + 
                      log_volume_unit_ball + n_dims * np.mean(np.log(epsilon + 1e-10)))
            
            return entropy
            
        except Exception as e:
            self.logger.warning(f"KSG entropy estimation failed: {e}")
            return self._entropy_gaussian_approx(data)
    
    def _entropy_histogram(self, data: np.ndarray, **kwargs) -> float:
        """Histogram-based entropy estimator"""
        try:
            bins = kwargs.get('bins', self.hist_bins)
            
            if isinstance(bins, str) and bins == 'auto':
                # Automatic bin selection
                n_samples = data.shape[0]
                if data.shape[1] == 1:
                    # 1D case
                    data_flat = data.flatten()
                    iqr = np.percentile(data_flat, 75) - np.percentile(data_flat, 25)
                    h = 2 * iqr / (n_samples ** (1/3))
                    bins = max(5, min(50, int((np.max(data_flat) - np.min(data_flat)) / h)))
                else:
                    # Multi-dimensional case
                    bins = max(5, min(20, int(n_samples ** (1 / (data.shape[1] + 2)))))
            
            # Compute histogram
            if data.shape[1] == 1:
                hist, _ = np.histogram(data.flatten(), bins=bins)
            else:
                hist, _ = np.histogramdd(data, bins=bins)
            
            # Convert to probabilities
            p = hist / np.sum(hist)
            
            # Compute entropy
            entropy = -np.sum(p[p > 0] * np.log(p[p > 0]))
            
            return entropy
            
        except Exception as e:
            self.logger.warning(f"Histogram entropy estimation failed: {e}")
            return self._entropy_gaussian_approx(data)
    
    def _entropy_knn(self, data: np.ndarray, **kwargs) -> float:
        """k-NN entropy estimator"""
        try:
            k = kwargs.get('k', self.knn_k)
            n_samples, n_dims = data.shape
            
            from sklearn.neighbors import NearestNeighbors
            
            # Find k-nearest neighbors
            nn = NearestNeighbors(n_neighbors=k+1)
            nn.fit(data)
            distances, _ = nn.kneighbors(data)
            
            # Distance to k-th neighbor
            rho_k = distances[:, k]
            
            # Volume of unit ball
            log_volume_unit_ball = (n_dims / 2) * np.log(np.pi) - special.loggamma(n_dims / 2 + 1)
            
            # KNN entropy estimate
            entropy = (log_volume_unit_ball + n_dims * np.mean(np.log(rho_k + 1e-10)) + 
                      special.digamma(n_samples) - special.digamma(k))
            
            return entropy
            
        except Exception as e:
            self.logger.warning(f"KNN entropy estimation failed: {e}")
            return self._entropy_gaussian_approx(data)
    
    def _entropy_gaussian_approx(self, data: np.ndarray) -> float:
        """Gaussian approximation of entropy"""
        try:
            n_dims = data.shape[1]
            
            # Covariance matrix
            cov_matrix = np.cov(data.T)
            
            # Determinant
            det_cov = np.linalg.det(cov_matrix + 1e-10 * np.eye(n_dims))
            
            # Gaussian entropy
            entropy = 0.5 * n_dims * (1 + np.log(2 * np.pi)) + 0.5 * np.log(abs(det_cov))
            
            return entropy
            
        except Exception as e:
            self.logger.error(f"Gaussian entropy approximation failed: {e}")
            return 1.0  # Default entropy value
    
    def _estimate_conditional_entropy(self, X: np.ndarray, Z: np.ndarray, method: str) -> float:
        """Estimate conditional entropy H(X|Z)"""
        try:
            # H(X|Z) = H(X,Z) - H(Z)
            XZ = np.hstack([X, Z])
            H_XZ = self._estimate_entropy(XZ, method)
            H_Z = self._estimate_entropy(Z, method)
            
            conditional_entropy = H_XZ - H_Z
            return max(0.0, conditional_entropy)
            
        except Exception as e:
            self.logger.warning(f"Conditional entropy estimation failed: {e}")
            return self._estimate_entropy(X, method)  # Fallback to marginal entropy
    
    # Transfer entropy helper methods
    def _prepare_transfer_entropy_data(self, X: np.ndarray, Y: np.ndarray, 
                                     history_length: int, delay: int) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """Prepare embedded data for transfer entropy calculation"""
        min_length = max(history_length + delay, 10)
        
        if len(X) < min_length or len(Y) < min_length:
            raise ValueError("Insufficient data for transfer entropy calculation")
        
        # Create embedded vectors
        X_embedded = []
        Y_embedded = []
        Y_future = []
        
        for t in range(history_length, len(X) - delay):
            # History of X
            x_hist = X[t-history_length:t]
            X_embedded.append(x_hist)
            
            # History of Y
            y_hist = Y[t-history_length:t]
            Y_embedded.append(y_hist)
            
            # Future value of Y
            y_fut = Y[t + delay]
            Y_future.append(y_fut)
        
        return (np.array(X_embedded), np.array(Y_embedded), np.array(Y_future))
    
    def _compute_transfer_entropy(self, X_embedded: np.ndarray, Y_embedded: np.ndarray, 
                                Y_future: np.ndarray) -> float:
        """Compute transfer entropy TE = I(Y_future; X_embedded | Y_embedded)"""
        try:
            # Reshape for consistency
            if Y_future.ndim == 1:
                Y_future = Y_future.reshape(-1, 1)
            
            # Conditional mutual information approach
            # TE(X->Y) = I(Y_future; X_embedded | Y_embedded)
            #          = H(Y_future | Y_embedded) - H(Y_future | X_embedded, Y_embedded)
            
            # Joint data
            XY_embedded = np.hstack([X_embedded, Y_embedded])
            
            # Compute conditional entropies using KSG
            H_Y_given_Y_past = self._conditional_entropy_ksg(Y_future, Y_embedded)
            H_Y_given_XY_past = self._conditional_entropy_ksg(Y_future, XY_embedded)
            
            transfer_entropy = H_Y_given_Y_past - H_Y_given_XY_past
            
            return max(0.0, transfer_entropy)
            
        except Exception as e:
            self.logger.warning(f"Transfer entropy computation failed: {e}")
            # Fallback to correlation-based approximation
            return self._te_correlation_fallback(X_embedded, Y_embedded, Y_future)
    
    def _conditional_entropy_ksg(self, Y: np.ndarray, Z: np.ndarray) -> float:
        """Conditional entropy H(Y|Z) using KSG estimator"""
        try:
            # H(Y|Z) = H(Y,Z) - H(Z)
            YZ = np.hstack([Y, Z])
            H_YZ = self._entropy_ksg(YZ)
            H_Z = self._entropy_ksg(Z)
            
            return max(0.0, H_YZ - H_Z)
            
        except Exception as e:
            self.logger.warning(f"Conditional entropy KSG failed: {e}")
            return self._entropy_gaussian_approx(Y)
    
    def _te_correlation_fallback(self, X_embedded: np.ndarray, Y_embedded: np.ndarray, 
                               Y_future: np.ndarray) -> float:
        """Correlation-based transfer entropy fallback"""
        try:
            from sklearn.linear_model import LinearRegression
            
            # Predict Y_future from Y_embedded only
            reg_y = LinearRegression().fit(Y_embedded, Y_future.ravel())
            Y_pred_y = reg_y.predict(Y_embedded)
            mse_y = np.mean((Y_future.ravel() - Y_pred_y)**2)
            
            # Predict Y_future from both X_embedded and Y_embedded
            XY_embedded = np.hstack([X_embedded, Y_embedded])
            reg_xy = LinearRegression().fit(XY_embedded, Y_future.ravel())
            Y_pred_xy = reg_xy.predict(XY_embedded)
            mse_xy = np.mean((Y_future.ravel() - Y_pred_xy)**2)
            
            # Transfer entropy approximation
            if mse_xy > 0 and mse_y > 0:
                te_approx = 0.5 * np.log(mse_y / mse_xy)
                return max(0.0, te_approx)
            else:
                return 0.0
                
        except Exception as e:
            self.logger.error(f"TE correlation fallback failed: {e}")
            return 0.0
    
    # Statistical significance testing methods
    def _mi_permutation_test(self, X: np.ndarray, Y: np.ndarray, observed_mi: float,
                           method: str, **kwargs) -> float:
        """Permutation test for mutual information significance"""
        n_permutations = min(self.n_permutations, 100)  # Limit for efficiency
        permutation_statistics = []
        
        for _ in range(n_permutations):
            # Permute Y to break dependence
            Y_perm = np.random.permutation(Y)
            
            # Compute MI for permuted data
            try:
                if method == 'ksg':
                    perm_mi = self._mi_ksg_estimator(X, Y_perm, **kwargs)
                elif method == 'histogram':
                    perm_mi = self._mi_histogram_estimator(X, Y_perm, **kwargs)
                elif method == 'knn':
                    perm_mi = self._mi_knn_estimator(X, Y_perm, **kwargs)
                else:
                    perm_mi = self._mi_correlation_fallback(X, Y_perm)
                
                permutation_statistics.append(perm_mi)
                
            except Exception as e:
                permutation_statistics.append(0.0)  # Conservative fallback
        
        # Calculate p-value
        if permutation_statistics:
            p_value = np.mean(np.array(permutation_statistics) >= observed_mi)
            return max(0.001, min(0.999, p_value))
        else:
            return 0.5  # Neutral p-value
    
    def _mi_bootstrap_ci(self, X: np.ndarray, Y: np.ndarray, method: str,
                        confidence_level: float = 0.95, **kwargs) -> Dict[str, float]:
        """Bootstrap confidence intervals for mutual information"""
        n_bootstrap = 50  # Limited for efficiency
        bootstrap_statistics = []
        
        for _ in range(n_bootstrap):
            # Bootstrap sample
            indices = np.random.choice(X.shape[0], X.shape[0], replace=True)
            X_boot = X[indices]
            Y_boot = Y[indices]
            
            # Compute MI for bootstrap sample
            try:
                if method == 'ksg':
                    boot_mi = self._mi_ksg_estimator(X_boot, Y_boot, **kwargs)
                elif method == 'histogram':
                    boot_mi = self._mi_histogram_estimator(X_boot, Y_boot, **kwargs)
                elif method == 'knn':
                    boot_mi = self._mi_knn_estimator(X_boot, Y_boot, **kwargs)
                else:
                    boot_mi = self._mi_correlation_fallback(X_boot, Y_boot)
                
                bootstrap_statistics.append(boot_mi)
                
            except Exception as e:
                continue  # Skip failed bootstrap samples
        
        # Calculate confidence interval
        if bootstrap_statistics:
            alpha = 1 - confidence_level
            lower_percentile = (alpha / 2) * 100
            upper_percentile = (1 - alpha / 2) * 100
            
            return {
                'lower': float(np.percentile(bootstrap_statistics, lower_percentile)),
                'upper': float(np.percentile(bootstrap_statistics, upper_percentile))
            }
        else:
            return {'lower': 0.0, 'upper': 1.0}
    
    def _compute_mi_effect_sizes(self, X: np.ndarray, Y: np.ndarray, mi_value: float,
                               H_X: float, H_Y: float) -> Dict[str, float]:
        """Compute various effect size measures for mutual information"""
        effect_sizes = {}
        
        try:
            # Normalized mutual information variants
            if H_X > 0 and H_Y > 0:
                effect_sizes['nmi_arithmetic'] = mi_value / ((H_X + H_Y) / 2)
                effect_sizes['nmi_geometric'] = mi_value / np.sqrt(H_X * H_Y)
                effect_sizes['nmi_harmonic'] = mi_value / (2 * H_X * H_Y / (H_X + H_Y))
                effect_sizes['nmi_max'] = mi_value / max(H_X, H_Y)
                effect_sizes['nmi_min'] = mi_value / min(H_X, H_Y)
            
            # Adjusted mutual information (accounts for chance)
            effect_sizes['ami'] = self._adjusted_mutual_information(X, Y, mi_value)
            
            # Variation of information
            effect_sizes['vi'] = H_X + H_Y - 2 * mi_value
            
        except Exception as e:
            self.logger.warning(f"Effect size computation failed: {e}")
            effect_sizes = {'nmi': 0.0}
        
        return effect_sizes
    
    def _adjusted_mutual_information(self, X: np.ndarray, Y: np.ndarray, mi_value: float) -> float:
        """Compute adjusted mutual information (AMI)"""
        try:
            # Simple approximation: AMI ≈ MI - E[MI_random]
            # For continuous variables, expected random MI is typically small
            n_samples = X.shape[0]
            expected_random_mi = np.log(n_samples) / (2 * n_samples)  # Rough approximation
            
            return max(0.0, mi_value - expected_random_mi)
            
        except Exception as e:
            return mi_value  # Fallback to original MI
    
    def _cmi_permutation_test(self, X: np.ndarray, Y: np.ndarray, Z: np.ndarray,
                            observed_cmi: float, method: str) -> float:
        """Permutation test for conditional mutual information"""
        n_permutations = min(self.n_permutations, 50)  # Very limited for efficiency
        permutation_statistics = []
        
        for _ in range(n_permutations):
            # Permute Y while keeping Z fixed
            Y_perm = np.random.permutation(Y)
            
            # Compute CMI for permuted data
            try:
                XYZ_perm = np.hstack([X, Y_perm, Z])
                XZ = np.hstack([X, Z])
                
                if method == 'ksg':
                    mi_xyz_perm = self._mi_ksg_estimator(X, XYZ_perm)
                    mi_xz = self._mi_ksg_estimator(X, XZ)
                elif method == 'histogram':
                    mi_xyz_perm = self._mi_histogram_estimator(X, XYZ_perm)
                    mi_xz = self._mi_histogram_estimator(X, XZ)
                else:
                    mi_xyz_perm = self._mi_correlation_fallback(X, XYZ_perm)
                    mi_xz = self._mi_correlation_fallback(X, XZ)
                
                perm_cmi = mi_xyz_perm - mi_xz
                permutation_statistics.append(perm_cmi)
                
            except Exception as e:
                permutation_statistics.append(0.0)
        
        # Calculate p-value
        if permutation_statistics:
            p_value = np.mean(np.array(permutation_statistics) >= observed_cmi)
            return max(0.001, min(0.999, p_value))
        else:
            return 0.5
    
    def _te_permutation_test(self, X_embedded: np.ndarray, Y_embedded: np.ndarray,
                           Y_future: np.ndarray, observed_te: float) -> float:
        """Permutation test for transfer entropy significance"""
        n_permutations = min(self.n_permutations, 30)  # Very limited for efficiency
        permutation_statistics = []
        
        for _ in range(n_permutations):
            # Permute X_embedded to break causal relationship
            X_perm = np.random.permutation(X_embedded)
            
            # Compute TE for permuted data
            try:
                perm_te = self._compute_transfer_entropy(X_perm, Y_embedded, Y_future)
                permutation_statistics.append(perm_te)
            except Exception as e:
                permutation_statistics.append(0.0)
        
        # Calculate p-value
        if permutation_statistics:
            p_value = np.mean(np.array(permutation_statistics) >= observed_te)
            return max(0.001, min(0.999, p_value))
        else:
            return 0.5
    
    def _te_bootstrap_ci(self, X_embedded: np.ndarray, Y_embedded: np.ndarray,
                        Y_future: np.ndarray, confidence_level: float = 0.95) -> Dict[str, float]:
        """Bootstrap confidence intervals for transfer entropy"""
        n_bootstrap = 30  # Limited for efficiency
        bootstrap_statistics = []
        
        for _ in range(n_bootstrap):
            # Bootstrap sample
            indices = np.random.choice(X_embedded.shape[0], X_embedded.shape[0], replace=True)
            X_boot = X_embedded[indices]
            Y_emb_boot = Y_embedded[indices]
            Y_fut_boot = Y_future[indices]
            
            # Compute TE for bootstrap sample
            try:
                boot_te = self._compute_transfer_entropy(X_boot, Y_emb_boot, Y_fut_boot)
                bootstrap_statistics.append(boot_te)
            except Exception as e:
                continue
        
        # Calculate confidence interval
        if bootstrap_statistics:
            alpha = 1 - confidence_level
            lower_percentile = (alpha / 2) * 100
            upper_percentile = (1 - alpha / 2) * 100
            
            return {
                'lower': float(np.percentile(bootstrap_statistics, lower_percentile)),
                'upper': float(np.percentile(bootstrap_statistics, upper_percentile))
            }
        else:
            return {'lower': 0.0, 'upper': 1.0}
    
    def _multi_information_test(self, X: np.ndarray, Y: np.ndarray, Z: np.ndarray) -> Dict[str, Any]:
        """Multi-information (total correlation) test for multiple variables"""
        try:
            start_time = time.time()
            
            # Multi-information: I(X;Y;Z) = H(X) + H(Y) + H(Z) - H(X,Y,Z)
            H_X = self._estimate_entropy(X, 'ksg')
            H_Y = self._estimate_entropy(Y, 'ksg')
            H_Z = self._estimate_entropy(Z, 'ksg')
            
            XYZ = np.hstack([X, Y, Z])
            H_XYZ = self._estimate_entropy(XYZ, 'ksg')
            
            multi_info = H_X + H_Y + H_Z - H_XYZ
            
            # Permutation test (simplified)
            n_permutations = 20
            perm_statistics = []
            
            for _ in range(n_permutations):
                # Permute one variable
                Z_perm = np.random.permutation(Z)
                XYZ_perm = np.hstack([X, Y, Z_perm])
                H_XYZ_perm = self._estimate_entropy(XYZ_perm, 'ksg')
                
                perm_multi_info = H_X + H_Y + self._estimate_entropy(Z_perm, 'ksg') - H_XYZ_perm
                perm_statistics.append(perm_multi_info)
            
            p_value = np.mean(np.array(perm_statistics) >= multi_info)
            
            return {
                'multi_information': float(multi_info),
                'p_value': float(max(0.001, min(0.999, p_value))),
                'marginal_entropies': [float(H_X), float(H_Y), float(H_Z)],
                'joint_entropy': float(H_XYZ),
                'computation_time': time.time() - start_time
            }
            
        except Exception as e:
            self.logger.error(f"Multi-information test failed: {e}")
            return {
                'multi_information': 0.0,
                'p_value': 1.0,
                'error': str(e)
            }


class DistanceBasedIndependenceTests:
    """
    Advanced distance-based independence testing methods.
    
    Implements distance correlation, energy statistics, ball statistics,
    and other distance-based measures for independence testing with
    comprehensive statistical validation and ensemble methods.
    """
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        """Initialize distance-based independence test engine"""
        self.config = config or {}
        self.logger = logging.getLogger(__name__)
        
        # Performance monitoring
        global performance_monitor
        self.performance_monitor = performance_monitor
        
        # Distance metric configurations
        self.distance_metrics = self.config.get('distance_metrics', 
                                              ['euclidean', 'manhattan', 'chebyshev'])
        self.default_metric = self.config.get('default_metric', 'euclidean')
        
        # Distance correlation parameters
        self.dcorr_config = self.config.get('distance_correlation', {})
        
        # Energy statistics parameters
        self.energy_config = self.config.get('energy_statistics', {})
        
        # Ball statistics parameters
        self.ball_config = self.config.get('ball_statistics', {})
        
        # Statistical test parameters
        self.n_permutations = self.config.get('n_permutations', 500)
        self.significance_level = self.config.get('significance_level', 0.05)
        
        # Cache for distance matrices
        self.distance_cache = {}
        
        self.logger.info("DistanceBasedIndependenceTests initialized successfully")
    
    def distance_correlation_test(self, X: np.ndarray, Y: np.ndarray, 
                                 metric: str = 'euclidean') -> Dict[str, Any]:
        """
        Distance correlation test for independence
        
        Distance correlation measures both linear and nonlinear dependence
        and is zero if and only if the variables are independent.
        
        Args:
            X: First variable data
            Y: Second variable data
            metric: Distance metric to use
            
        Returns:
            Dictionary with test results
        """
        start_time = time.time()
        
        try:
            # Ensure data is 2D
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            n_samples = X.shape[0]
            
            # Compute distance matrices
            dist_X = self._compute_distance_matrix(X, metric)
            dist_Y = self._compute_distance_matrix(Y, metric)
            
            # Double center distance matrices
            dcent_X = self._double_center_distance_matrix(dist_X)
            dcent_Y = self._double_center_distance_matrix(dist_Y)
            
            # Compute distance covariance
            dcov_XY = self._distance_covariance(dcent_X, dcent_Y)
            
            # Compute distance variances
            dvar_X = self._distance_variance(dcent_X)
            dvar_Y = self._distance_variance(dcent_Y)
            
            # Distance correlation
            if dvar_X > 0 and dvar_Y > 0:
                dcorr = dcov_XY / np.sqrt(dvar_X * dvar_Y)
            else:
                dcorr = 0.0
            
            # Statistical significance testing
            p_value = self._dcorr_permutation_test(X, Y, dcorr, metric)
            
            # Bootstrap confidence intervals
            confidence_interval = self._dcorr_bootstrap_ci(X, Y, metric)
            
            # Additional statistics
            bias_corrected_dcorr = self._bias_corrected_dcorr(dcorr, n_samples)
            
            result = {
                'distance_correlation': float(dcorr),
                'bias_corrected_dcorr': float(bias_corrected_dcorr),
                'distance_covariance': float(dcov_XY),
                'distance_variance_X': float(dvar_X),
                'distance_variance_Y': float(dvar_Y),
                'p_value': float(p_value),
                'independent': p_value > self.significance_level,
                'confidence_interval': confidence_interval,
                'metric': metric,
                'n_samples': n_samples,
                'computation_time': time.time() - start_time
            }
            
            # Update performance metrics
            self.performance_monitor.record_operation("distance_correlation_test", time.time() - start_time)
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in distance correlation test: {e}")
            return {
                'distance_correlation': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': 'DistanceCorrelation_fallback'
            }
    
    def energy_statistics_test(self, X: np.ndarray, Y: np.ndarray, 
                              metric: str = 'euclidean') -> Dict[str, Any]:
        """
        Energy statistics test for independence
        
        Energy statistics use distances between sample points to test
        for independence and can detect any type of dependence.
        
        Args:
            X: First variable data
            Y: Second variable data
            metric: Distance metric to use
            
        Returns:
            Dictionary with test results
        """
        start_time = time.time()
        
        try:
            # Ensure data is 2D
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            n_samples = X.shape[0]
            
            # Compute distance matrices
            dist_X = self._compute_distance_matrix(X, metric)
            dist_Y = self._compute_distance_matrix(Y, metric)
            
            # Energy statistics
            energy_stat = self._compute_energy_statistic(dist_X, dist_Y, n_samples)
            
            # Normalized energy statistic
            normalized_energy = self._normalize_energy_statistic(energy_stat, n_samples)
            
            # Statistical significance testing
            p_value = self._energy_permutation_test(X, Y, energy_stat, metric)
            
            # Bootstrap confidence intervals
            confidence_interval = self._energy_bootstrap_ci(X, Y, metric)
            
            # Additional energy-based measures
            energy_measures = self._compute_additional_energy_measures(dist_X, dist_Y, n_samples)
            
            result = {
                'energy_statistic': float(energy_stat),
                'normalized_energy': float(normalized_energy),
                'p_value': float(p_value),
                'independent': p_value > self.significance_level,
                'confidence_interval': confidence_interval,
                'additional_measures': energy_measures,
                'metric': metric,
                'n_samples': n_samples,
                'computation_time': time.time() - start_time
            }
            
            # Update performance metrics
            self.performance_monitor.record_operation("energy_statistics_test", time.time() - start_time)
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in energy statistics test: {e}")
            return {
                'energy_statistic': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': 'EnergyStatistics_fallback'
            }
    
    def ball_statistics_test(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """
        Ball statistics test for independence
        
        Uses ball statistics which are based on the number of data points
        falling within balls of varying radii.
        """
        start_time = time.time()
        
        try:
            # Ensure data is 2D
            if X.ndim == 1:
                X = X.reshape(-1, 1)
            if Y.ndim == 1:
                Y = Y.reshape(-1, 1)
            
            n_samples = X.shape[0]
            
            # Standardize data
            X_std = (X - np.mean(X, axis=0)) / (np.std(X, axis=0) + 1e-10)
            Y_std = (Y - np.mean(Y, axis=0)) / (np.std(Y, axis=0) + 1e-10)
            
            # Ball statistic computation
            ball_stat = self._compute_ball_statistic(X_std, Y_std)
            
            # Statistical significance
            p_value = self._ball_permutation_test(X_std, Y_std, ball_stat)
            
            # Effect size measures
            effect_size = self._ball_effect_size(X_std, Y_std, ball_stat)
            
            result = {
                'ball_statistic': float(ball_stat),
                'effect_size': float(effect_size),
                'p_value': float(p_value),
                'independent': p_value > self.significance_level,
                'n_samples': n_samples,
                'computation_time': time.time() - start_time
            }
            
            # Update performance metrics
            self.performance_monitor.record_operation("ball_statistics_test", time.time() - start_time)
            
            return result
            
        except Exception as e:
            self.logger.error(f"Error in ball statistics test: {e}")
            return {
                'ball_statistic': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': 'BallStatistics_fallback'
            }
    
    def ensemble_distance_test(self, X: np.ndarray, Y: np.ndarray) -> Dict[str, Any]:
        """
        Ensemble distance-based independence test combining multiple methods
        """
        start_time = time.time()
        
        try:
            results = {}
            
            # Distance correlation with different metrics
            for metric in ['euclidean', 'manhattan', 'chebyshev']:
                try:
                    results[f'dcorr_{metric}'] = self.distance_correlation_test(X, Y, metric)
                except Exception as e:
                    self.logger.warning(f"Distance correlation with {metric} failed: {e}")
                    continue
            
            # Energy statistics
            try:
                results['energy'] = self.energy_statistics_test(X, Y)
            except Exception as e:
                self.logger.warning(f"Energy statistics failed: {e}")
            
            # Ball statistics
            try:
                results['ball'] = self.ball_statistics_test(X, Y)
            except Exception as e:
                self.logger.warning(f"Ball statistics failed: {e}")
            
            # Aggregate results
            if results:
                # Extract test statistics and p-values
                test_statistics = []
                p_values = []
                
                for key, result in results.items():
                    if 'error' not in result:
                        if 'distance_correlation' in result:
                            test_statistics.append(result['distance_correlation'])
                            p_values.append(result['p_value'])
                        elif 'energy_statistic' in result:
                            test_statistics.append(result['energy_statistic'])
                            p_values.append(result['p_value'])
                        elif 'ball_statistic' in result:
                            test_statistics.append(result['ball_statistic'])
                            p_values.append(result['p_value'])
                
                if test_statistics and p_values:
                    # Fisher's combined test
                    chi2_statistic = -2 * np.sum(np.log(np.array(p_values) + 1e-10))
                    from scipy.stats import chi2
                    combined_p_value = 1 - chi2.cdf(chi2_statistic, 2 * len(p_values))
                    
                    # Weighted average of test statistics
                    weights = [1.0 / (r.get('computation_time', 1.0) + 1e-6) 
                             for r in results.values() if 'error' not in r]
                    if len(weights) == len(test_statistics):
                        weighted_statistic = np.average(test_statistics, weights=weights)
                    else:
                        weighted_statistic = np.mean(test_statistics)
                else:
                    combined_p_value = 1.0
                    weighted_statistic = 0.0
                
                ensemble_result = {
                    'test_statistic': float(weighted_statistic),
                    'p_value': float(combined_p_value),
                    'independent': combined_p_value > self.significance_level,
                    'individual_results': results,
                    'method': 'EnsembleDistance',
                    'n_successful_tests': len(test_statistics),
                    'computation_time': time.time() - start_time
                }
                
                return ensemble_result
            else:
                raise RuntimeError("All distance-based tests failed")
                
        except Exception as e:
            self.logger.error(f"Error in ensemble distance test: {e}")
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'independent': True,
                'error': str(e),
                'method': 'EnsembleDistance_fallback'
            }


class CopulaBasedIndependenceTests:
    """
    Advanced copula-based independence testing methods with comprehensive 
    goodness-of-fit tests and parametric/non-parametric copula models.
    
    Implements:
    - Empirical copula construction
    - Parametric copula fitting (Gaussian, Clayton, Gumbel, Frank, Joe, etc.)
    - Archimedean copula families
    - Vine copulas for multivariate dependencies
    - Goodness-of-fit tests (Cramér-von Mises, Kolmogorov-Smirnov, Anderson-Darling)
    - Independence testing via copula parameter estimation
    - Bootstrap and permutation testing
    - Model selection via AIC/BIC/cross-validation
    """
    
    def __init__(self, performance_monitor=None, use_gpu=False):
        """Initialize copula-based independence testing framework."""
        self.performance_monitor = performance_monitor or PerformanceMonitor()
        self.use_gpu = use_gpu and self._check_gpu_availability()
        self.logger = logging.getLogger(__name__)
        
        # Initialize copula families and parameters
        self._initialize_copula_families()
        
        # Cache for fitted copulas
        self.copula_cache = {}
        
        self.logger.info(f"CopulaBasedIndependenceTests initialized with GPU={'enabled' if self.use_gpu else 'disabled'}")
    
    def _check_gpu_availability(self):
        """Check if GPU acceleration is available for copula computations."""
        try:
            import cupy as cp
            # Test GPU functionality
            test_array = cp.array([1, 2, 3])
            return True
        except Exception:
            return False
    
    def _initialize_copula_families(self):
        """Initialize available copula families and their parameter constraints."""
        self.copula_families = {
            'independence': {
                'params': [],
                'bounds': [],
                'generator': None,
                'generator_inv': None
            },
            'gaussian': {
                'params': ['rho'],
                'bounds': [(-0.99, 0.99)],
                'generator': None,  # Elliptical copula
                'generator_inv': None
            },
            'clayton': {
                'params': ['theta'],
                'bounds': [(0.01, 50.0)],
                'generator': lambda t, theta: (1/theta) * (t**(-theta) - 1),
                'generator_inv': lambda t, theta: (1 + theta * t)**(-1/theta)
            },
            'gumbel': {
                'params': ['theta'],
                'bounds': [(1.01, 50.0)],
                'generator': lambda t, theta: (-np.log(t))**theta,
                'generator_inv': lambda t, theta: np.exp(-(t**(1/theta)))
            },
            'frank': {
                'params': ['theta'],
                'bounds': [(-50.0, 50.0)],
                'generator': lambda t, theta: -np.log((np.exp(-theta*t) - 1)/(np.exp(-theta) - 1)) if theta != 0 else -np.log(t),
                'generator_inv': lambda t, theta: (-1/theta) * np.log(1 + np.exp(-t) * (np.exp(-theta) - 1)) if theta != 0 else np.exp(-t)
            },
            'joe': {
                'params': ['theta'],
                'bounds': [(1.01, 50.0)],
                'generator': lambda t, theta: -np.log(1 - (1-t)**theta),
                'generator_inv': lambda t, theta: 1 - (1 - np.exp(-t))**(1/theta)
            },
            'ami': {  # Ali-Mikhail-Haq
                'params': ['theta'],
                'bounds': [(-0.99, 0.99)],
                'generator': lambda t, theta: np.log((1 - theta*(1-t))/t),
                'generator_inv': lambda t, theta: (1 - theta)/(np.exp(t) - theta)
            }
        }
    
    def empirical_copula_test(self, X, Y, method='standard', n_bootstrap=1000, alpha=0.05):
        """
        Test independence using empirical copula with various test statistics.
        
        Parameters:
        -----------
        X, Y : array-like
            Input data vectors
        method : str
            Test method ('standard', 'spearman_footrule', 'blomqvist_beta')
        n_bootstrap : int
            Number of bootstrap samples
        alpha : float
            Significance level
            
        Returns:
        --------
        dict : Test results with p-value and test statistics
        """
        start_time = time.time()
        
        try:
            X = np.asarray(X).flatten()
            Y = np.asarray(Y).flatten()
            
            if len(X) != len(Y):
                raise ValueError("X and Y must have the same length")
            
            n = len(X)
            
            # Convert to pseudo-observations (empirical CDFs)
            U = self._to_pseudo_observations(X)
            V = self._to_pseudo_observations(Y)
            
            # Compute empirical copula
            empirical_copula = self._compute_empirical_copula(U, V)
            
            if method == 'standard':
                # Standard empirical copula independence test
                test_stat = self._empirical_copula_statistic(U, V)
                
            elif method == 'spearman_footrule':
                # Spearman's footrule test via copula
                test_stat = self._spearman_footrule_copula(U, V)
                
            elif method == 'blomqvist_beta':
                # Blomqvist's beta coefficient test
                test_stat = self._blomqvist_beta_test(U, V)
                
            else:
                raise ValueError(f"Unknown method: {method}")
            
            # Bootstrap p-value estimation
            bootstrap_stats = []
            for _ in range(n_bootstrap):
                # Generate independent samples
                boot_X = np.random.uniform(0, 1, n)
                boot_Y = np.random.uniform(0, 1, n)
                
                if method == 'standard':
                    boot_stat = self._empirical_copula_statistic(boot_X, boot_Y)
                elif method == 'spearman_footrule':
                    boot_stat = self._spearman_footrule_copula(boot_X, boot_Y)
                elif method == 'blomqvist_beta':
                    boot_stat = self._blomqvist_beta_test(boot_X, boot_Y)
                
                bootstrap_stats.append(boot_stat)
            
            # Calculate p-value
            p_value = np.mean(np.array(bootstrap_stats) >= test_stat)
            
            # Effect size estimation
            effect_size = self._compute_copula_effect_size(U, V, method)
            
            # Interpretation
            interpretation = self._interpret_copula_test(p_value, alpha, method)
            
            elapsed_time = time.time() - start_time
            if self.performance_monitor:
                self.performance_monitor.log_operation("empirical_copula_test", elapsed_time)
            
            return {
                'test_type': f'empirical_copula_{method}',
                'p_value': float(p_value),
                'test_statistic': float(test_stat),
                'effect_size': float(effect_size),
                'interpretation': interpretation,
                'method': method,
                'sample_size': n,
                'bootstrap_samples': n_bootstrap,
                'confidence_level': 1 - alpha,
                'execution_time': elapsed_time
            }
            
        except Exception as e:
            self.logger.error(f"Error in empirical_copula_test: {str(e)}")
            return {
                'test_type': f'empirical_copula_{method}',
                'p_value': 1.0,
                'test_statistic': 0.0,
                'effect_size': 0.0,
                'interpretation': 'Test failed',
                'error': str(e)
            }
    
    def parametric_copula_test(self, X, Y, copula_family='gaussian', method='maximum_likelihood', 
                             n_bootstrap=1000, alpha=0.05):
        """
        Test independence using parametric copula models with parameter estimation.
        
        Parameters:
        -----------
        X, Y : array-like
            Input data vectors
        copula_family : str
            Copula family ('gaussian', 'clayton', 'gumbel', 'frank', 'joe')
        method : str
            Parameter estimation method ('maximum_likelihood', 'method_of_moments', 'tau_inversion')
        n_bootstrap : int
            Number of bootstrap samples
        alpha : float
            Significance level
            
        Returns:
        --------
        dict : Test results with fitted parameters and goodness-of-fit measures
        """
        start_time = time.time()
        
        try:
            X = np.asarray(X).flatten()
            Y = np.asarray(Y).flatten()
            
            if len(X) != len(Y):
                raise ValueError("X and Y must have the same length")
            
            n = len(X)
            
            # Convert to pseudo-observations
            U = self._to_pseudo_observations(X)
            V = self._to_pseudo_observations(Y)
            
            # Fit copula parameters
            fitted_params = self._fit_copula_parameters(U, V, copula_family, method)
            
            # Test for independence (parameter = 0 or independence value)
            independence_value = self._get_independence_parameter_value(copula_family)
            
            # Compute test statistic (likelihood ratio or parameter-based)
            test_stat = self._compute_parametric_copula_statistic(
                U, V, copula_family, fitted_params, independence_value
            )
            
            # Bootstrap confidence interval and p-value
            bootstrap_params = []
            bootstrap_stats = []
            
            for _ in range(n_bootstrap):
                # Generate samples under independence hypothesis
                if copula_family == 'independence':
                    boot_U = np.random.uniform(0, 1, n)
                    boot_V = np.random.uniform(0, 1, n)
                else:
                    boot_U, boot_V = self._simulate_copula(n, copula_family, [independence_value])
                
                boot_params = self._fit_copula_parameters(boot_U, boot_V, copula_family, method)
                boot_stat = self._compute_parametric_copula_statistic(
                    boot_U, boot_V, copula_family, boot_params, independence_value
                )
                
                bootstrap_params.append(boot_params)
                bootstrap_stats.append(boot_stat)
            
            # Calculate p-value
            p_value = np.mean(np.array(bootstrap_stats) >= test_stat)
            
            # Goodness-of-fit tests
            gof_results = self._goodness_of_fit_tests(U, V, copula_family, fitted_params)
            
            # Parameter confidence intervals
            param_ci = self._parameter_confidence_intervals(bootstrap_params, alpha)
            
            # Effect size (dependence strength)
            effect_size = self._copula_dependence_measure(copula_family, fitted_params)
            
            # Model selection criteria
            aic = self._compute_aic(U, V, copula_family, fitted_params)
            bic = self._compute_bic(U, V, copula_family, fitted_params, n)
            
            elapsed_time = time.time() - start_time
            if self.performance_monitor:
                self.performance_monitor.log_operation("parametric_copula_test", elapsed_time)
            
            return {
                'test_type': f'parametric_copula_{copula_family}',
                'p_value': float(p_value),
                'test_statistic': float(test_stat),
                'effect_size': float(effect_size),
                'fitted_parameters': fitted_params,
                'parameter_ci': param_ci,
                'goodness_of_fit': gof_results,
                'aic': float(aic),
                'bic': float(bic),
                'copula_family': copula_family,
                'estimation_method': method,
                'sample_size': n,
                'bootstrap_samples': n_bootstrap,
                'confidence_level': 1 - alpha,
                'execution_time': elapsed_time,
                'interpretation': self._interpret_parametric_copula_test(
                    p_value, alpha, copula_family, fitted_params
                )
            }
            
        except Exception as e:
            self.logger.error(f"Error in parametric_copula_test: {str(e)}")
            return {
                'test_type': f'parametric_copula_{copula_family}',
                'p_value': 1.0,
                'test_statistic': 0.0,
                'effect_size': 0.0,
                'interpretation': 'Test failed',
                'error': str(e)
            }
    
    def goodness_of_fit_test(self, X, Y, copula_family, fitted_params=None, 
                           test_types=['cramer_von_mises', 'kolmogorov_smirnov', 'anderson_darling'],
                           n_bootstrap=1000, alpha=0.05):
        """
        Comprehensive goodness-of-fit tests for copula models.
        
        Parameters:
        -----------
        X, Y : array-like
            Input data vectors
        copula_family : str
            Copula family to test
        fitted_params : list, optional
            Pre-fitted parameters (if None, will estimate)
        test_types : list
            Types of GoF tests to perform
        n_bootstrap : int
            Number of bootstrap samples
        alpha : float
            Significance level
            
        Returns:
        --------
        dict : Comprehensive GoF test results
        """
        start_time = time.time()
        
        try:
            X = np.asarray(X).flatten()
            Y = np.asarray(Y).flatten()
            n = len(X)
            
            # Convert to pseudo-observations
            U = self._to_pseudo_observations(X)
            V = self._to_pseudo_observations(Y)
            
            # Fit parameters if not provided
            if fitted_params is None:
                fitted_params = self._fit_copula_parameters(U, V, copula_family, 'maximum_likelihood')
            
            gof_results = {}
            
            for test_type in test_types:
                if test_type == 'cramer_von_mises':
                    result = self._cramer_von_mises_copula_test(U, V, copula_family, fitted_params, n_bootstrap)
                elif test_type == 'kolmogorov_smirnov':
                    result = self._kolmogorov_smirnov_copula_test(U, V, copula_family, fitted_params, n_bootstrap)
                elif test_type == 'anderson_darling':
                    result = self._anderson_darling_copula_test(U, V, copula_family, fitted_params, n_bootstrap)
                else:
                    continue
                
                gof_results[test_type] = result
            
            # Overall assessment
            overall_p_value = np.mean([result['p_value'] for result in gof_results.values()])
            overall_assessment = 'Good fit' if overall_p_value > alpha else 'Poor fit'
            
            elapsed_time = time.time() - start_time
            if self.performance_monitor:
                self.performance_monitor.log_operation("goodness_of_fit_test", elapsed_time)
            
            return {
                'copula_family': copula_family,
                'fitted_parameters': fitted_params,
                'individual_tests': gof_results,
                'overall_p_value': float(overall_p_value),
                'overall_assessment': overall_assessment,
                'sample_size': n,
                'bootstrap_samples': n_bootstrap,
                'confidence_level': 1 - alpha,
                'execution_time': elapsed_time
            }
            
        except Exception as e:
            self.logger.error(f"Error in goodness_of_fit_test: {str(e)}")
            return {
                'copula_family': copula_family,
                'error': str(e),
                'overall_assessment': 'Test failed'
            }
    
    def vine_copula_test(self, data_matrix, vine_structure='c_vine', n_bootstrap=500, alpha=0.05):
        """
        Test independence using vine copula models for multivariate dependencies.
        
        Parameters:
        -----------
        data_matrix : array-like, shape (n_samples, n_features)
            Multivariate data matrix
        vine_structure : str
            Type of vine structure ('c_vine', 'd_vine', 'r_vine')
        n_bootstrap : int
            Number of bootstrap samples
        alpha : float
            Significance level
            
        Returns:
        --------
        dict : Vine copula test results with conditional independence assessments
        """
        start_time = time.time()
        
        try:
            data_matrix = np.asarray(data_matrix)
            if data_matrix.ndim != 2:
                raise ValueError("Data matrix must be 2-dimensional")
            
            n_samples, n_features = data_matrix.shape
            
            if n_features < 3:
                raise ValueError("Vine copula requires at least 3 variables")
            
            # Convert to pseudo-observations
            pseudo_data = np.zeros_like(data_matrix)
            for i in range(n_features):
                pseudo_data[:, i] = self._to_pseudo_observations(data_matrix[:, i])
            
            # Build vine structure
            vine_tree = self._build_vine_structure(pseudo_data, vine_structure)
            
            # Estimate pair-copulas for each tree level
            fitted_copulas = self._estimate_vine_copulas(pseudo_data, vine_tree)
            
            # Test overall independence
            test_statistics = []
            p_values = []
            
            # Test each pair-copula for independence
            for tree_level, tree_copulas in fitted_copulas.items():
                for edge, copula_result in tree_copulas.items():
                    # Test if this copula represents independence
                    edge_test_stat = self._test_pair_copula_independence(copula_result)
                    test_statistics.append(edge_test_stat['test_statistic'])
                    p_values.append(edge_test_stat['p_value'])
            
            # Combine p-values using Fisher's method
            if p_values:
                chi2_statistic = -2 * np.sum(np.log(np.array(p_values) + 1e-10))
                from scipy.stats import chi2
                combined_p_value = 1 - chi2.cdf(chi2_statistic, 2 * len(p_values))
            else:
                combined_p_value = 1.0
            
            # Bootstrap test for vine copula
            bootstrap_stats = []
            for _ in range(n_bootstrap):
                # Generate independent multivariate samples
                boot_data = np.random.uniform(0, 1, (n_samples, n_features))
                boot_vine_tree = self._build_vine_structure(boot_data, vine_structure)
                boot_fitted = self._estimate_vine_copulas(boot_data, boot_vine_tree)
                
                boot_stats = []
                for tree_level, tree_copulas in boot_fitted.items():
                    for edge, copula_result in tree_copulas.items():
                        edge_test = self._test_pair_copula_independence(copula_result)
                        boot_stats.append(edge_test['test_statistic'])
                
                if boot_stats:
                    bootstrap_stats.append(np.mean(boot_stats))
            
            # Calculate bootstrap p-value
            observed_mean_stat = np.mean(test_statistics) if test_statistics else 0.0
            bootstrap_p_value = np.mean(np.array(bootstrap_stats) >= observed_mean_stat) if bootstrap_stats else 1.0
            
            elapsed_time = time.time() - start_time
            if self.performance_monitor:
                self.performance_monitor.log_operation("vine_copula_test", elapsed_time)
            
            return {
                'test_type': f'vine_copula_{vine_structure}',
                'combined_p_value': float(combined_p_value),
                'bootstrap_p_value': float(bootstrap_p_value),
                'overall_test_statistic': float(observed_mean_stat),
                'individual_statistics': test_statistics,
                'individual_p_values': p_values,
                'vine_structure': vine_structure,
                'fitted_copulas': fitted_copulas,
                'n_variables': n_features,
                'sample_size': n_samples,
                'bootstrap_samples': n_bootstrap,
                'confidence_level': 1 - alpha,
                'execution_time': elapsed_time,
                'interpretation': self._interpret_vine_copula_test(combined_p_value, alpha)
            }
            
        except Exception as e:
            self.logger.error(f"Error in vine_copula_test: {str(e)}")
            return {
                'test_type': f'vine_copula_{vine_structure}',
                'combined_p_value': 1.0,
                'overall_test_statistic': 0.0,
                'interpretation': 'Test failed',
                'error': str(e)
            }
    
    def ensemble_copula_test(self, X, Y, copula_families=['gaussian', 'clayton', 'gumbel', 'frank'],
                           selection_criterion='aic', n_bootstrap=500, alpha=0.05):
        """
        Ensemble independence testing using multiple copula families with model selection.
        
        Parameters:
        -----------
        X, Y : array-like
            Input data vectors
        copula_families : list
            List of copula families to test
        selection_criterion : str
            Model selection criterion ('aic', 'bic', 'cross_validation')
        n_bootstrap : int
            Number of bootstrap samples
        alpha : float
            Significance level
            
        Returns:
        --------
        dict : Ensemble test results with best model selection
        """
        start_time = time.time()
        
        try:
            X = np.asarray(X).flatten()
            Y = np.asarray(Y).flatten()
            n = len(X)
            
            # Convert to pseudo-observations
            U = self._to_pseudo_observations(X)
            V = self._to_pseudo_observations(Y)
            
            # Test each copula family
            family_results = {}
            selection_scores = {}
            
            for family in copula_families:
                try:
                    # Fit copula and compute test
                    result = self.parametric_copula_test(X, Y, family, 'maximum_likelihood', n_bootstrap, alpha)
                    family_results[family] = result
                    
                    # Compute selection score
                    if selection_criterion == 'aic':
                        selection_scores[family] = result.get('aic', np.inf)
                    elif selection_criterion == 'bic':
                        selection_scores[family] = result.get('bic', np.inf)
                    elif selection_criterion == 'cross_validation':
                        cv_score = self._cross_validate_copula(U, V, family)
                        selection_scores[family] = -cv_score  # Negative for minimization
                        
                except Exception as e:
                    self.logger.warning(f"Failed to fit {family} copula: {str(e)}")
                    continue
            
            if not family_results:
                raise RuntimeError("All copula families failed to fit")
            
            # Select best model
            best_family = min(selection_scores.keys(), key=lambda k: selection_scores[k])
            best_result = family_results[best_family]
            
            # Ensemble p-value using multiple testing correction
            p_values = [result['p_value'] for result in family_results.values()]
            
            # Bonferroni correction
            bonferroni_p = min(1.0, min(p_values) * len(p_values))
            
            # Benjamin-Hochberg (FDR) correction
            sorted_p = sorted(p_values)
            m = len(sorted_p)
            fdr_p = min(1.0, min([sorted_p[i] * m / (i + 1) for i in range(m)]))
            
            # Fisher's combined test
            chi2_statistic = -2 * np.sum(np.log(np.array(p_values) + 1e-10))
            from scipy.stats import chi2
            fisher_p = 1 - chi2.cdf(chi2_statistic, 2 * len(p_values))
            
            # Weighted ensemble based on model selection scores
            weights = self._compute_model_weights(selection_scores)
            weighted_p_value = np.sum([weights[family] * family_results[family]['p_value'] 
                                     for family in weights.keys()])
            
            elapsed_time = time.time() - start_time
            if self.performance_monitor:
                self.performance_monitor.log_operation("ensemble_copula_test", elapsed_time)
            
            return {
                'test_type': 'ensemble_copula',
                'best_model': best_family,
                'best_result': best_result,
                'all_results': family_results,
                'selection_scores': selection_scores,
                'model_weights': weights,
                'bonferroni_p_value': float(bonferroni_p),
                'fdr_p_value': float(fdr_p),
                'fisher_p_value': float(fisher_p),
                'weighted_p_value': float(weighted_p_value),
                'selection_criterion': selection_criterion,
                'n_models_tested': len(family_results),
                'sample_size': n,
                'bootstrap_samples': n_bootstrap,
                'confidence_level': 1 - alpha,
                'execution_time': elapsed_time,
                'interpretation': self._interpret_ensemble_copula_test(
                    best_result['p_value'], weighted_p_value, alpha, best_family
                )
            }
            
        except Exception as e:
            self.logger.error(f"Error in ensemble_copula_test: {str(e)}")
            return {
                'test_type': 'ensemble_copula',
                'weighted_p_value': 1.0,
                'interpretation': 'Test failed',
                'error': str(e)
            }
    
    # Helper methods for copula computations
    def _to_pseudo_observations(self, X):
        """Convert data to pseudo-observations (empirical CDF values)."""
        n = len(X)
        ranks = np.argsort(np.argsort(X))
        return (ranks + 1) / (n + 1)
    
    def _compute_empirical_copula(self, U, V):
        """Compute empirical copula from pseudo-observations."""
        n = len(U)
        # Grid-based empirical copula
        grid_size = min(50, n // 4)  # Adaptive grid size
        u_grid = np.linspace(0, 1, grid_size)
        v_grid = np.linspace(0, 1, grid_size)
        
        copula_values = np.zeros((grid_size, grid_size))
        for i, u in enumerate(u_grid):
            for j, v in enumerate(v_grid):
                copula_values[i, j] = np.mean((U <= u) & (V <= v))
        
        return copula_values
    
    def _empirical_copula_statistic(self, U, V):
        """Compute test statistic based on empirical copula departure from independence."""
        n = len(U)
        # Cramér-von Mises statistic for empirical copula
        statistic = 0.0
        for i in range(n):
            for j in range(n):
                empirical_copula_val = np.mean((U <= U[i]) & (V <= V[j]))
                independence_val = U[i] * V[j]  # Product copula (independence)
                statistic += (empirical_copula_val - independence_val) ** 2
        
        return statistic / (n * n)
    
    def _spearman_footrule_copula(self, U, V):
        """Spearman's footrule test via copula representation."""
        n = len(U)
        ranks_U = np.argsort(np.argsort(U)) + 1
        ranks_V = np.argsort(np.argsort(V)) + 1
        
        # Footrule distance
        footrule = np.sum(np.abs(ranks_U - ranks_V))
        # Normalize by maximum possible distance
        max_footrule = n * n / 2 if n % 2 == 0 else (n * n - 1) / 2
        
        return footrule / max_footrule
    
    def _blomqvist_beta_test(self, U, V):
        """Blomqvist's beta coefficient test for independence."""
        n = len(U)
        # Count concordant pairs in quadrants
        concordant = np.sum(((U > 0.5) & (V > 0.5)) | ((U <= 0.5) & (V <= 0.5)))
        beta = (2 * concordant / n) - 1
        
        return np.abs(beta)  # Test statistic
    
    def _fit_copula_parameters(self, U, V, copula_family, method='maximum_likelihood'):
        """Fit copula parameters using specified estimation method."""
        if copula_family == 'independence':
            return []
        
        try:
            if method == 'maximum_likelihood':
                return self._maximum_likelihood_estimation(U, V, copula_family)
            elif method == 'method_of_moments':
                return self._method_of_moments_estimation(U, V, copula_family)
            elif method == 'tau_inversion':
                return self._tau_inversion_estimation(U, V, copula_family)
            else:
                raise ValueError(f"Unknown estimation method: {method}")
                
        except Exception as e:
            self.logger.warning(f"Parameter estimation failed for {copula_family}: {str(e)}")
            # Return independence parameters as fallback
            return [0.0] if copula_family in ['gaussian', 'frank', 'ami'] else [1.0]
    
    def _maximum_likelihood_estimation(self, U, V, copula_family):
        """Maximum likelihood estimation for copula parameters."""
        from scipy.optimize import minimize_scalar, minimize
        
        def negative_log_likelihood(params):
            try:
                log_likelihood = self._copula_log_likelihood(U, V, copula_family, params)
                return -log_likelihood
            except:
                return np.inf
        
        bounds = self.copula_families[copula_family]['bounds']
        
        if len(bounds) == 1:
            # Single parameter copula
            result = minimize_scalar(negative_log_likelihood, bounds=bounds[0], method='bounded')
            return [result.x] if result.success else [0.0]
        else:
            # Multi-parameter copula
            result = minimize(negative_log_likelihood, x0=[0.5] * len(bounds), 
                            bounds=bounds, method='L-BFGS-B')
            return result.x.tolist() if result.success else [0.0] * len(bounds)
    
    def _copula_log_likelihood(self, U, V, copula_family, params):
        """Compute log-likelihood for copula model."""
        n = len(U)
        
        if copula_family == 'gaussian':
            rho = params[0]
            from scipy.stats import norm
            z_u = norm.ppf(U)
            z_v = norm.ppf(V)
            
            log_pdf = -0.5 * np.log(1 - rho**2) - \
                      (rho**2 * (z_u**2 + z_v**2) - 2 * rho * z_u * z_v) / (2 * (1 - rho**2))
            
            return np.sum(log_pdf)
            
        elif copula_family == 'clayton':
            theta = params[0]
            if theta <= 0:
                return -np.inf
            
            log_pdf = np.log(1 + theta) + \
                      -(1 + theta) * (np.log(U) + np.log(V)) + \
                      -(2 + 1/theta) * np.log(U**(-theta) + V**(-theta) - 1)
            
            return np.sum(log_pdf)
            
        elif copula_family == 'gumbel':
            theta = params[0]
            if theta < 1:
                return -np.inf
            
            log_u = np.log(U)
            log_v = np.log(V)
            
            log_pdf = np.log(theta - 1) + \
                      (theta - 1) * (log_u + log_v) + \
                      (1 - 2*theta) * np.log(-log_u) + \
                      (1 - 2*theta) * np.log(-log_v) + \
                      -(-log_u)**theta - (-log_v)**theta + \
                      ((-log_u)**theta + (-log_v)**theta)**(1/theta)
            
            return np.sum(log_pdf)
            
        else:
            # Fallback for other copula families
            return 0.0
    
    def _method_of_moments_estimation(self, U, V, copula_family):
        """Method of moments estimation based on rank correlations."""
        # Compute Kendall's tau
        from scipy.stats import kendalltau
        tau, _ = kendalltau(U, V)
        
        if copula_family == 'gaussian':
            # Gaussian copula: rho = sin(pi * tau / 2)
            rho = np.sin(np.pi * tau / 2)
            return [max(-0.99, min(0.99, rho))]
            
        elif copula_family == 'clayton':
            # Clayton copula: theta = 2 * tau / (1 - tau)
            theta = 2 * tau / (1 - tau) if tau < 1 else 50.0
            return [max(0.01, min(50.0, theta))]
            
        elif copula_family == 'gumbel':
            # Gumbel copula: theta = 1 / (1 - tau)
            theta = 1 / (1 - tau) if tau < 1 else 50.0
            return [max(1.01, min(50.0, theta))]
            
        elif copula_family == 'frank':
            # Frank copula: approximate relationship
            if abs(tau) < 0.01:
                return [0.0]
            else:
                # Approximation for Frank copula
                theta = 4 * tau / (1 - tau) if tau != 1 else 50.0
                return [max(-50.0, min(50.0, theta))]
                
        else:
            return [0.0]
    
    def _tau_inversion_estimation(self, U, V, copula_family):
        """Tau inversion method for copula parameter estimation."""
        return self._method_of_moments_estimation(U, V, copula_family)  # Same as MoM for simplicity
    
    def _get_independence_parameter_value(self, copula_family):
        """Get parameter value corresponding to independence for each copula family."""
        if copula_family in ['gaussian', 'frank', 'ami']:
            return 0.0  # Zero correlation/dependence parameter
        elif copula_family in ['clayton', 'gumbel', 'joe']:
            return 1.0 if copula_family == 'gumbel' else 0.0
        else:
            return 0.0
    
    def _compute_parametric_copula_statistic(self, U, V, copula_family, fitted_params, independence_value):
        """Compute test statistic for parametric copula independence test."""
        try:
            if not fitted_params:
                return 0.0
            
            param_value = fitted_params[0]
            
            # Test statistic based on distance from independence value
            if copula_family == 'gaussian':
                # Fisher's z-transformation for correlation
                n = len(U)
                z_stat = 0.5 * np.log((1 + param_value) / (1 - param_value))
                return abs(z_stat) * np.sqrt(n - 3)
                
            else:
                # Generic test based on parameter magnitude
                return abs(param_value - independence_value)
                
        except Exception:
            return 0.0
    
    def _goodness_of_fit_tests(self, U, V, copula_family, fitted_params):
        """Run multiple goodness-of-fit tests for the fitted copula."""
        results = {}
        
        try:
            # Cramér-von Mises test
            results['cramer_von_mises'] = self._cramer_von_mises_copula_test(U, V, copula_family, fitted_params, 200)
            
            # Kolmogorov-Smirnov test
            results['kolmogorov_smirnov'] = self._kolmogorov_smirnov_copula_test(U, V, copula_family, fitted_params, 200)
            
            # Anderson-Darling test
            results['anderson_darling'] = self._anderson_darling_copula_test(U, V, copula_family, fitted_params, 200)
            
        except Exception as e:
            self.logger.warning(f"GoF tests failed: {str(e)}")
            
        return results
    
    def _cramer_von_mises_copula_test(self, U, V, copula_family, fitted_params, n_bootstrap):
        """Cramér-von Mises goodness-of-fit test for copulas."""
        try:
            n = len(U)
            
            # Compute empirical copula
            empirical_copula = self._compute_empirical_copula(U, V)
            
            # Compute theoretical copula values
            theoretical_copula = self._compute_theoretical_copula(U, V, copula_family, fitted_params)
            
            # CvM statistic
            cvm_statistic = np.sum((empirical_copula - theoretical_copula) ** 2)
            
            # Bootstrap p-value
            bootstrap_stats = []
            for _ in range(n_bootstrap):
                # Generate data from fitted copula
                boot_U, boot_V = self._simulate_copula(n, copula_family, fitted_params)
                boot_empirical = self._compute_empirical_copula(boot_U, boot_V)
                boot_theoretical = self._compute_theoretical_copula(boot_U, boot_V, copula_family, fitted_params)
                boot_stat = np.sum((boot_empirical - boot_theoretical) ** 2)
                bootstrap_stats.append(boot_stat)
            
            p_value = np.mean(np.array(bootstrap_stats) >= cvm_statistic)
            
            return {
                'test_statistic': float(cvm_statistic),
                'p_value': float(p_value),
                'test_type': 'cramer_von_mises'
            }
            
        except Exception as e:
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'test_type': 'cramer_von_mises',
                'error': str(e)
            }
    
    def _kolmogorov_smirnov_copula_test(self, U, V, copula_family, fitted_params, n_bootstrap):
        """Kolmogorov-Smirnov goodness-of-fit test for copulas."""
        try:
            n = len(U)
            
            # Compute empirical and theoretical copula CDFs
            empirical_copula = self._compute_empirical_copula(U, V)
            theoretical_copula = self._compute_theoretical_copula(U, V, copula_family, fitted_params)
            
            # KS statistic (maximum absolute difference)
            ks_statistic = np.max(np.abs(empirical_copula - theoretical_copula))
            
            # Bootstrap p-value
            bootstrap_stats = []
            for _ in range(n_bootstrap):
                boot_U, boot_V = self._simulate_copula(n, copula_family, fitted_params)
                boot_empirical = self._compute_empirical_copula(boot_U, boot_V)
                boot_theoretical = self._compute_theoretical_copula(boot_U, boot_V, copula_family, fitted_params)
                boot_stat = np.max(np.abs(boot_empirical - boot_theoretical))
                bootstrap_stats.append(boot_stat)
            
            p_value = np.mean(np.array(bootstrap_stats) >= ks_statistic)
            
            return {
                'test_statistic': float(ks_statistic),
                'p_value': float(p_value),
                'test_type': 'kolmogorov_smirnov'
            }
            
        except Exception as e:
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'test_type': 'kolmogorov_smirnov',
                'error': str(e)
            }
    
    def _anderson_darling_copula_test(self, U, V, copula_family, fitted_params, n_bootstrap):
        """Anderson-Darling goodness-of-fit test for copulas."""
        try:
            n = len(U)
            
            # Simplified Anderson-Darling test for copulas
            # (full implementation would require more complex integration)
            empirical_copula = self._compute_empirical_copula(U, V)
            theoretical_copula = self._compute_theoretical_copula(U, V, copula_family, fitted_params)
            
            # Simplified AD statistic
            differences = empirical_copula - theoretical_copula
            weights = 1.0 / (theoretical_copula * (1 - theoretical_copula) + 1e-10)
            ad_statistic = np.sum(weights * differences ** 2)
            
            # Bootstrap p-value
            bootstrap_stats = []
            for _ in range(n_bootstrap):
                boot_U, boot_V = self._simulate_copula(n, copula_family, fitted_params)
                boot_empirical = self._compute_empirical_copula(boot_U, boot_V)
                boot_theoretical = self._compute_theoretical_copula(boot_U, boot_V, copula_family, fitted_params)
                boot_diff = boot_empirical - boot_theoretical
                boot_weights = 1.0 / (boot_theoretical * (1 - boot_theoretical) + 1e-10)
                boot_stat = np.sum(boot_weights * boot_diff ** 2)
                bootstrap_stats.append(boot_stat)
            
            p_value = np.mean(np.array(bootstrap_stats) >= ad_statistic)
            
            return {
                'test_statistic': float(ad_statistic),
                'p_value': float(p_value),
                'test_type': 'anderson_darling'
            }
            
        except Exception as e:
            return {
                'test_statistic': 0.0,
                'p_value': 1.0,
                'test_type': 'anderson_darling',
                'error': str(e)
            }
    
    def _compute_theoretical_copula(self, U, V, copula_family, fitted_params):
        """Compute theoretical copula values for given parameters."""
        try:
            if copula_family == 'independence':
                return np.outer(U, V)  # Product copula
            
            # For other copulas, use approximation based on empirical structure
            # (Full implementation would require copula CDF computation)
            empirical_copula = self._compute_empirical_copula(U, V)
            return empirical_copula  # Simplified fallback
            
        except Exception:
            return np.outer(U, V)  # Fallback to independence
    
    def _simulate_copula(self, n, copula_family, params):
        """Simulate samples from specified copula."""
        try:
            if copula_family == 'independence':
                return np.random.uniform(0, 1, n), np.random.uniform(0, 1, n)
            
            elif copula_family == 'gaussian' and len(params) == 1:
                rho = params[0]
                from scipy.stats import multivariate_normal, norm
                samples = multivariate_normal.rvs([0, 0], [[1, rho], [rho, 1]], n)
                U = norm.cdf(samples[:, 0])
                V = norm.cdf(samples[:, 1])
                return U, V
            
            else:
                # Fallback to independence for complex copulas
                return np.random.uniform(0, 1, n), np.random.uniform(0, 1, n)
                
        except Exception:
            return np.random.uniform(0, 1, n), np.random.uniform(0, 1, n)
    
    def _parameter_confidence_intervals(self, bootstrap_params, alpha):
        """Compute confidence intervals for copula parameters."""
        try:
            if not bootstrap_params or not bootstrap_params[0]:
                return []
            
            n_params = len(bootstrap_params[0])
            confidence_intervals = []
            
            for i in range(n_params):
                param_values = [params[i] for params in bootstrap_params if len(params) > i]
                if param_values:
                    lower = np.percentile(param_values, 100 * alpha / 2)
                    upper = np.percentile(param_values, 100 * (1 - alpha / 2))
                    confidence_intervals.append((lower, upper))
                else:
                    confidence_intervals.append((0.0, 0.0))
            
            return confidence_intervals
            
        except Exception:
            return []
    
    def _copula_dependence_measure(self, copula_family, fitted_params):
        """Compute dependence measure for fitted copula."""
        try:
            if not fitted_params:
                return 0.0
            
            param = fitted_params[0]
            
            if copula_family == 'gaussian':
                return abs(param)  # Absolute correlation
            elif copula_family in ['clayton', 'gumbel', 'frank']:
                # Convert to Kendall's tau approximation
                if copula_family == 'clayton':
                    tau = param / (param + 2) if param > 0 else 0.0
                elif copula_family == 'gumbel':
                    tau = (param - 1) / param if param > 1 else 0.0
                else:  # frank
                    tau = param / 4 if abs(param) < 1 else 0.25 * np.sign(param)
                return abs(tau)
            else:
                return abs(param)
                
        except Exception:
            return 0.0
    
    def _compute_aic(self, U, V, copula_family, fitted_params):
        """Compute Akaike Information Criterion."""
        try:
            log_likelihood = self._copula_log_likelihood(U, V, copula_family, fitted_params)
            n_params = len(fitted_params)
            return 2 * n_params - 2 * log_likelihood
        except Exception:
            return np.inf
    
    def _compute_bic(self, U, V, copula_family, fitted_params, n):
        """Compute Bayesian Information Criterion."""
        try:
            log_likelihood = self._copula_log_likelihood(U, V, copula_family, fitted_params)
            n_params = len(fitted_params)
            return np.log(n) * n_params - 2 * log_likelihood
        except Exception:
            return np.inf
    
    def _cross_validate_copula(self, U, V, copula_family, k_folds=5):
        """Cross-validation score for copula model."""
        try:
            n = len(U)
            indices = np.arange(n)
            np.random.shuffle(indices)
            
            fold_size = n // k_folds
            cv_scores = []
            
            for i in range(k_folds):
                # Split data
                test_start = i * fold_size
                test_end = (i + 1) * fold_size if i < k_folds - 1 else n
                
                test_indices = indices[test_start:test_end]
                train_indices = np.concatenate([indices[:test_start], indices[test_end:]])
                
                U_train, V_train = U[train_indices], V[train_indices]
                U_test, V_test = U[test_indices], V[test_indices]
                
                # Fit on training data
                params = self._fit_copula_parameters(U_train, V_train, copula_family)
                
                # Evaluate on test data
                log_likelihood = self._copula_log_likelihood(U_test, V_test, copula_family, params)
                cv_scores.append(log_likelihood)
            
            return np.mean(cv_scores)
            
        except Exception:
            return -np.inf
    
    def _compute_model_weights(self, selection_scores):
        """Compute model weights based on selection scores."""
        try:
            # Convert to weights using exponential of negative scores
            scores = np.array(list(selection_scores.values()))
            min_score = np.min(scores)
            exp_scores = np.exp(-(scores - min_score))
            normalized_weights = exp_scores / np.sum(exp_scores)
            
            weights = {}
            for i, family in enumerate(selection_scores.keys()):
                weights[family] = normalized_weights[i]
            
            return weights
            
        except Exception:
            # Equal weights fallback
            n_models = len(selection_scores)
            return {family: 1.0 / n_models for family in selection_scores.keys()}
    
    def _interpret_copula_test(self, p_value, alpha, method):
        """Interpret copula-based independence test results."""
        if p_value <= alpha:
            return f"Reject independence hypothesis (p={p_value:.4f} <= {alpha})"
        else:
            return f"Fail to reject independence hypothesis (p={p_value:.4f} > {alpha})"
    
    def _interpret_parametric_copula_test(self, p_value, alpha, copula_family, fitted_params):
        """Interpret parametric copula test results."""
        base_interpretation = self._interpret_copula_test(p_value, alpha, 'parametric')
        param_info = f"Fitted {copula_family} copula with parameters: {fitted_params}"
        return f"{base_interpretation}. {param_info}"
    
    def _interpret_vine_copula_test(self, p_value, alpha):
        """Interpret vine copula test results."""
        return self._interpret_copula_test(p_value, alpha, 'vine_copula')
    
    def _interpret_ensemble_copula_test(self, best_p_value, weighted_p_value, alpha, best_family):
        """Interpret ensemble copula test results."""
        best_interp = self._interpret_copula_test(best_p_value, alpha, 'best_model')
        weighted_interp = self._interpret_copula_test(weighted_p_value, alpha, 'ensemble')
        return f"Best model ({best_family}): {best_interp}. Ensemble result: {weighted_interp}"
    
